"use client";

/* ============================================================================
   SURFACES, RULES, PLATES, STATUS
   The four archetypes plus the signature devices built on them.
   ========================================================================= */

import { useCallback, useState, type ReactNode, type HTMLAttributes } from "react";
import { Icon, type IconName } from "./Icon";

export type Tone = "neutral" | "signal" | "success" | "warning" | "danger" | "ai";

/* One status table for the whole product. The old portal had this map
   redefined privately in 20 files, which is why a "running" server was a
   different green depending on which page you were looking at. */
export const STATUS_TONE: Record<string, { tone: Tone; label: string; live?: boolean }> = {
  running:      { tone: "success", label: "Running" },
  active:       { tone: "success", label: "Active" },
  ready:        { tone: "success", label: "Ready" },
  healthy:      { tone: "success", label: "Healthy" },
  provisioning: { tone: "signal",  label: "Provisioning", live: true },
  pending:      { tone: "signal",  label: "Pending", live: true },
  reinstalling: { tone: "signal",  label: "Reinstalling", live: true },
  deleting:     { tone: "danger",  label: "Deleting", live: true },
  stopped:      { tone: "neutral", label: "Stopped" },
  suspended:    { tone: "warning", label: "Suspended" },
  expiring:     { tone: "warning", label: "Expiring" },
  degraded:     { tone: "warning", label: "Degraded" },
  error:        { tone: "danger",  label: "Error" },
  failed:       { tone: "danger",  label: "Failed" },
};

export const TONE_TEXT: Record<Tone, string> = {
  neutral: "text-ink-muted",
  signal:  "text-signal-text",
  success: "text-success-text",
  warning: "text-warning-text",
  danger:  "text-danger-text",
  ai:      "text-ai-text",
};

const TONE_CHIP: Record<Tone, string> = {
  neutral: "border-hairline-strong text-ink-secondary",
  signal:  "border-signal-edge/45 text-signal-text",
  success: "border-success-text/40 text-success-text",
  warning: "border-warning-text/40 text-warning-text",
  danger:  "border-danger-text/40 text-danger-text",
  ai:      "border-ai-text/40 text-ai-text",
};

/* ---------------------------------------------------------------- OBJECT */
interface ObjectSurfaceProps extends HTMLAttributes<HTMLDivElement> {
  status?: keyof typeof STATUS_TONE;
  interactive?: boolean;
  children: ReactNode;
}
/** A thing the customer owns. The notch and the filament belong to this and
    to nothing else, so both read as "yours" without a label. */
export function ObjectSurface({
  status, interactive, className = "", children, ...rest
}: ObjectSurfaceProps) {
  const s = status ? STATUS_TONE[status] : undefined;
  return (
    <div
      className={`nx-object ${interactive ? "nx-object-interactive" : ""} ${className}`}
      {...rest}
    >
      {s && (
        <span
          className={`nx-filament ${TONE_TEXT[s.tone]}`}
          data-live={s.live ? "true" : "false"}
          aria-hidden="true"
        />
      )}
      {children}
    </div>
  );
}

/* ------------------------------------------------------------- CONTAINER */
/** Groups information. Deliberately plainer than an object — this is what
    stops every paragraph in the portal from becoming a bordered rectangle. */
export function Container({ className = "", children, ...rest }: HTMLAttributes<HTMLDivElement>) {
  return (
    <div className={`nx-container-surface ${className}`} {...rest}>{children}</div>
  );
}

/* ----------------------------------------------------------------- RULE */
export function SectionRule({ label, action }: { label: string; action?: ReactNode }) {
  return (
    <div className="nx-rule my-5 first:mt-0">
      <span className="nx-rule-label">{label}</span>
      {action && <div className="order-last shrink-0 pl-3">{action}</div>}
    </div>
  );
}

/* ---------------------------------------------------------------- PLATE */
interface DataPlateProps {
  label?: string;
  value: string;
  /** Renders a copy affordance. Technical values almost always want one. */
  copyable?: boolean;
  masked?: boolean;
  className?: string;
}
/** Every technical value in the product renders here: addresses, commands,
    identifiers, node names, ports, DNS values, hashes. One treatment, so
    infrastructure data looks like infrastructure data. */
export function DataPlate({ label, value, copyable = true, masked = false, className = "" }: DataPlateProps) {
  const [revealed, setRevealed] = useState(!masked);
  const shown = revealed ? value : "•".repeat(Math.min(value.length, 18));
  return (
    <div className={className}>
      {label && (
        <div className="mb-1.5 font-display text-label uppercase tracking-[0.11em] text-ink-muted">
          {label}
        </div>
      )}
      <div className="nx-plate flex items-center gap-2 px-3 py-2">
        <code className="min-w-0 flex-1 overflow-x-auto whitespace-nowrap text-ink">{shown}</code>
        {masked && (
          <button
            type="button"
            onClick={() => setRevealed((v) => !v)}
            className="shrink-0 rounded-sm px-1.5 py-0.5 font-display text-label uppercase tracking-[0.11em] text-ink-muted transition-colors duration-[var(--nx-dur-1)] hover:text-ink"
          >
            {revealed ? "Hide" : "Show"}
          </button>
        )}
        {copyable && <CopyButton value={value} />}
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------- COPY */
/** One copy interaction for the product. The old portal had thirteen, each
    with its own confirmation behaviour. */
export function CopyButton({ value, label = "Copy" }: { value: string; label?: string }) {
  const [done, setDone] = useState(false);
  const copy = useCallback(() => {
    void navigator.clipboard?.writeText(value).then(() => {
      setDone(true);
      window.setTimeout(() => setDone(false), 1600);
    });
  }, [value]);
  return (
    <button
      type="button"
      onClick={copy}
      className={`shrink-0 rounded-sm p-1 transition-colors duration-[var(--nx-dur-1)] ${
        done ? "text-success-text" : "text-ink-muted hover:text-ink"
      }`}
      aria-label={done ? "Copied" : label}
    >
      <Icon name={done ? "check" : "copy"} size="sm" />
    </button>
  );
}

/* --------------------------------------------------------------- BADGE */
export function Badge({
  children, tone = "neutral", size = "md", icon,
}: { children: ReactNode; tone?: Tone; size?: "sm" | "md"; icon?: IconName }) {
  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-sm border bg-transparent font-display font-semibold uppercase tracking-[0.09em] ${TONE_CHIP[tone]} ${
        size === "sm" ? "px-1.5 py-0.5 text-[0.6875rem]" : "px-2 py-1 text-label"
      }`}
    >
      {icon && <Icon name={icon} size="sm" />}
      {children}
    </span>
  );
}

/* ------------------------------------------------------ STATUS INDICATOR */
/** State is encoded in form as well as colour: a live state animates, a
    steady state does not, so the difference survives a greyscale screenshot. */
export function StatusIndicator({
  status, showLabel = true, size = "md",
}: { status: keyof typeof STATUS_TONE; showLabel?: boolean; size?: "sm" | "md" }) {
  const s = STATUS_TONE[status] ?? { tone: "neutral" as Tone, label: status };
  const dot = size === "sm" ? "h-1.5 w-1.5" : "h-2 w-2";
  return (
    <span className={`inline-flex items-center gap-2 ${TONE_TEXT[s.tone]}`}>
      <span className={`relative ${dot} shrink-0`}>
        <span className={`absolute inset-0 rounded-full bg-current ${s.live ? "animate-nx-pulse" : ""}`} />
        {s.live && <span className="absolute -inset-1 rounded-full border border-current opacity-40" />}
      </span>
      {showLabel && (
        <span className={`font-display font-semibold ${size === "sm" ? "text-[0.75rem]" : "text-body-sm"}`}>
          {s.label}
        </span>
      )}
    </span>
  );
}

/* --------------------------------------------------------- PAGE HEADER */
interface PageHeaderProps {
  eyebrow?: string;
  title: string;
  description?: string;
  status?: keyof typeof STATUS_TONE;
  meta?: ReactNode;
  actions?: ReactNode;
}
/** The single page-header contract. In the old portal 60 of 64 routes
    bypassed the shared header and six different heading recipes coexisted. */
export function PageHeader({ eyebrow, title, description, status, meta, actions }: PageHeaderProps) {
  return (
    <header className="mb-7 border-b border-hairline pb-5">
      {eyebrow && (
        <div className="mb-2 font-display text-label uppercase tracking-[0.13em] text-signal-text">
          {eyebrow}
        </div>
      )}
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="min-w-0">
          <div className="flex flex-wrap items-center gap-3">
            <h1 className="text-h1 text-ink">{title}</h1>
            {status && <StatusIndicator status={status} />}
          </div>
          {description && (
            <p className="mt-2 max-w-[68ch] text-body text-ink-secondary">{description}</p>
          )}
          {meta && <div className="mt-3 flex flex-wrap items-center gap-x-5 gap-y-2">{meta}</div>}
        </div>
        {actions && <div className="flex shrink-0 flex-wrap items-center gap-2">{actions}</div>}
      </div>
    </header>
  );
}

/** A compact label/value pair for header metadata. */
export function MetaItem({ label, value, mono }: { label: string; value: ReactNode; mono?: boolean }) {
  return (
    <div className="flex items-baseline gap-2">
      <span className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">{label}</span>
      <span className={`text-body-sm text-ink-secondary ${mono ? "font-mono" : ""}`}>{value}</span>
    </div>
  );
}

input.content:
"use client";

/* ============================================================================
   BUTTONS AND FORM CONTROLS
   Every control ships default, hover, active, focus, disabled, loading,
   error and success. Sizes are variants, never overrides — the old portal
   hand-tuned every small button because no size variant existed.
   ========================================================================= */

import {
  useId, useState, useRef, useEffect,
  type ButtonHTMLAttributes, type InputHTMLAttributes,
  type SelectHTMLAttributes, type ReactNode,
} from "react";
import { Icon, type IconName } from "./Icon";

/* ------------------------------------------------------------- BUTTON */
type Variant = "primary" | "secondary" | "ghost" | "danger" | "ai";
type Size = "sm" | "md" | "lg";

const VARIANT: Record<Variant, string> = {
  primary:
    "bg-signal text-white border border-signal hover:bg-signal-hover active:bg-signal-press",
  secondary:
    "bg-interactive text-ink border border-hairline-strong hover:bg-[#22304a] hover:border-[#3a4a66] active:bg-interactive",
  ghost:
    "bg-transparent text-ink-secondary border border-transparent hover:bg-interactive hover:text-ink active:bg-[#22304a]",
  danger:
    "bg-transparent text-danger-text border border-danger-text/40 hover:bg-danger/25 hover:border-danger-text/70 active:bg-danger/35",
  ai:
    "bg-ai text-white border border-ai hover:brightness-110 active:brightness-95",
};

const SIZE: Record<Size, string> = {
  sm: "h-8 px-3 text-[0.8125rem] gap-1.5",
  md: "h-10 px-4 text-body-sm gap-2",
  lg: "h-12 px-5 text-body gap-2",
};

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: Variant;
  size?: Size;
  loading?: boolean;
  icon?: IconName;
  iconRight?: IconName;
  block?: boolean;
}

export function Button({
  variant = "secondary", size = "md", loading, icon, iconRight, block,
  className = "", children, disabled, ...rest
}: ButtonProps) {
  return (
    <button
      className={`inline-flex items-center justify-center rounded-md font-display font-semibold
        transition-[background-color,border-color,color] duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
        disabled:cursor-not-allowed disabled:opacity-45
        ${VARIANT[variant]} ${SIZE[size]} ${block ? "w-full" : ""} ${className}`}
      disabled={disabled || loading}
      aria-busy={loading || undefined}
      {...rest}
    >
      {loading ? (
        <Icon name="spinner" size={size === "lg" ? "lg" : "md"} className="animate-spin" />
      ) : icon ? (
        <Icon name={icon} size={size === "lg" ? "lg" : "md"} />
      ) : null}
      {children}
      {iconRight && !loading && <Icon name={iconRight} size={size === "lg" ? "lg" : "md"} />}
    </button>
  );
}

/** Icon-only control. The label is required, not optional — that is how the
    nine unnamed icon buttons in the old portal stop being possible. */
export function IconButton({
  name, label, variant = "ghost", size = "md", className = "", ...rest
}: { name: IconName; label: string; variant?: Variant; size?: Size } & ButtonHTMLAttributes<HTMLButtonElement>) {
  const box = size === "sm" ? "h-8 w-8" : size === "lg" ? "h-12 w-12" : "h-10 w-10";
  return (
    <button
      aria-label={label}
      title={label}
      className={`inline-flex items-center justify-center rounded-md
        transition-[background-color,border-color,color] duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
        disabled:cursor-not-allowed disabled:opacity-45 ${VARIANT[variant]} ${box} ${className}`}
      {...rest}
    >
      <Icon name={name} size={size === "sm" ? "sm" : size === "lg" ? "lg" : "md"} />
    </button>
  );
}

/* -------------------------------------------------------------- FIELD */
interface FieldProps {
  label: string;
  hint?: string;
  error?: string;
  success?: string;
  required?: boolean;
  children: (props: { id: string; describedBy?: string; invalid: boolean }) => ReactNode;
}
/** One label, hint, error and success structure for every form in the
    product. 61% of labels in the old portal had no programmatic association;
    here association is produced by the wrapper, not by discipline. */
export function Field({ label, hint, error, success, required, children }: FieldProps) {
  const id = useId();
  const hintId = `${id}-hint`;
  const msgId = `${id}-msg`;
  const describedBy = [hint ? hintId : null, error || success ? msgId : null]
    .filter(Boolean).join(" ") || undefined;

  return (
    <div className="flex flex-col gap-1.5">
      <label htmlFor={id} className="font-display text-label uppercase tracking-[0.11em] text-ink-secondary">
        {label}
        {required && <span className="ml-1 text-danger-text" aria-hidden="true">*</span>}
      </label>
      {hint && <p id={hintId} className="text-caption text-ink-muted">{hint}</p>}
      {children({ id, describedBy, invalid: Boolean(error) })}
      {(error || success) && (
        <p
          id={msgId}
          role={error ? "alert" : "status"}
          className={`flex items-start gap-1.5 text-caption ${error ? "text-danger-text" : "text-success-text"}`}
        >
          <Icon name={error ? "alert" : "check"} size="sm" className="mt-0.5" />
          <span>{error || success}</span>
        </p>
      )}
    </div>
  );
}

const CONTROL_BASE =
  "w-full rounded-md border bg-plate px-3 text-body text-ink placeholder:text-ink-muted " +
  "transition-[border-color,background-color] duration-[var(--nx-dur-1)] " +
  "hover:border-hairline-strong disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:border-hairline";

/* -------------------------------------------------------------- INPUT */
export function Input({
  invalid, mono, className = "", ...rest
}: { invalid?: boolean; mono?: boolean } & InputHTMLAttributes<HTMLInputElement>) {
  return (
    <input
      aria-invalid={invalid || undefined}
      className={`${CONTROL_BASE} h-10 ${invalid ? "border-danger-text/60" : "border-hairline"} ${mono ? "font-mono text-code" : ""} ${className}`}
      {...rest}
    />
  );
}

/* ------------------------------------------------------------- SELECT */
export function Select({
  invalid, className = "", children, ...rest
}: { invalid?: boolean } & SelectHTMLAttributes<HTMLSelectElement>) {
  return (
    <div className="relative">
      <select
        aria-invalid={invalid || undefined}
        className={`${CONTROL_BASE} h-10 appearance-none pr-9 ${invalid ? "border-danger-text/60" : "border-hairline"} ${className}`}
        {...rest}
      >
        {children}
      </select>
      <Icon name="chevronDown" size="md"
        className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-ink-muted" />
    </div>
  );
}

/* ----------------------------------------------------------- TEXTAREA */
export function Textarea({
  invalid, className = "", ...rest
}: { invalid?: boolean } & InputHTMLAttributes<HTMLTextAreaElement>) {
  return (
    <textarea
      aria-invalid={invalid || undefined}
      className={`${CONTROL_BASE} min-h-24 resize-y py-2.5 ${invalid ? "border-danger-text/60" : "border-hairline"} ${className}`}
      {...(rest as object)}
    />
  );
}

/* ----------------------------------------------------------- COMBOBOX */
export interface ComboOption { value: string; label: string; hint?: string; icon?: IconName }
/** Filterable single-select with full keyboard support. */
export function Combobox({
  options, value, onChange, placeholder = "Search…", id, describedBy,
}: {
  options: ComboOption[]; value?: string; onChange?: (v: string) => void;
  placeholder?: string; id?: string; describedBy?: string;
}) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);
  const wrapRef = useRef<HTMLDivElement>(null);
  const listId = useId();

  const selected = options.find((o) => o.value === value);
  const filtered = query
    ? options.filter((o) => o.label.toLowerCase().includes(query.toLowerCase()))
    : options;

  useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, [open]);

  const commit = (v: string) => { onChange?.(v); setOpen(false); setQuery(""); };

  return (
    <div ref={wrapRef} className="relative">
      <input
        id={id}
        aria-describedby={describedBy}
        role="combobox"
        aria-expanded={open}
        aria-controls={listId}
        aria-autocomplete="list"
        value={open ? query : selected?.label ?? ""}
        placeholder={placeholder}
        onChange={(e) => { setQuery(e.target.value); setOpen(true); setActive(0); }}
        onFocus={() => setOpen(true)}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown") { e.preventDefault(); setOpen(true); setActive((i) => Math.min(i + 1, filtered.length - 1)); }
          else if (e.key === "ArrowUp") { e.preventDefault(); setActive((i) => Math.max(i - 1, 0)); }
          else if (e.key === "Enter" && open && filtered[active]) { e.preventDefault(); commit(filtered[active].value); }
          else if (e.key === "Escape") { setOpen(false); }
        }}
        className={`${CONTROL_BASE} h-10 border-hairline pr-9`}
      />
      <Icon name="search" size="md" className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-ink-muted" />
      {open && (
        <ul
          id={listId}
          role="listbox"
          className="absolute left-0 right-0 top-[calc(100%+4px)] z-[var(--nx-z-overlay)] max-h-64 overflow-y-auto rounded-md border border-hairline-strong bg-surface py-1 shadow-overlay"
        >
          {filtered.length === 0 && (
            <li className="px-3 py-2 text-body-sm text-ink-muted">No matches for “{query}”.</li>
          )}
          {filtered.map((o, i) => (
            <li key={o.value} role="option" aria-selected={o.value === value}>
              <button
                type="button"
                onMouseEnter={() => setActive(i)}
                onClick={() => commit(o.value)}
                className={`flex w-full items-center gap-2.5 px-3 py-2 text-left text-body-sm transition-colors duration-[var(--nx-dur-1)] ${
                  i === active ? "bg-interactive text-ink" : "text-ink-secondary"
                }`}
              >
                {o.icon && <Icon name={o.icon} size="md" className="text-ink-muted" />}
                <span className="flex-1">{o.label}</span>
                {o.hint && <span className="font-mono text-caption text-ink-muted">{o.hint}</span>}
                {o.value === value && <Icon name="check" size="sm" className="text-signal-text" />}
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/* ------------------------------------------------------------- TOGGLE */
/** One switch for the product. The old portal had six, in two sizes and two
    DOM strategies, none using the switch role. */
export function Toggle({
  checked, onChange, label, description, disabled,
}: { checked: boolean; onChange?: (v: boolean) => void; label: string; description?: string; disabled?: boolean }) {
  return (
    <label className={`flex items-start gap-3 ${disabled ? "opacity-50" : "cursor-pointer"}`}>
      <button
        type="button"
        role="switch"
        aria-checked={checked}
        aria-label={label}
        disabled={disabled}
        onClick={() => onChange?.(!checked)}
        className={`relative mt-0.5 h-5 w-9 shrink-0 rounded-pill border transition-colors duration-[var(--nx-dur-1)] ease-[var(--nx-ease)] ${
          checked ? "border-signal bg-signal" : "border-hairline-strong bg-interactive"
        } ${disabled ? "cursor-not-allowed" : ""}`}
      >
        <span
          className={`absolute top-1/2 h-3.5 w-3.5 -translate-y-1/2 rounded-full bg-white transition-[left] duration-[var(--nx-dur-1)] ease-[var(--nx-ease)] ${
            checked ? "left-[1.125rem]" : "left-0.5"
          }`}
        />
      </button>
      <span className="min-w-0">
        <span className="block text-body-sm font-medium text-ink">{label}</span>
        {description && <span className="block text-caption text-ink-muted">{description}</span>}
      </span>
    </label>
  );
}

/* ---------------------------------------------------- CHECKBOX / RADIO */
export function Checkbox({
  checked, onChange, label, description, disabled,
}: { checked: boolean; onChange?: (v: boolean) => void; label: string; description?: string; disabled?: boolean }) {
  return (
    <label className={`flex items-start gap-3 ${disabled ? "opacity-50" : "cursor-pointer"}`}>
      <span className="relative mt-0.5 flex h-[1.125rem] w-[1.125rem] shrink-0">
        <input
          type="checkbox"
          checked={checked}
          disabled={disabled}
          onChange={(e) => onChange?.(e.target.checked)}
          className="peer absolute inset-0 cursor-pointer opacity-0 disabled:cursor-not-allowed"
        />
        <span className={`pointer-events-none flex h-full w-full items-center justify-center rounded-sm border transition-colors duration-[var(--nx-dur-1)] peer-focus-visible:outline peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-signal-edge ${
          checked ? "border-signal bg-signal text-white" : "border-hairline-strong bg-plate text-transparent"
        }`}>
          <Icon name="check" size="sm" />
        </span>
      </span>
      <span className="min-w-0">
        <span className="block text-body-sm font-medium text-ink">{label}</span>
        {description && <span className="block text-caption text-ink-muted">{description}</span>}
      </span>
    </label>
  );
}

export function Radio({
  checked, onChange, label, description, name, disabled,
}: { checked: boolean; onChange?: () => void; label: string; description?: string; name: string; disabled?: boolean }) {
  return (
    <label className={`flex items-start gap-3 ${disabled ? "opacity-50" : "cursor-pointer"}`}>
      <span className="relative mt-0.5 flex h-[1.125rem] w-[1.125rem] shrink-0">
        <input
          type="radio" name={name} checked={checked} disabled={disabled} onChange={() => onChange?.()}
          className="peer absolute inset-0 cursor-pointer opacity-0 disabled:cursor-not-allowed"
        />
        <span className={`pointer-events-none flex h-full w-full items-center justify-center rounded-full border transition-colors duration-[var(--nx-dur-1)] peer-focus-visible:outline peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-signal-edge ${
          checked ? "border-signal" : "border-hairline-strong bg-plate"
        }`}>
          {checked && <span className="h-2 w-2 rounded-full bg-signal" />}
        </span>
      </span>
      <span className="min-w-0">
        <span className="block text-body-sm font-medium text-ink">{label}</span>
        {description && <span className="block text-caption text-ink-muted">{description}</span>}
      </span>
    </label>
  );
}

toolUseResult.content:
"use client";

/* ============================================================================
   BUTTONS AND FORM CONTROLS
   Every control ships default, hover, active, focus, disabled, loading,
   error and success. Sizes are variants, never overrides — the old portal
   hand-tuned every small button because no size variant existed.
   ========================================================================= */

import {
  useId, useState, useRef, useEffect,
  type ButtonHTMLAttributes, type InputHTMLAttributes,
  type SelectHTMLAttributes, type ReactNode,
} from "react";
import { Icon, type IconName } from "./Icon";

/* ------------------------------------------------------------- BUTTON */
type Variant = "primary" | "secondary" | "ghost" | "danger" | "ai";
type Size = "sm" | "md" | "lg";

const VARIANT: Record<Variant, string> = {
  primary:
    "bg-signal text-white border border-signal hover:bg-signal-hover active:bg-signal-press",
  secondary:
    "bg-interactive text-ink border border-hairline-strong hover:bg-[#22304a] hover:border-[#3a4a66] active:bg-interactive",
  ghost:
    "bg-transparent text-ink-secondary border border-transparent hover:bg-interactive hover:text-ink active:bg-[#22304a]",
  danger:
    "bg-transparent text-danger-text border border-danger-text/40 hover:bg-danger/25 hover:border-danger-text/70 active:bg-danger/35",
  ai:
    "bg-ai text-white border border-ai hover:brightness-110 active:brightness-95",
};

const SIZE: Record<Size, string> = {
  sm: "h-8 px-3 text-[0.8125rem] gap-1.5",
  md: "h-10 px-4 text-body-sm gap-2",
  lg: "h-12 px-5 text-body gap-2",
};

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: Variant;
  size?: Size;
  loading?: boolean;
  icon?: IconName;
  iconRight?: IconName;
  block?: boolean;
}

export function Button({
  variant = "secondary", size = "md", loading, icon, iconRight, block,
  className = "", children, disabled, ...rest
}: ButtonProps) {
  return (
    <button
      className={`inline-flex items-center justify-center rounded-md font-display font-semibold
        transition-[background-color,border-color,color] duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
        disabled:cursor-not-allowed disabled:opacity-45
        ${VARIANT[variant]} ${SIZE[size]} ${block ? "w-full" : ""} ${className}`}
      disabled={disabled || loading}
      aria-busy={loading || undefined}
      {...rest}
    >
      {loading ? (
        <Icon name="spinner" size={size === "lg" ? "lg" : "md"} className="animate-spin" />
      ) : icon ? (
        <Icon name={icon} size={size === "lg" ? "lg" : "md"} />
      ) : null}
      {children}
      {iconRight && !loading && <Icon name={iconRight} size={size === "lg" ? "lg" : "md"} />}
    </button>
  );
}

/** Icon-only control. The label is required, not optional — that is how the
    nine unnamed icon buttons in the old portal stop being possible. */
export function IconButton({
  name, label, variant = "ghost", size = "md", className = "", ...rest
}: { name: IconName; label: string; variant?: Variant; size?: Size } & ButtonHTMLAttributes<HTMLButtonElement>) {
  const box = size === "sm" ? "h-8 w-8" : size === "lg" ? "h-12 w-12" : "h-10 w-10";
  return (
    <button
      aria-label={label}
      title={label}
      className={`inline-flex items-center justify-center rounded-md
        transition-[background-color,border-color,color] duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
        disabled:cursor-not-allowed disabled:opacity-45 ${VARIANT[variant]} ${box} ${className}`}
      {...rest}
    >
      <Icon name={name} size={size === "sm" ? "sm" : size === "lg" ? "lg" : "md"} />
    </button>
  );
}

/* -------------------------------------------------------------- FIELD */
interface FieldProps {
  label: string;
  hint?: string;
  error?: string;
  success?: string;
  required?: boolean;
  children: (props: { id: string; describedBy?: string; invalid: boolean }) => ReactNode;
}
/** One label, hint, error and success structure for every form in the
    product. 61% of labels in the old portal had no programmatic association;
    here association is produced by the wrapper, not by discipline. */
export function Field({ label, hint, error, success, required, children }: FieldProps) {
  const id = useId();
  const hintId = `${id}-hint`;
  const msgId = `${id}-msg`;
  const describedBy = [hint ? hintId : null, error || success ? msgId : null]
    .filter(Boolean).join(" ") || undefined;

  return (
    <div className="flex flex-col gap-1.5">
      <label htmlFor={id} className="font-display text-label uppercase tracking-[0.11em] text-ink-secondary">
        {label}
        {required && <span className="ml-1 text-danger-text" aria-hidden="true">*</span>}
      </label>
      {hint && <p id={hintId} className="text-caption text-ink-muted">{hint}</p>}
      {children({ id, describedBy, invalid: Boolean(error) })}
      {(error || success) && (
        <p
          id={msgId}
          role={error ? "alert" : "status"}
          className={`flex items-start gap-1.5 text-caption ${error ? "text-danger-text" : "text-success-text"}`}
        >
          <Icon name={error ? "alert" : "check"} size="sm" className="mt-0.5" />
          <span>{error || success}</span>
        </p>
      )}
    </div>
  );
}

const CONTROL_BASE =
  "w-full rounded-md border bg-plate px-3 text-body text-ink placeholder:text-ink-muted " +
  "transition-[border-color,background-color] duration-[var(--nx-dur-1)] " +
  "hover:border-hairline-strong disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:border-hairline";

/* -------------------------------------------------------------- INPUT */
export function Input({
  invalid, mono, className = "", ...rest
}: { invalid?: boolean; mono?: boolean } & InputHTMLAttributes<HTMLInputElement>) {
  return (
    <input
      aria-invalid={invalid || undefined}
      className={`${CONTROL_BASE} h-10 ${invalid ? "border-danger-text/60" : "border-hairline"} ${mono ? "font-mono text-code" : ""} ${className}`}
      {...rest}
    />
  );
}

/* ------------------------------------------------------------- SELECT */
export function Select({
  invalid, className = "", children, ...rest
}: { invalid?: boolean } & SelectHTMLAttributes<HTMLSelectElement>) {
  return (
    <div className="relative">
      <select
        aria-invalid={invalid || undefined}
        className={`${CONTROL_BASE} h-10 appearance-none pr-9 ${invalid ? "border-danger-text/60" : "border-hairline"} ${className}`}
        {...rest}
      >
        {children}
      </select>
      <Icon name="chevronDown" size="md"
        className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-ink-muted" />
    </div>
  );
}

/* ----------------------------------------------------------- TEXTAREA */
export function Textarea({
  invalid, className = "", ...rest
}: { invalid?: boolean } & InputHTMLAttributes<HTMLTextAreaElement>) {
  return (
    <textarea
      aria-invalid={invalid || undefined}
      className={`${CONTROL_BASE} min-h-24 resize-y py-2.5 ${invalid ? "border-danger-text/60" : "border-hairline"} ${className}`}
      {...(rest as object)}
    />
  );
}

/* ----------------------------------------------------------- COMBOBOX */
export interface ComboOption { value: string; label: string; hint?: string; icon?: IconName }
/** Filterable single-select with full keyboard support. */
export function Combobox({
  options, value, onChange, placeholder = "Search…", id, describedBy,
}: {
  options: ComboOption[]; value?: string; onChange?: (v: string) => void;
  placeholder?: string; id?: string; describedBy?: string;
}) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);
  const wrapRef = useRef<HTMLDivElement>(null);
  const listId = useId();

  const selected = options.find((o) => o.value === value);
  const filtered = query
    ? options.filter((o) => o.label.toLowerCase().includes(query.toLowerCase()))
    : options;

  useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, [open]);

  const commit = (v: string) => { onChange?.(v); setOpen(false); setQuery(""); };

  return (
    <div ref={wrapRef} className="relative">
      <input
        id={id}
        aria-describedby={describedBy}
        role="combobox"
        aria-expanded={open}
        aria-controls={listId}
        aria-autocomplete="list"
        value={open ? query : selected?.label ?? ""}
        placeholder={placeholder}
        onChange={(e) => { setQuery(e.target.value); setOpen(true); setActive(0); }}
        onFocus={() => setOpen(true)}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown") { e.preventDefault(); setOpen(true); setActive((i) => Math.min(i + 1, filtered.length - 1)); }
          else if (e.key === "ArrowUp") { e.preventDefault(); setActive((i) => Math.max(i - 1, 0)); }
          else if (e.key === "Enter" && open && filtered[active]) { e.preventDefault(); commit(filtered[active].value); }
          else if (e.key === "Escape") { setOpen(false); }
        }}
        className={`${CONTROL_BASE} h-10 border-hairline pr-9`}
      />
      <Icon name="search" size="md" className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-ink-muted" />
      {open && (
        <ul
          id={listId}
          role="listbox"
          className="absolute left-0 right-0 top-[calc(100%+4px)] z-[var(--nx-z-overlay)] max-h-64 overflow-y-auto rounded-md border border-hairline-strong bg-surface py-1 shadow-overlay"
        >
          {filtered.length === 0 && (
            <li className="px-3 py-2 text-body-sm text-ink-muted">No matches for “{query}”.</li>
          )}
          {filtered.map((o, i) => (
            <li key={o.value} role="option" aria-selected={o.value === value}>
              <button
                type="button"
                onMouseEnter={() => setActive(i)}
                onClick={() => commit(o.value)}
                className={`flex w-full items-center gap-2.5 px-3 py-2 text-left text-body-sm transition-colors duration-[var(--nx-dur-1)] ${
                  i === active ? "bg-interactive text-ink" : "text-ink-secondary"
                }`}
              >
                {o.icon && <Icon name={o.icon} size="md" className="text-ink-muted" />}
                <span className="flex-1">{o.label}</span>
                {o.hint && <span className="font-mono text-caption text-ink-muted">{o.hint}</span>}
                {o.value === value && <Icon name="check" size="sm" className="text-signal-text" />}
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/* ------------------------------------------------------------- TOGGLE */
/** One switch for the product. The old portal had six, in two sizes and two
    DOM strategies, none using the switch role. */
export function Toggle({
  checked, onChange, label, description, disabled,
}: { checked: boolean; onChange?: (v: boolean) => void; label: string; description?: string; disabled?: boolean }) {
  return (
    <label className={`flex items-start gap-3 ${disabled ? "opacity-50" : "cursor-pointer"}`}>
      <button
        type="button"
        role="switch"
        aria-checked={checked}
        aria-label={label}
        disabled={disabled}
        onClick={() => onChange?.(!checked)}
        className={`relative mt-0.5 h-5 w-9 shrink-0 rounded-pill border transition-colors duration-[var(--nx-dur-1)] ease-[var(--nx-ease)] ${
          checked ? "border-signal bg-signal" : "border-hairline-strong bg-interactive"
        } ${disabled ? "cursor-not-allowed" : ""}`}
      >
        <span
          className={`absolute top-1/2 h-3.5 w-3.5 -translate-y-1/2 rounded-full bg-white transition-[left] duration-[var(--nx-dur-1)] ease-[var(--nx-ease)] ${
            checked ? "left-[1.125rem]" : "left-0.5"
          }`}
        />
      </button>
      <span className="min-w-0">
        <span className="block text-body-sm font-medium text-ink">{label}</span>
        {description && <span className="block text-caption text-ink-muted">{description}</span>}
      </span>
    </label>
  );
}

/* ---------------------------------------------------- CHECKBOX / RADIO */
export function Checkbox({
  checked, onChange, label, description, disabled,
}: { checked: boolean; onChange?: (v: boolean) => void; label: string; description?: string; disabled?: boolean }) {
  return (
    <label className={`flex items-start gap-3 ${disabled ? "opacity-50" : "cursor-pointer"}`}>
      <span className="relative mt-0.5 flex h-[1.125rem] w-[1.125rem] shrink-0">
        <input
          type="checkbox"
          checked={checked}
          disabled={disabled}
          onChange={(e) => onChange?.(e.target.checked)}
          className="peer absolute inset-0 cursor-pointer opacity-0 disabled:cursor-not-allowed"
        />
        <span className={`pointer-events-none flex h-full w-full items-center justify-center rounded-sm border transition-colors duration-[var(--nx-dur-1)] peer-focus-visible:outline peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-signal-edge ${
          checked ? "border-signal bg-signal text-white" : "border-hairline-strong bg-plate text-transparent"
        }`}>
          <Icon name="check" size="sm" />
        </span>
      </span>
      <span className="min-w-0">
        <span className="block text-body-sm font-medium text-ink">{label}</span>
        {description && <span className="block text-caption text-ink-muted">{description}</span>}
      </span>
    </label>
  );
}

export function Radio({
  checked, onChange, label, description, name, disabled,
}: { checked: boolean; onChange?: () => void; label: string; description?: string; name: string; disabled?: boolean }) {
  return (
    <label className={`flex items-start gap-3 ${disabled ? "opacity-50" : "cursor-pointer"}`}>
      <span className="relative mt-0.5 flex h-[1.125rem] w-[1.125rem] shrink-0">
        <input
          type="radio" name={name} checked={checked} disabled={disabled} onChange={() => onChange?.()}
          className="peer absolute inset-0 cursor-pointer opacity-0 disabled:cursor-not-allowed"
        />
        <span className={`pointer-events-none flex h-full w-full items-center justify-center rounded-full border transition-colors duration-[var(--nx-dur-1)] peer-focus-visible:outline peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-signal-edge ${
          checked ? "border-signal" : "border-hairline-strong bg-plate"
        }`}>
          {checked && <span className="h-2 w-2 rounded-full bg-signal" />}
        </span>
      </span>
      <span className="min-w-0">
        <span className="block text-body-sm font-medium text-ink">{label}</span>
        {description && <span className="block text-caption text-ink-muted">{description}</span>}
      </span>
    </label>
  );
}

input.content:
"use client";

/* ============================================================================
   TABS, SEGMENTED CONTROLS, STEPPERS, PROGRESS, WIZARD
   One tab mechanism for the product. The old portal had eight tab-bar styles
   plus eight one-off segmented rows, and its two most-used implementations
   rewrote the URL without adding history, so Back left the page.
   ========================================================================= */

import { useId, useRef, type ReactNode, type KeyboardEvent } from "react";
import { Icon, type IconName } from "./Icon";

/* ---------------------------------------------------------------- TABS */
export interface TabItem { id: string; label: string; icon?: IconName; badge?: string | number; disabled?: boolean }

/** Arrow keys move, Home and End jump, Enter and Space are implicit on a
    button. Roving tabindex, so the tab list is one stop in the page order. */
export function Tabs({
  items, active, onChange, ariaLabel = "Sections",
}: { items: TabItem[]; active: string; onChange: (id: string) => void; ariaLabel?: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const base = useId();

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const enabled = items.filter((i) => !i.disabled);
    const idx = enabled.findIndex((i) => i.id === active);
    let next = -1;
    if (e.key === "ArrowRight") next = (idx + 1) % enabled.length;
    else if (e.key === "ArrowLeft") next = (idx - 1 + enabled.length) % enabled.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = enabled.length - 1;
    if (next >= 0) {
      e.preventDefault();
      onChange(enabled[next].id);
      const el = ref.current?.querySelector<HTMLButtonElement>(`#${CSS.escape(`${base}-${enabled[next].id}`)}`);
      el?.focus();
    }
  };

  return (
    <div
      ref={ref}
      role="tablist"
      aria-label={ariaLabel}
      onKeyDown={onKeyDown}
      className="flex gap-0.5 overflow-x-auto border-b border-hairline"
    >
      {items.map((t) => {
        const on = t.id === active;
        return (
          <button
            key={t.id}
            id={`${base}-${t.id}`}
            role="tab"
            aria-selected={on}
            aria-controls={`${base}-panel-${t.id}`}
            tabIndex={on ? 0 : -1}
            disabled={t.disabled}
            onClick={() => onChange(t.id)}
            className={`relative -mb-px inline-flex shrink-0 items-center gap-2 whitespace-nowrap border-b-2 px-3.5 py-2.5 font-display text-body-sm font-semibold
              transition-colors duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
              disabled:cursor-not-allowed disabled:opacity-40
              ${on
                ? "border-signal-edge text-ink"
                : "border-transparent text-ink-muted hover:border-hairline-strong hover:text-ink-secondary"}`}
          >
            {t.icon && <Icon name={t.icon} size="md" />}
            {t.label}
            {t.badge !== undefined && (
              <span className="rounded-sm bg-interactive px-1.5 py-0.5 font-mono text-[0.6875rem] text-ink-secondary">
                {t.badge}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}

export function TabPanel({ id, active, children }: { id: string; active: string; children: ReactNode }) {
  if (id !== active) return null;
  return (
    <div role="tabpanel" className="animate-nx-fade pt-5">
      {children}
    </div>
  );
}

/* --------------------------------------------------- SEGMENTED CONTROL */
/** For switching a view of the same data — a time range, a density. Visually
    distinct from tabs on purpose: tabs change what you are looking at, a
    segment changes how. */
export function SegmentedControl<T extends string>({
  options, value, onChange, size = "md", ariaLabel,
}: {
  options: { value: T; label: string }[]; value: T; onChange: (v: T) => void;
  size?: "sm" | "md"; ariaLabel: string;
}) {
  return (
    <div
      role="group"
      aria-label={ariaLabel}
      className="inline-flex rounded-md border border-hairline bg-plate p-0.5"
    >
      {options.map((o) => {
        const on = o.value === value;
        return (
          <button
            key={o.value}
            type="button"
            aria-pressed={on}
            onClick={() => onChange(o.value)}
            className={`rounded-sm font-display font-semibold transition-colors duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
              ${size === "sm" ? "px-2 py-1 text-[0.75rem]" : "px-3 py-1.5 text-[0.8125rem]"}
              ${on ? "bg-interactive text-ink" : "text-ink-muted hover:text-ink-secondary"}`}
          >
            {o.label}
          </button>
        );
      })}
    </div>
  );
}

/* ------------------------------------------------------------- STEPPER */
export interface Step { id: string; label: string }

export function Stepper({ steps, current }: { steps: Step[]; current: number }) {
  return (
    <ol className="flex flex-wrap items-center gap-x-2 gap-y-2">
      {steps.map((s, i) => {
        const done = i < current;
        const now = i === current;
        return (
          <li key={s.id} className="flex items-center gap-2">
            <span
              className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border font-mono text-[0.6875rem] font-semibold
                ${done ? "border-success-text/50 bg-success/30 text-success-text"
                  : now ? "border-signal-edge bg-signal/25 text-signal-text"
                  : "border-hairline-strong text-ink-muted"}`}
              aria-hidden="true"
            >
              {done ? <Icon name="check" size="sm" /> : i + 1}
            </span>
            <span className={`font-display text-body-sm font-semibold ${now ? "text-ink" : done ? "text-ink-secondary" : "text-ink-muted"}`}>
              {s.label}
            </span>
            {i < steps.length - 1 && (
              <span className="mx-1 h-px w-6 bg-hairline-strong sm:w-10" aria-hidden="true" />
            )}
          </li>
        );
      })}
    </ol>
  );
}

/* ------------------------------------------------------------ PROGRESS */
export function Progress({
  value, max = 100, label, tone = "signal", showValue = true,
}: { value: number; max?: number; label?: string; tone?: "signal" | "success" | "warning" | "danger"; showValue?: boolean }) {
  const pct = Math.max(0, Math.min(100, (value / max) * 100));
  const bar = {
    signal: "bg-signal", success: "bg-success-text", warning: "bg-warning-text", danger: "bg-danger-text",
  }[tone];
  return (
    <div>
      {(label || showValue) && (
        <div className="mb-1.5 flex items-baseline justify-between gap-3">
          {label && <span className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">{label}</span>}
          {showValue && <span className="font-mono text-caption tabular-nums text-ink-secondary">{Math.round(pct)}%</span>}
        </div>
      )}
      <div
        className="h-1.5 w-full overflow-hidden rounded-pill bg-plate"
        role="progressbar"
        aria-valuenow={Math.round(pct)}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label={label}
      >
        <div className={`h-full rounded-pill ${bar} transition-[width] duration-[var(--nx-dur-3)] ease-[var(--nx-ease)]`} style={{ width: `${pct}%` }} />
      </div>
    </div>
  );
}

/* -------------------------------------------------------------- WIZARD */
/** The shell a purchase flow lives in. The price summary is a sibling of the
    step content, not a child, so on mobile it pins to the bottom and the
    price can never scroll out of view. */
export function Wizard({
  steps, current, onBack, children, summary, primary,
}: {
  steps: Step[]; current: number; onBack?: () => void;
  children: ReactNode; summary?: ReactNode; primary?: ReactNode;
}) {
  return (
    <div className="nx-container-surface overflow-hidden">
      <div className="border-b border-hairline px-5 py-4">
        <Stepper steps={steps} current={current} />
      </div>

      <div className="px-5 py-6 lg:px-6">{children}</div>

      <div className="sticky bottom-0 flex flex-wrap items-center justify-between gap-3 border-t border-hairline bg-surface/95 px-5 py-3.5 backdrop-blur">
        <div className="min-w-0">{summary}</div>
        <div className="flex items-center gap-2">
          {onBack && current > 0 && (
            <button
              type="button"
              onClick={onBack}
              className="inline-flex items-center gap-1.5 rounded-md px-3 py-2 font-display text-body-sm font-semibold text-ink-muted transition-colors duration-[var(--nx-dur-1)] hover:text-ink"
            >
              <Icon name="chevronLeft" size="md" /> Back
            </button>
          )}
          {primary}
        </div>
      </div>
    </div>
  );
}

toolUseResult.content:
"use client";

/* ============================================================================
   TABS, SEGMENTED CONTROLS, STEPPERS, PROGRESS, WIZARD
   One tab mechanism for the product. The old portal had eight tab-bar styles
   plus eight one-off segmented rows, and its two most-used implementations
   rewrote the URL without adding history, so Back left the page.
   ========================================================================= */

import { useId, useRef, type ReactNode, type KeyboardEvent } from "react";
import { Icon, type IconName } from "./Icon";

/* ---------------------------------------------------------------- TABS */
export interface TabItem { id: string; label: string; icon?: IconName; badge?: string | number; disabled?: boolean }

/** Arrow keys move, Home and End jump, Enter and Space are implicit on a
    button. Roving tabindex, so the tab list is one stop in the page order. */
export function Tabs({
  items, active, onChange, ariaLabel = "Sections",
}: { items: TabItem[]; active: string; onChange: (id: string) => void; ariaLabel?: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const base = useId();

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const enabled = items.filter((i) => !i.disabled);
    const idx = enabled.findIndex((i) => i.id === active);
    let next = -1;
    if (e.key === "ArrowRight") next = (idx + 1) % enabled.length;
    else if (e.key === "ArrowLeft") next = (idx - 1 + enabled.length) % enabled.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = enabled.length - 1;
    if (next >= 0) {
      e.preventDefault();
      onChange(enabled[next].id);
      const el = ref.current?.querySelector<HTMLButtonElement>(`#${CSS.escape(`${base}-${enabled[next].id}`)}`);
      el?.focus();
    }
  };

  return (
    <div
      ref={ref}
      role="tablist"
      aria-label={ariaLabel}
      onKeyDown={onKeyDown}
      className="flex gap-0.5 overflow-x-auto border-b border-hairline"
    >
      {items.map((t) => {
        const on = t.id === active;
        return (
          <button
            key={t.id}
            id={`${base}-${t.id}`}
            role="tab"
            aria-selected={on}
            aria-controls={`${base}-panel-${t.id}`}
            tabIndex={on ? 0 : -1}
            disabled={t.disabled}
            onClick={() => onChange(t.id)}
            className={`relative -mb-px inline-flex shrink-0 items-center gap-2 whitespace-nowrap border-b-2 px-3.5 py-2.5 font-display text-body-sm font-semibold
              transition-colors duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
              disabled:cursor-not-allowed disabled:opacity-40
              ${on
                ? "border-signal-edge text-ink"
                : "border-transparent text-ink-muted hover:border-hairline-strong hover:text-ink-secondary"}`}
          >
            {t.icon && <Icon name={t.icon} size="md" />}
            {t.label}
            {t.badge !== undefined && (
              <span className="rounded-sm bg-interactive px-1.5 py-0.5 font-mono text-[0.6875rem] text-ink-secondary">
                {t.badge}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}

export function TabPanel({ id, active, children }: { id: string; active: string; children: ReactNode }) {
  if (id !== active) return null;
  return (
    <div role="tabpanel" className="animate-nx-fade pt-5">
      {children}
    </div>
  );
}

/* --------------------------------------------------- SEGMENTED CONTROL */
/** For switching a view of the same data — a time range, a density. Visually
    distinct from tabs on purpose: tabs change what you are looking at, a
    segment changes how. */
export function SegmentedControl<T extends string>({
  options, value, onChange, size = "md", ariaLabel,
}: {
  options: { value: T; label: string }[]; value: T; onChange: (v: T) => void;
  size?: "sm" | "md"; ariaLabel: string;
}) {
  return (
    <div
      role="group"
      aria-label={ariaLabel}
      className="inline-flex rounded-md border border-hairline bg-plate p-0.5"
    >
      {options.map((o) => {
        const on = o.value === value;
        return (
          <button
            key={o.value}
            type="button"
            aria-pressed={on}
            onClick={() => onChange(o.value)}
            className={`rounded-sm font-display font-semibold transition-colors duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
              ${size === "sm" ? "px-2 py-1 text-[0.75rem]" : "px-3 py-1.5 text-[0.8125rem]"}
              ${on ? "bg-interactive text-ink" : "text-ink-muted hover:text-ink-secondary"}`}
          >
            {o.label}
          </button>
        );
      })}
    </div>
  );
}

/* ------------------------------------------------------------- STEPPER */
export interface Step { id: string; label: string }

export function Stepper({ steps, current }: { steps: Step[]; current: number }) {
  return (
    <ol className="flex flex-wrap items-center gap-x-2 gap-y-2">
      {steps.map((s, i) => {
        const done = i < current;
        const now = i === current;
        return (
          <li key={s.id} className="flex items-center gap-2">
            <span
              className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border font-mono text-[0.6875rem] font-semibold
                ${done ? "border-success-text/50 bg-success/30 text-success-text"
                  : now ? "border-signal-edge bg-signal/25 text-signal-text"
                  : "border-hairline-strong text-ink-muted"}`}
              aria-hidden="true"
            >
              {done ? <Icon name="check" size="sm" /> : i + 1}
            </span>
            <span className={`font-display text-body-sm font-semibold ${now ? "text-ink" : done ? "text-ink-secondary" : "text-ink-muted"}`}>
              {s.label}
            </span>
            {i < steps.length - 1 && (
              <span className="mx-1 h-px w-6 bg-hairline-strong sm:w-10" aria-hidden="true" />
            )}
          </li>
        );
      })}
    </ol>
  );
}

/* ------------------------------------------------------------ PROGRESS */
export function Progress({
  value, max = 100, label, tone = "signal", showValue = true,
}: { value: number; max?: number; label?: string; tone?: "signal" | "success" | "warning" | "danger"; showValue?: boolean }) {
  const pct = Math.max(0, Math.min(100, (value / max) * 100));
  const bar = {
    signal: "bg-signal", success: "bg-success-text", warning: "bg-warning-text", danger: "bg-danger-text",
  }[tone];
  return (
    <div>
      {(label || showValue) && (
        <div className="mb-1.5 flex items-baseline justify-between gap-3">
          {label && <span className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">{label}</span>}
          {showValue && <span className="font-mono text-caption tabular-nums text-ink-secondary">{Math.round(pct)}%</span>}
        </div>
      )}
      <div
        className="h-1.5 w-full overflow-hidden rounded-pill bg-plate"
        role="progressbar"
        aria-valuenow={Math.round(pct)}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label={label}
      >
        <div className={`h-full rounded-pill ${bar} transition-[width] duration-[var(--nx-dur-3)] ease-[var(--nx-ease)]`} style={{ width: `${pct}%` }} />
      </div>
    </div>
  );
}

/* -------------------------------------------------------------- WIZARD */
/** The shell a purchase flow lives in. The price summary is a sibling of the
    step content, not a child, so on mobile it pins to the bottom and the
    price can never scroll out of view. */
export function Wizard({
  steps, current, onBack, children, summary, primary,
}: {
  steps: Step[]; current: number; onBack?: () => void;
  children: ReactNode; summary?: ReactNode; primary?: ReactNode;
}) {
  return (
    <div className="nx-container-surface overflow-hidden">
      <div className="border-b border-hairline px-5 py-4">
        <Stepper steps={steps} current={current} />
      </div>

      <div className="px-5 py-6 lg:px-6">{children}</div>

      <div className="sticky bottom-0 flex flex-wrap items-center justify-between gap-3 border-t border-hairline bg-surface/95 px-5 py-3.5 backdrop-blur">
        <div className="min-w-0">{summary}</div>
        <div className="flex items-center gap-2">
          {onBack && current > 0 && (
            <button
              type="button"
              onClick={onBack}
              className="inline-flex items-center gap-1.5 rounded-md px-3 py-2 font-display text-body-sm font-semibold text-ink-muted transition-colors duration-[var(--nx-dur-1)] hover:text-ink"
            >
              <Icon name="chevronLeft" size="md" /> Back
            </button>
          )}
          {primary}
        </div>
      </div>
    </div>
  );
}

input.content:
"use client";

/* ============================================================================
   MODALS, DRAWERS, CONFIRMATIONS, DROPDOWNS, TOOLTIPS, TOASTS
   One implementation each, all with focus management. The old portal had 24
   independent overlays with zero focus traps, 60 browser confirmations and
   10 browser alerts, and no toast system at all.
   ========================================================================= */

import {
  createContext, useContext, useCallback, useEffect, useId, useRef, useState,
  type ReactNode,
} from "react";
import { Icon, type IconName } from "./Icon";
import { Button, IconButton } from "./controls";
import type { Tone } from "./primitives";

/* ------------------------------------------------------- focus plumbing */
function useFocusTrap(open: boolean, onClose: () => void) {
  const ref = useRef<HTMLDivElement>(null);
  const restoreTo = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (!open) return;
    restoreTo.current = document.activeElement as HTMLElement;

    const node = ref.current;
    const focusables = () =>
      Array.from(
        node?.querySelectorAll<HTMLElement>(
          'a[href],button:not([disabled]),textarea,input,select,[tabindex]:not([tabindex="-1"])'
        ) ?? []
      ).filter((el) => el.offsetParent !== null);

    focusables()[0]?.focus() ?? node?.focus();

    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") { e.stopPropagation(); onClose(); return; }
      if (e.key !== "Tab") return;
      const f = focusables();
      if (f.length === 0) return;
      const first = f[0], last = f[f.length - 1];
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    };

    document.addEventListener("keydown", onKey, true);
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", onKey, true);
      document.body.style.overflow = prevOverflow;
      restoreTo.current?.focus();
    };
  }, [open, onClose]);

  return ref;
}

/* --------------------------------------------------------------- MODAL */
export function Modal({
  open, onClose, title, description, children, footer, size = "md",
}: {
  open: boolean; onClose: () => void; title: string; description?: string;
  children?: ReactNode; footer?: ReactNode; size?: "sm" | "md" | "lg";
}) {
  const ref = useFocusTrap(open, onClose);
  const titleId = useId();
  const descId = useId();
  if (!open) return null;

  const width = { sm: "max-w-sm", md: "max-w-lg", lg: "max-w-2xl" }[size];

  return (
    <div className="fixed inset-0 z-[var(--nx-z-overlay)] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-scrim/80 animate-nx-fade" onClick={onClose} aria-hidden="true" />
      <div
        ref={ref}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={description ? descId : undefined}
        tabIndex={-1}
        className={`animate-nx-rise relative w-full ${width} rounded-lg border border-hairline-strong bg-surface shadow-overlay`}
      >
        <div className="flex items-start justify-between gap-4 border-b border-hairline px-5 py-4">
          <div className="min-w-0">
            <h2 id={titleId} className="text-h3 text-ink">{title}</h2>
            {description && <p id={descId} className="mt-1 text-body-sm text-ink-secondary">{description}</p>}
          </div>
          <IconButton name="close" label="Close" size="sm" onClick={onClose} />
        </div>
        {children && <div className="px-5 py-5">{children}</div>}
        {footer && <div className="flex flex-wrap justify-end gap-2 border-t border-hairline px-5 py-4">{footer}</div>}
      </div>
    </div>
  );
}

/* -------------------------------------------------------------- DRAWER */
export function Drawer({
  open, onClose, title, side = "right", children, footer,
}: {
  open: boolean; onClose: () => void; title: string;
  side?: "right" | "left"; children?: ReactNode; footer?: ReactNode;
}) {
  const ref = useFocusTrap(open, onClose);
  const titleId = useId();
  if (!open) return null;
  return (
    <div className="fixed inset-0 z-[var(--nx-z-overlay)]">
      <div className="absolute inset-0 bg-scrim/80 animate-nx-fade" onClick={onClose} aria-hidden="true" />
      <div
        ref={ref}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        tabIndex={-1}
        className={`absolute inset-y-0 flex w-full max-w-md flex-col border-hairline-strong bg-surface shadow-overlay
          ${side === "right"
            ? "right-0 border-l animate-nx-slide-right"
            : "left-0 border-r animate-nx-slide-left"}`}
      >
        <div className="flex items-center justify-between gap-4 border-b border-hairline px-5 py-4">
          <h2 id={titleId} className="text-h3 text-ink">{title}</h2>
          <IconButton name="close" label="Close" size="sm" onClick={onClose} />
        </div>
        <div className="min-h-0 flex-1 overflow-y-auto px-5 py-5">{children}</div>
        {footer && <div className="flex justify-end gap-2 border-t border-hairline px-5 py-4">{footer}</div>}
      </div>
    </div>
  );
}

/* ---------------------------------------------------- CONFIRM DIALOG */
/** Every destructive confirmation states what happens, what is lost and
    whether it can be undone. Irreversible actions require the resource name
    to be typed — clicking OK is not consent for a destroy. */
export function ConfirmDialog({
  open, onClose, onConfirm, title, whatHappens, whatIsLost, reversible,
  confirmLabel = "Confirm", typeToConfirm, tone = "danger",
}: {
  open: boolean; onClose: () => void; onConfirm: () => void;
  title: string; whatHappens: string; whatIsLost?: string; reversible: boolean;
  confirmLabel?: string; typeToConfirm?: string; tone?: "danger" | "signal";
}) {
  const [typed, setTyped] = useState("");
  useEffect(() => { if (!open) setTyped(""); }, [open]);
  const armed = !typeToConfirm || typed === typeToConfirm;

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={title}
      size="sm"
      footer={
        <>
          <Button variant="ghost" onClick={onClose}>Cancel</Button>
          <Button
            variant={tone === "danger" ? "danger" : "primary"}
            disabled={!armed}
            onClick={() => { onConfirm(); onClose(); }}
          >
            {confirmLabel}
          </Button>
        </>
      }
    >
      <div className="flex flex-col gap-4">
        <dl className="flex flex-col gap-3">
          <div>
            <dt className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">What happens</dt>
            <dd className="mt-1 text-body-sm text-ink-secondary">{whatHappens}</dd>
          </div>
          {whatIsLost && (
            <div>
              <dt className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">What is lost</dt>
              <dd className="mt-1 text-body-sm text-danger-text">{whatIsLost}</dd>
            </div>
          )}
          <div>
            <dt className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">Reversible</dt>
            <dd className={`mt-1 text-body-sm ${reversible ? "text-ink-secondary" : "text-danger-text"}`}>
              {reversible ? "Yes — this can be undone." : "No. This cannot be undone."}
            </dd>
          </div>
        </dl>
        {typeToConfirm && (
          <label className="flex flex-col gap-1.5">
            <span className="text-body-sm text-ink-secondary">
              Type <code className="font-mono text-code text-ink">{typeToConfirm}</code> to confirm.
            </span>
            <input
              value={typed}
              onChange={(e) => setTyped(e.target.value)}
              autoComplete="off"
              className="h-10 w-full rounded-md border border-hairline bg-plate px-3 font-mono text-code text-ink transition-colors duration-[var(--nx-dur-1)] hover:border-hairline-strong"
            />
          </label>
        )}
      </div>
    </Modal>
  );
}

/* ------------------------------------------------------------ DROPDOWN */
export interface MenuItem {
  label: string; icon?: IconName; onSelect?: () => void;
  tone?: "default" | "danger"; separatorBefore?: boolean;
}
export function Dropdown({ trigger, items, align = "right" }: {
  trigger: ReactNode; items: MenuItem[]; align?: "left" | "right";
}) {
  const [open, setOpen] = useState(false);
  const wrap = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => {
      if (wrap.current && !wrap.current.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setOpen(false); };
    document.addEventListener("mousedown", onDoc);
    document.addEventListener("keydown", onKey);
    return () => { document.removeEventListener("mousedown", onDoc); document.removeEventListener("keydown", onKey); };
  }, [open]);

  return (
    <div ref={wrap} className="relative">
      <span onClick={() => setOpen((v) => !v)}>{trigger}</span>
      {open && (
        <div
          role="menu"
          className={`absolute top-[calc(100%+4px)] z-[var(--nx-z-overlay)] min-w-52 animate-nx-rise rounded-md border border-hairline-strong bg-surface py-1 shadow-overlay ${
            align === "right" ? "right-0" : "left-0"
          }`}
        >
          {items.map((it, i) => (
            <div key={it.label}>
              {it.separatorBefore && i > 0 && <div className="my-1 h-px bg-hairline" />}
              <button
                role="menuitem"
                type="button"
                onClick={() => { it.onSelect?.(); setOpen(false); }}
                className={`flex w-full items-center gap-2.5 px-3 py-2 text-left text-body-sm transition-colors duration-[var(--nx-dur-1)] hover:bg-interactive ${
                  it.tone === "danger" ? "text-danger-text" : "text-ink-secondary hover:text-ink"
                }`}
              >
                {it.icon && <Icon name={it.icon} size="md" />}
                {it.label}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------- TOOLTIP */
export function Tooltip({ label, children }: { label: string; children: ReactNode }) {
  const [open, setOpen] = useState(false);
  const id = useId();
  return (
    <span className="relative inline-flex">
      <span
        aria-describedby={open ? id : undefined}
        onMouseEnter={() => setOpen(true)}
        onMouseLeave={() => setOpen(false)}
        onFocus={() => setOpen(true)}
        onBlur={() => setOpen(false)}
        className="inline-flex"
      >
        {children}
      </span>
      {open && (
        <span
          id={id}
          role="tooltip"
          className="pointer-events-none absolute bottom-[calc(100%+6px)] left-1/2 z-[var(--nx-z-tooltip)] w-max max-w-56 -translate-x-1/2 animate-nx-fade rounded-md border border-hairline-strong bg-plate px-2.5 py-1.5 text-caption text-ink shadow-overlay"
        >
          {label}
        </span>
      )}
    </span>
  );
}

/* --------------------------------------------------------------- ALERT */
const ALERT_STYLE: Record<Tone, { border: string; icon: IconName; text: string }> = {
  neutral: { border: "border-hairline-strong",     icon: "info",    text: "text-ink-secondary" },
  signal:  { border: "border-signal-edge/45",      icon: "info",    text: "text-signal-text" },
  success: { border: "border-success-text/40",     icon: "check",   text: "text-success-text" },
  warning: { border: "border-warning-text/40",     icon: "warning", text: "text-warning-text" },
  danger:  { border: "border-danger-text/40",      icon: "alert",   text: "text-danger-text" },
  ai:      { border: "border-ai-text/40",          icon: "ai",      text: "text-ai-text" },
};

export function Alert({
  tone = "neutral", title, children, action,
}: { tone?: Tone; title: string; children?: ReactNode; action?: ReactNode }) {
  const s = ALERT_STYLE[tone];
  return (
    <div
      role={tone === "danger" ? "alert" : "status"}
      className={`flex gap-3 rounded-md border-l-2 border-y border-r border-y-hairline border-r-hairline bg-surface px-4 py-3 ${s.border}`}
    >
      <Icon name={s.icon} size="md" className={`mt-0.5 ${s.text}`} />
      <div className="min-w-0 flex-1">
        <p className={`font-display text-body-sm font-semibold ${s.text}`}>{title}</p>
        {children && <div className="mt-1 text-body-sm text-ink-secondary">{children}</div>}
      </div>
      {action && <div className="shrink-0 self-center">{action}</div>}
    </div>
  );
}

/* --------------------------------------------------------------- TOAST */
export interface ToastMsg { id: number; tone: Tone; title: string; body?: string }
const ToastCtx = createContext<{ push: (t: Omit<ToastMsg, "id">) => void }>({ push: () => {} });
export const useToast = () => useContext(ToastCtx);

export function ToastProvider({ children }: { children: ReactNode }) {
  const [items, setItems] = useState<ToastMsg[]>([]);
  const push = useCallback((t: Omit<ToastMsg, "id">) => {
    const id = Date.now() + Math.random();
    setItems((xs) => [...xs, { ...t, id }]);
    window.setTimeout(() => setItems((xs) => xs.filter((x) => x.id !== id)), 4500);
  }, []);
  return (
    <ToastCtx.Provider value={{ push }}>
      {children}
      <div
        className="pointer-events-none fixed bottom-4 right-4 z-[var(--nx-z-toast)] flex w-full max-w-sm flex-col gap-2"
        aria-live="polite"
        aria-atomic="false"
      >
        {items.map((t) => {
          const s = ALERT_STYLE[t.tone];
          return (
            <div
              key={t.id}
              className={`pointer-events-auto flex animate-nx-rise gap-3 rounded-md border border-hairline-strong border-l-2 bg-surface px-4 py-3 shadow-overlay ${s.border}`}
            >
              <Icon name={s.icon} size="md" className={`mt-0.5 ${s.text}`} />
              <div className="min-w-0 flex-1">
                <p className={`font-display text-body-sm font-semibold ${s.text}`}>{t.title}</p>
                {t.body && <p className="mt-0.5 text-caption text-ink-secondary">{t.body}</p>}
              </div>
              <button
                type="button"
                aria-label="Dismiss"
                onClick={() => setItems((xs) => xs.filter((x) => x.id !== t.id))}
                className="shrink-0 self-start rounded-sm p-0.5 text-ink-muted transition-colors duration-[var(--nx-dur-1)] hover:text-ink"
              >
                <Icon name="close" size="sm" />
              </button>
            </div>
          );
        })}
      </div>
    </ToastCtx.Provider>
  );
}

