"use client";

/* ============================================================================
   TABLES, METRICS, METERS, CHARTS
   Chart colour comes from tokens, never from a hardcoded hex — the old
   portal's charts were unthemeable because the stroke was baked in.
   ========================================================================= */

import type { ReactNode } from "react";
import { Icon } from "./Icon";

/* --------------------------------------------------------------- TABLE */
export interface Column<Row> {
  key: string;
  header: string;
  align?: "left" | "right";
  /** Marks the column as technical, so its cells get the mono treatment. */
  mono?: boolean;
  width?: string;
  render: (row: Row) => ReactNode;
}

/** One table skin. Wide content scrolls inside its own container so the page
    body never scrolls sideways; below `md` the caller should render cards
    instead — see ResourceRow. */
export function Table<Row extends { id: string }>({
  columns, rows, caption, empty,
}: { columns: Column<Row>[]; rows: Row[]; caption?: string; empty?: ReactNode }) {
  if (rows.length === 0 && empty) return <>{empty}</>;
  return (
    <div className="overflow-x-auto rounded-lg border border-hairline">
      <table className="w-full border-collapse text-body-sm">
        {caption && <caption className="sr-only">{caption}</caption>}
        <thead>
          <tr className="border-b border-hairline bg-surface">
            {columns.map((c) => (
              <th
                key={c.key}
                scope="col"
                style={c.width ? { width: c.width } : undefined}
                className={`px-4 py-2.5 font-display text-label font-semibold uppercase tracking-[0.11em] text-ink-muted ${
                  c.align === "right" ? "text-right" : "text-left"
                }`}
              >
                {c.header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((r) => (
            <tr
              key={r.id}
              className="border-b border-hairline last:border-0 transition-colors duration-[var(--nx-dur-1)] hover:bg-surface"
            >
              {columns.map((c) => (
                <td
                  key={c.key}
                  className={`px-4 py-3 align-middle ${c.align === "right" ? "text-right" : "text-left"} ${
                    c.mono ? "font-mono text-code text-ink-secondary" : "text-ink-secondary"
                  }`}
                >
                  {c.render(r)}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/* --------------------------------------------------------- METRIC TILE */
export function MetricTile({
  label, value, unit, delta, hint, chart,
}: {
  label: string; value: string | number; unit?: string;
  delta?: { value: string; direction: "up" | "down"; good?: boolean };
  hint?: string; chart?: ReactNode;
}) {
  return (
    <div className="flex flex-col gap-2 px-4 py-3.5">
      <span className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">{label}</span>
      <div className="flex items-baseline gap-1.5">
        <span className="font-display text-metric tabular-nums text-ink">{value}</span>
        {unit && <span className="font-mono text-body-sm text-ink-muted">{unit}</span>}
      </div>
      {delta && (
        <span className={`inline-flex items-center gap-1 text-caption ${delta.good === false ? "text-danger-text" : "text-success-text"}`}>
          <Icon name={delta.direction === "up" ? "chevronRight" : "chevronRight"} size="sm"
            className={delta.direction === "up" ? "-rotate-90" : "rotate-90"} />
          {delta.value}
        </span>
      )}
      {chart}
      {hint && <span className="text-caption text-ink-muted">{hint}</span>}
    </div>
  );
}

/* ------------------------------------------------------ RESOURCE METER */
export function ResourceMeter({
  label, used, total, unit, format,
}: { label: string; used: number; total: number; unit?: string; format?: (n: number) => string }) {
  const pct = total > 0 ? Math.min(100, (used / total) * 100) : 0;
  const tone = pct >= 90 ? "danger" : pct >= 75 ? "warning" : "signal";
  const bar = { signal: "bg-signal", warning: "bg-warning-text", danger: "bg-danger-text" }[tone];
  const fmt = format ?? ((n: number) => String(n));
  return (
    <div>
      <div className="mb-1.5 flex items-baseline justify-between gap-3">
        <span className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">{label}</span>
        <span className="font-mono text-caption tabular-nums text-ink-secondary">
          {fmt(used)}<span className="text-ink-muted"> / {fmt(total)}{unit ? ` ${unit}` : ""}</span>
        </span>
      </div>
      <div
        className="h-1.5 w-full overflow-hidden rounded-pill bg-plate"
        role="meter" aria-valuenow={Math.round(pct)} aria-valuemin={0} aria-valuemax={100} aria-label={label}
      >
        <div className={`h-full rounded-pill ${bar} transition-[width] duration-[var(--nx-dur-3)] ease-[var(--nx-ease)]`} style={{ width: `${pct}%` }} />
      </div>
    </div>
  );
}

/* -------------------------------------------------------------- CHARTS */
type Ramp = "data" | "data-2" | "data-3" | "data-4" | "data-5";
const RAMP: Record<Ramp, string> = {
  "data":   "var(--color-data)",
  "data-2": "var(--color-data-2)",
  "data-3": "var(--color-data-3)",
  "data-4": "var(--color-data-4)",
  "data-5": "var(--color-data-5)",
};

export function Sparkline({
  points, tone = "data", width = 120, height = 32,
}: { points: number[]; tone?: Ramp; width?: number; height?: number }) {
  if (points.length < 2) return null;
  const min = Math.min(...points), max = Math.max(...points);
  const span = max - min || 1;
  const d = points
    .map((p, i) => {
      const x = (i / (points.length - 1)) * width;
      const y = height - ((p - min) / span) * (height - 4) - 2;
      return `${i === 0 ? "M" : "L"}${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(" ");
  const lastX = width;
  const lastY = height - ((points[points.length - 1] - min) / span) * (height - 4) - 2;
  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} aria-hidden="true" className="overflow-visible">
      <path d={d} fill="none" stroke={RAMP[tone]} strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" />
      <circle cx={lastX} cy={lastY} r={2.5} fill={RAMP[tone]} />
    </svg>
  );
}

/** Area chart with a real scale: every gridline is labelled with a value the
    chart actually reaches, and the endpoint is emphasised. */
export function AreaChart({
  points, labels, tone = "data", height = 160, unit = "", ariaLabel,
}: {
  points: number[]; labels?: string[]; tone?: Ramp;
  height?: number; unit?: string; ariaLabel: string;
}) {
  const W = 560, H = height, padL = 44, padB = 22, padT = 10, padR = 8;
  const iw = W - padL - padR, ih = H - padT - padB;
  const max = Math.max(...points, 1);
  const niceMax = Math.ceil(max / 5) * 5 || 5;
  const ticks = [0, niceMax / 2, niceMax];

  const x = (i: number) => padL + (i / (points.length - 1)) * iw;
  const y = (v: number) => padT + ih - (v / niceMax) * ih;

  const line = points.map((p, i) => `${i === 0 ? "M" : "L"}${x(i).toFixed(1)},${y(p).toFixed(1)}`).join(" ");
  const area = `${line} L${x(points.length - 1).toFixed(1)},${(padT + ih).toFixed(1)} L${padL},${(padT + ih).toFixed(1)} Z`;
  const gid = `nx-grad-${tone}`;

  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="w-full" role="img" aria-label={ariaLabel}>
      <defs>
        <linearGradient id={gid} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={RAMP[tone]} stopOpacity="0.28" />
          <stop offset="100%" stopColor={RAMP[tone]} stopOpacity="0.02" />
        </linearGradient>
      </defs>

      {ticks.map((t) => (
        <g key={t}>
          <line x1={padL} x2={W - padR} y1={y(t)} y2={y(t)} stroke="var(--color-hairline)" strokeWidth={1} />
          <text
            x={padL - 8} y={y(t)} textAnchor="end" dominantBaseline="middle"
            fill="var(--color-ink-muted)" fontSize="11" fontFamily="var(--font-mono)"
          >
            {t}{unit}
          </text>
        </g>
      ))}

      <path d={area} fill={`url(#${gid})`} />
      <path d={line} fill="none" stroke={RAMP[tone]} strokeWidth={1.75} strokeLinecap="round" strokeLinejoin="round" />
      <circle cx={x(points.length - 1)} cy={y(points[points.length - 1])} r={3.5} fill={RAMP[tone]} />

      {labels?.map((l, i) => {
        const step = Math.ceil(labels.length / 5);
        if (i % step !== 0 && i !== labels.length - 1) return null;
        return (
          <text
            key={l + i} x={x(i)} y={H - 6}
            textAnchor={i === labels.length - 1 ? "end" : i === 0 ? "start" : "middle"}
            fill="var(--color-ink-muted)" fontSize="11" fontFamily="var(--font-mono)"
          >
            {l}
          </text>
        );
      })}
    </svg>
  );
}

input.content:
"use client";

/* ============================================================================
   LOADING, EMPTY, ERROR, SUCCESS — and the deployment ladder
   The old portal served all 58 routes from one loading file and one error
   file, showed "Something went wrong" eleven times, and had no not-found
   inside the shell at all. Each state here is a designed surface.
   ========================================================================= */

import { useState, type ReactNode } from "react";
import { Icon, type IconName } from "./Icon";
import { Button } from "./controls";

/* ------------------------------------------------------------ SKELETON */
export function Skeleton({ className = "" }: { className?: string }) {
  return <div className={`animate-nx-pulse rounded-sm bg-interactive ${className}`} aria-hidden="true" />;
}

/** Shape-matched loading. A skeleton should predict the content that follows,
    which is why this takes a shape rather than being one generic block. */
export function LoadingState({ shape = "list", label = "Loading" }: { shape?: "list" | "metrics" | "detail"; label?: string }) {
  return (
    <div role="status" aria-live="polite" aria-busy="true">
      <span className="sr-only">{label}…</span>
      {shape === "metrics" && (
        <div className="grid grid-cols-2 gap-px overflow-hidden rounded-lg border border-hairline bg-hairline lg:grid-cols-4">
          {Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="flex flex-col gap-2.5 bg-surface px-4 py-3.5">
              <Skeleton className="h-3 w-20" />
              <Skeleton className="h-7 w-24" />
            </div>
          ))}
        </div>
      )}
      {shape === "list" && (
        <div className="flex flex-col gap-2">
          {Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="nx-object flex items-center gap-4 px-4 py-3.5">
              <Skeleton className="h-8 w-8 rounded-md" />
              <div className="flex flex-1 flex-col gap-2">
                <Skeleton className="h-3.5 w-40" />
                <Skeleton className="h-3 w-64" />
              </div>
              <Skeleton className="h-7 w-20 rounded-md" />
            </div>
          ))}
        </div>
      )}
      {shape === "detail" && (
        <div className="flex flex-col gap-5">
          <Skeleton className="h-8 w-64" />
          <div className="grid gap-3 sm:grid-cols-2">
            <Skeleton className="h-24" /><Skeleton className="h-24" />
          </div>
          <Skeleton className="h-40" />
        </div>
      )}
    </div>
  );
}

export function Spinner({ label = "Working" }: { label?: string }) {
  return (
    <span role="status" className="inline-flex items-center gap-2 text-ink-muted">
      <Icon name="spinner" size="md" className="animate-spin" />
      <span className="text-body-sm">{label}…</span>
    </span>
  );
}

/* --------------------------------------------------------- EMPTY STATE */
/** Explains the situation and offers the next action. Never "No data." */
export function EmptyState({
  icon = "resources", title, description, action, secondary,
}: { icon?: IconName; title: string; description: string; action?: ReactNode; secondary?: ReactNode }) {
  return (
    <div className="nx-container-surface flex flex-col items-center px-6 py-14 text-center">
      <span className="mb-4 flex h-12 w-12 items-center justify-center rounded-lg border border-hairline-strong bg-plate text-signal-text">
        <Icon name={icon} size="lg" />
      </span>
      <h3 className="text-h3 text-ink">{title}</h3>
      <p className="mt-2 max-w-[46ch] text-body-sm text-ink-secondary">{description}</p>
      {(action || secondary) && (
        <div className="mt-5 flex flex-wrap items-center justify-center gap-2">{action}{secondary}</div>
      )}
    </div>
  );
}

/* --------------------------------------------------------- ERROR STATE */
/** What happened, why, and how to fix it. Technical detail is available but
    never leads — the old portal put a bare digest on screen in a tone that
    failed contrast. */
export function ErrorState({
  title, reason, fix, technical, onRetry, onSupport,
}: {
  title: string; reason?: string; fix?: string; technical?: string;
  onRetry?: () => void; onSupport?: () => void;
}) {
  const [open, setOpen] = useState(false);
  return (
    <div className="nx-container-surface px-6 py-10" role="alert">
      <div className="mx-auto flex max-w-[52ch] flex-col items-center text-center">
        <span className="mb-4 flex h-12 w-12 items-center justify-center rounded-lg border border-danger-text/40 bg-danger/20 text-danger-text">
          <Icon name="alert" size="lg" />
        </span>
        <h3 className="text-h3 text-ink">{title}</h3>
        {reason && <p className="mt-2 text-body-sm text-ink-secondary">{reason}</p>}
        {fix && <p className="mt-2 text-body-sm text-ink-secondary">{fix}</p>}
        <div className="mt-5 flex flex-wrap items-center justify-center gap-2">
          {onRetry && <Button variant="primary" icon="restart" onClick={onRetry}>Try again</Button>}
          {onSupport && <Button variant="secondary" icon="support" onClick={onSupport}>Contact support</Button>}
        </div>
        {technical && (
          <div className="mt-5 w-full">
            <button
              type="button"
              onClick={() => setOpen((v) => !v)}
              aria-expanded={open}
              className="inline-flex items-center gap-1.5 font-display text-caption font-semibold text-ink-muted transition-colors duration-[var(--nx-dur-1)] hover:text-ink-secondary"
            >
              <Icon name="chevronRight" size="sm" className={open ? "rotate-90 transition-transform" : "transition-transform"} />
              View technical details
            </button>
            {open && (
              <pre className="nx-plate mt-2 overflow-x-auto px-3 py-2 text-left text-code text-ink-secondary">{technical}</pre>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

/* ------------------------------------------------------- SUCCESS STATE */
/** Rewarding without celebration effects: an elegant mark, the facts, and
    the one next action. */
export function SuccessState({
  title, summary, facts, action,
}: { title: string; summary?: string; facts?: { label: string; value: string; mono?: boolean }[]; action?: ReactNode }) {
  return (
    <div className="nx-container-surface px-6 py-10">
      <div className="mx-auto flex max-w-[52ch] flex-col items-center text-center">
        <span className="mb-4 flex h-12 w-12 items-center justify-center rounded-full border border-success-text/45 bg-success/25">
          <svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="var(--color-success-text)"
            strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
            <path d="m5 12.5 4.5 4.5L19 7" strokeDasharray="22" className="animate-nx-check" />
          </svg>
        </span>
        <h3 className="text-h2 text-ink">{title}</h3>
        {summary && <p className="mt-2 text-body-sm text-ink-secondary">{summary}</p>}
        {facts && (
          <dl className="mt-5 grid w-full grid-cols-1 gap-px overflow-hidden rounded-lg border border-hairline bg-hairline sm:grid-cols-2">
            {facts.map((f) => (
              <div key={f.label} className="bg-surface px-4 py-3 text-left">
                <dt className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">{f.label}</dt>
                <dd className={`mt-1 text-body-sm text-ink ${f.mono ? "font-mono text-code" : ""}`}>{f.value}</dd>
              </div>
            ))}
          </dl>
        )}
        {action && <div className="mt-5">{action}</div>}
      </div>
    </div>
  );
}

/* ---------------------------------------------------- DEPLOYMENT LADDER */
export type RungState = "done" | "active" | "pending" | "failed";
export interface Rung { label: string; state: RungState }

/**
 * The signature post-payment moment.
 *
 * Honesty rules, enforced by the component's own API:
 *   - it takes named stages, and there is no percentage prop to pass
 *   - it shows elapsed time and a typical range, never a countdown
 *   - past the expected window it says so and offers an action, rather than
 *     spinning silently
 * The backend reports six coarse stages and no progress figure, so six rungs
 * is exactly what this can honestly draw.
 */
export function DeploymentLadder({
  rungs, elapsedLabel, typicalLabel, overdue, onCheckStatus,
}: {
  rungs: Rung[]; elapsedLabel: string; typicalLabel: string;
  overdue?: boolean; onCheckStatus?: () => void;
}) {
  return (
    <div className="nx-container-surface overflow-hidden">
      <div className="flex flex-wrap items-baseline justify-between gap-2 border-b border-hairline px-5 py-3.5">
        <span className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">Provisioning</span>
        <span className="font-mono text-caption tabular-nums text-ink-secondary">
          {elapsedLabel} <span className="text-ink-muted">· {typicalLabel}</span>
        </span>
      </div>

      <ol className="px-5 py-2" aria-live="polite">
        {rungs.map((r, i) => (
          <li key={r.label} className="flex items-start gap-3 py-2.5">
            <span className="relative flex flex-col items-center self-stretch" aria-hidden="true">
              <span
                className={`mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full border
                  ${r.state === "done" ? "border-success-text/50 bg-success/30 text-success-text"
                    : r.state === "active" ? "border-signal-edge bg-signal/25 text-signal-text"
                    : r.state === "failed" ? "border-danger-text/50 bg-danger/25 text-danger-text"
                    : "border-hairline-strong text-ink-disabled"}`}
              >
                {r.state === "done" && <Icon name="check" size="sm" />}
                {r.state === "active" && <span className="h-1.5 w-1.5 rounded-full bg-current animate-nx-pulse" />}
                {r.state === "failed" && <Icon name="close" size="sm" />}
              </span>
              {i < rungs.length - 1 && (
                <span className={`w-px flex-1 ${r.state === "done" ? "bg-success-text/35" : "bg-hairline"}`} />
              )}
            </span>
            <span className={`pt-0.5 text-body-sm ${
              r.state === "pending" ? "text-ink-muted"
                : r.state === "failed" ? "text-danger-text"
                : "text-ink"}`}>
              {r.label}
            </span>
          </li>
        ))}
      </ol>

      {overdue && (
        <div className="border-t border-hairline px-5 py-3.5">
          <p className="text-body-sm text-warning-text">
            This is taking longer than usual. Your server is still being built and you have not been charged twice.
          </p>
          {onCheckStatus && (
            <Button variant="secondary" size="sm" icon="support" className="mt-2.5" onClick={onCheckStatus}>
              Check status
            </Button>
          )}
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------ SETUP CHECKLIST */
export interface Task { label: string; detail?: string; done: boolean; optional?: boolean; action?: ReactNode }

/** Stage two of a purchase, and the standing task list on the dashboard.
    Skipped items do not vanish; they persist as tasks. */
export function SetupChecklist({ title, tasks }: { title: string; tasks: Task[] }) {
  const done = tasks.filter((t) => t.done).length;
  return (
    <div className="nx-container-surface overflow-hidden">
      <div className="flex flex-wrap items-baseline justify-between gap-2 border-b border-hairline px-5 py-3.5">
        <span className="font-display text-h4 text-ink">{title}</span>
        <span className="font-mono text-caption tabular-nums text-ink-muted">{done} of {tasks.length} done</span>
      </div>
      <ul className="divide-y divide-hairline">
        {tasks.map((t) => (
          <li key={t.label} className="flex items-start gap-3 px-5 py-3.5">
            <span
              className={`mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full border ${
                t.done ? "border-success-text/50 bg-success/30 text-success-text" : "border-hairline-strong text-transparent"
              }`}
              aria-hidden="true"
            >
              <Icon name="check" size="sm" />
            </span>
            <span className="min-w-0 flex-1">
              <span className={`block text-body-sm font-medium ${t.done ? "text-ink-secondary line-through decoration-hairline-strong" : "text-ink"}`}>
                {t.label}
                {t.optional && !t.done && (
                  <span className="ml-2 font-display text-label uppercase tracking-[0.11em] text-ink-muted">Optional</span>
                )}
              </span>
              {t.detail && <span className="mt-0.5 block text-caption text-ink-muted">{t.detail}</span>}
            </span>
            {t.action && <span className="shrink-0 self-center">{t.action}</span>}
          </li>
        ))}
      </ul>
    </div>
  );
}

toolUseResult.content:
"use client";

/* ============================================================================
   LOADING, EMPTY, ERROR, SUCCESS — and the deployment ladder
   The old portal served all 58 routes from one loading file and one error
   file, showed "Something went wrong" eleven times, and had no not-found
   inside the shell at all. Each state here is a designed surface.
   ========================================================================= */

import { useState, type ReactNode } from "react";
import { Icon, type IconName } from "./Icon";
import { Button } from "./controls";

/* ------------------------------------------------------------ SKELETON */
export function Skeleton({ className = "" }: { className?: string }) {
  return <div className={`animate-nx-pulse rounded-sm bg-interactive ${className}`} aria-hidden="true" />;
}

/** Shape-matched loading. A skeleton should predict the content that follows,
    which is why this takes a shape rather than being one generic block. */
export function LoadingState({ shape = "list", label = "Loading" }: { shape?: "list" | "metrics" | "detail"; label?: string }) {
  return (
    <div role="status" aria-live="polite" aria-busy="true">
      <span className="sr-only">{label}…</span>
      {shape === "metrics" && (
        <div className="grid grid-cols-2 gap-px overflow-hidden rounded-lg border border-hairline bg-hairline lg:grid-cols-4">
          {Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="flex flex-col gap-2.5 bg-surface px-4 py-3.5">
              <Skeleton className="h-3 w-20" />
              <Skeleton className="h-7 w-24" />
            </div>
          ))}
        </div>
      )}
      {shape === "list" && (
        <div className="flex flex-col gap-2">
          {Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="nx-object flex items-center gap-4 px-4 py-3.5">
              <Skeleton className="h-8 w-8 rounded-md" />
              <div className="flex flex-1 flex-col gap-2">
                <Skeleton className="h-3.5 w-40" />
                <Skeleton className="h-3 w-64" />
              </div>
              <Skeleton className="h-7 w-20 rounded-md" />
            </div>
          ))}
        </div>
      )}
      {shape === "detail" && (
        <div className="flex flex-col gap-5">
          <Skeleton className="h-8 w-64" />
          <div className="grid gap-3 sm:grid-cols-2">
            <Skeleton className="h-24" /><Skeleton className="h-24" />
          </div>
          <Skeleton className="h-40" />
        </div>
      )}
    </div>
  );
}

export function Spinner({ label = "Working" }: { label?: string }) {
  return (
    <span role="status" className="inline-flex items-center gap-2 text-ink-muted">
      <Icon name="spinner" size="md" className="animate-spin" />
      <span className="text-body-sm">{label}…</span>
    </span>
  );
}

/* --------------------------------------------------------- EMPTY STATE */
/** Explains the situation and offers the next action. Never "No data." */
export function EmptyState({
  icon = "resources", title, description, action, secondary,
}: { icon?: IconName; title: string; description: string; action?: ReactNode; secondary?: ReactNode }) {
  return (
    <div className="nx-container-surface flex flex-col items-center px-6 py-14 text-center">
      <span className="mb-4 flex h-12 w-12 items-center justify-center rounded-lg border border-hairline-strong bg-plate text-signal-text">
        <Icon name={icon} size="lg" />
      </span>
      <h3 className="text-h3 text-ink">{title}</h3>
      <p className="mt-2 max-w-[46ch] text-body-sm text-ink-secondary">{description}</p>
      {(action || secondary) && (
        <div className="mt-5 flex flex-wrap items-center justify-center gap-2">{action}{secondary}</div>
      )}
    </div>
  );
}

/* --------------------------------------------------------- ERROR STATE */
/** What happened, why, and how to fix it. Technical detail is available but
    never leads — the old portal put a bare digest on screen in a tone that
    failed contrast. */
export function ErrorState({
  title, reason, fix, technical, onRetry, onSupport,
}: {
  title: string; reason?: string; fix?: string; technical?: string;
  onRetry?: () => void; onSupport?: () => void;
}) {
  const [open, setOpen] = useState(false);
  return (
    <div className="nx-container-surface px-6 py-10" role="alert">
      <div className="mx-auto flex max-w-[52ch] flex-col items-center text-center">
        <span className="mb-4 flex h-12 w-12 items-center justify-center rounded-lg border border-danger-text/40 bg-danger/20 text-danger-text">
          <Icon name="alert" size="lg" />
        </span>
        <h3 className="text-h3 text-ink">{title}</h3>
        {reason && <p className="mt-2 text-body-sm text-ink-secondary">{reason}</p>}
        {fix && <p className="mt-2 text-body-sm text-ink-secondary">{fix}</p>}
        <div className="mt-5 flex flex-wrap items-center justify-center gap-2">
          {onRetry && <Button variant="primary" icon="restart" onClick={onRetry}>Try again</Button>}
          {onSupport && <Button variant="secondary" icon="support" onClick={onSupport}>Contact support</Button>}
        </div>
        {technical && (
          <div className="mt-5 w-full">
            <button
              type="button"
              onClick={() => setOpen((v) => !v)}
              aria-expanded={open}
              className="inline-flex items-center gap-1.5 font-display text-caption font-semibold text-ink-muted transition-colors duration-[var(--nx-dur-1)] hover:text-ink-secondary"
            >
              <Icon name="chevronRight" size="sm" className={open ? "rotate-90 transition-transform" : "transition-transform"} />
              View technical details
            </button>
            {open && (
              <pre className="nx-plate mt-2 overflow-x-auto px-3 py-2 text-left text-code text-ink-secondary">{technical}</pre>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

/* ------------------------------------------------------- SUCCESS STATE */
/** Rewarding without celebration effects: an elegant mark, the facts, and
    the one next action. */
export function SuccessState({
  title, summary, facts, action,
}: { title: string; summary?: string; facts?: { label: string; value: string; mono?: boolean }[]; action?: ReactNode }) {
  return (
    <div className="nx-container-surface px-6 py-10">
      <div className="mx-auto flex max-w-[52ch] flex-col items-center text-center">
        <span className="mb-4 flex h-12 w-12 items-center justify-center rounded-full border border-success-text/45 bg-success/25">
          <svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="var(--color-success-text)"
            strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
            <path d="m5 12.5 4.5 4.5L19 7" strokeDasharray="22" className="animate-nx-check" />
          </svg>
        </span>
        <h3 className="text-h2 text-ink">{title}</h3>
        {summary && <p className="mt-2 text-body-sm text-ink-secondary">{summary}</p>}
        {facts && (
          <dl className="mt-5 grid w-full grid-cols-1 gap-px overflow-hidden rounded-lg border border-hairline bg-hairline sm:grid-cols-2">
            {facts.map((f) => (
              <div key={f.label} className="bg-surface px-4 py-3 text-left">
                <dt className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">{f.label}</dt>
                <dd className={`mt-1 text-body-sm text-ink ${f.mono ? "font-mono text-code" : ""}`}>{f.value}</dd>
              </div>
            ))}
          </dl>
        )}
        {action && <div className="mt-5">{action}</div>}
      </div>
    </div>
  );
}

/* ---------------------------------------------------- DEPLOYMENT LADDER */
export type RungState = "done" | "active" | "pending" | "failed";
export interface Rung { label: string; state: RungState }

/**
 * The signature post-payment moment.
 *
 * Honesty rules, enforced by the component's own API:
 *   - it takes named stages, and there is no percentage prop to pass
 *   - it shows elapsed time and a typical range, never a countdown
 *   - past the expected window it says so and offers an action, rather than
 *     spinning silently
 * The backend reports six coarse stages and no progress figure, so six rungs
 * is exactly what this can honestly draw.
 */
export function DeploymentLadder({
  rungs, elapsedLabel, typicalLabel, overdue, onCheckStatus,
}: {
  rungs: Rung[]; elapsedLabel: string; typicalLabel: string;
  overdue?: boolean; onCheckStatus?: () => void;
}) {
  return (
    <div className="nx-container-surface overflow-hidden">
      <div className="flex flex-wrap items-baseline justify-between gap-2 border-b border-hairline px-5 py-3.5">
        <span className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">Provisioning</span>
        <span className="font-mono text-caption tabular-nums text-ink-secondary">
          {elapsedLabel} <span className="text-ink-muted">· {typicalLabel}</span>
        </span>
      </div>

      <ol className="px-5 py-2" aria-live="polite">
        {rungs.map((r, i) => (
          <li key={r.label} className="flex items-start gap-3 py-2.5">
            <span className="relative flex flex-col items-center self-stretch" aria-hidden="true">
              <span
                className={`mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full border
                  ${r.state === "done" ? "border-success-text/50 bg-success/30 text-success-text"
                    : r.state === "active" ? "border-signal-edge bg-signal/25 text-signal-text"
                    : r.state === "failed" ? "border-danger-text/50 bg-danger/25 text-danger-text"
                    : "border-hairline-strong text-ink-disabled"}`}
              >
                {r.state === "done" && <Icon name="check" size="sm" />}
                {r.state === "active" && <span className="h-1.5 w-1.5 rounded-full bg-current animate-nx-pulse" />}
                {r.state === "failed" && <Icon name="close" size="sm" />}
              </span>
              {i < rungs.length - 1 && (
                <span className={`w-px flex-1 ${r.state === "done" ? "bg-success-text/35" : "bg-hairline"}`} />
              )}
            </span>
            <span className={`pt-0.5 text-body-sm ${
              r.state === "pending" ? "text-ink-muted"
                : r.state === "failed" ? "text-danger-text"
                : "text-ink"}`}>
              {r.label}
            </span>
          </li>
        ))}
      </ol>

      {overdue && (
        <div className="border-t border-hairline px-5 py-3.5">
          <p className="text-body-sm text-warning-text">
            This is taking longer than usual. Your server is still being built and you have not been charged twice.
          </p>
          {onCheckStatus && (
            <Button variant="secondary" size="sm" icon="support" className="mt-2.5" onClick={onCheckStatus}>
              Check status
            </Button>
          )}
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------ SETUP CHECKLIST */
export interface Task { label: string; detail?: string; done: boolean; optional?: boolean; action?: ReactNode }

/** Stage two of a purchase, and the standing task list on the dashboard.
    Skipped items do not vanish; they persist as tasks. */
export function SetupChecklist({ title, tasks }: { title: string; tasks: Task[] }) {
  const done = tasks.filter((t) => t.done).length;
  return (
    <div className="nx-container-surface overflow-hidden">
      <div className="flex flex-wrap items-baseline justify-between gap-2 border-b border-hairline px-5 py-3.5">
        <span className="font-display text-h4 text-ink">{title}</span>
        <span className="font-mono text-caption tabular-nums text-ink-muted">{done} of {tasks.length} done</span>
      </div>
      <ul className="divide-y divide-hairline">
        {tasks.map((t) => (
          <li key={t.label} className="flex items-start gap-3 px-5 py-3.5">
            <span
              className={`mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full border ${
                t.done ? "border-success-text/50 bg-success/30 text-success-text" : "border-hairline-strong text-transparent"
              }`}
              aria-hidden="true"
            >
              <Icon name="check" size="sm" />
            </span>
            <span className="min-w-0 flex-1">
              <span className={`block text-body-sm font-medium ${t.done ? "text-ink-secondary line-through decoration-hairline-strong" : "text-ink"}`}>
                {t.label}
                {t.optional && !t.done && (
                  <span className="ml-2 font-display text-label uppercase tracking-[0.11em] text-ink-muted">Optional</span>
                )}
              </span>
              {t.detail && <span className="mt-0.5 block text-caption text-ink-muted">{t.detail}</span>}
            </span>
            {t.action && <span className="shrink-0 self-center">{t.action}</span>}
          </li>
        ))}
      </ul>
    </div>
  );
}

input.content:
"use client";

/* ============================================================================
   CORE SHELL
   The foundational frame only — enough to demonstrate the system. No product
   pages are migrated into it in Phase 2.

   Geometry is a contract, not a per-page decision:
     rail 15rem (collapsed 4.5rem) · header 3.5rem · content max 90rem
   ========================================================================= */

import { useEffect, useState, type ReactNode } from "react";
import { Icon, type IconName } from "../system/Icon";
import { IconButton } from "../system/controls";
import { Badge } from "../system/primitives";

export interface NavItem {
  id: string;
  label: string;
  icon: IconName;
  badge?: string | number;
  /** Marks a kind the customer does not own yet — grouped under Explore. */
  owned?: boolean;
}
export interface NavGroup { label?: string; items: NavItem[] }

export function AppShell({
  groups, active, onNavigate, children, title = "Nxeon",
}: {
  groups: NavGroup[]; active: string; onNavigate: (id: string) => void;
  children: ReactNode; title?: string;
}) {
  const [collapsed, setCollapsed] = useState(false);
  const [drawer, setDrawer] = useState(false);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setDrawer(false); };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, []);

  const railWidth = collapsed ? "lg:w-18" : "lg:w-60";

  return (
    <div className="relative z-[var(--nx-z-raised)] flex min-h-screen">
      {/* Mobile scrim */}
      {drawer && (
        <div
          className="fixed inset-0 z-[var(--nx-z-scrim)] bg-scrim/75 lg:hidden"
          onClick={() => setDrawer(false)}
          aria-hidden="true"
        />
      )}

      {/* ---------------------------------------------------------- RAIL */}
      <aside
        id="nx-rail"
        inert={!drawer && typeof window !== "undefined" && window.innerWidth < 1024 ? true : undefined}
        className={`fixed inset-y-0 left-0 z-[var(--nx-z-rail)] flex w-60 flex-col border-r border-hairline bg-surface
          transition-transform duration-[var(--nx-dur-3)] ease-[var(--nx-ease)]
          ${drawer ? "translate-x-0" : "-translate-x-full"}
          lg:sticky lg:top-0 lg:h-screen lg:translate-x-0 ${railWidth}`}
      >
        {/* Brand */}
        <div className="flex h-14 shrink-0 items-center gap-2.5 border-b border-hairline px-4">
          <NxeonMark />
          {!collapsed && (
            <span className="font-display text-h4 font-bold tracking-[-0.01em] text-ink">{title}</span>
          )}
          <div className="ml-auto lg:hidden">
            <IconButton name="close" label="Close navigation" size="sm" onClick={() => setDrawer(false)} />
          </div>
        </div>

        {/* Nav */}
        <nav aria-label="Primary" className="min-h-0 flex-1 overflow-y-auto px-2.5 py-3">
          {groups.map((g, gi) => (
            <div key={g.label ?? gi} className="mb-4 last:mb-0">
              {g.label && !collapsed && (
                <div className="mb-1.5 px-2 font-display text-label uppercase tracking-[0.13em] text-ink-muted">
                  {g.label}
                </div>
              )}
              {g.label && collapsed && <div className="mx-2 mb-2 h-px bg-hairline" />}
              <ul className="flex flex-col gap-0.5">
                {g.items.map((it) => {
                  const on = it.id === active;
                  return (
                    <li key={it.id}>
                      <button
                        type="button"
                        onClick={() => { onNavigate(it.id); setDrawer(false); }}
                        aria-current={on ? "page" : undefined}
                        title={collapsed ? it.label : undefined}
                        className={`group relative flex w-full items-center gap-2.5 rounded-md py-2 pl-3 pr-2 text-left
                          font-display text-body-sm font-medium
                          transition-colors duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
                          ${on ? "bg-interactive text-ink" : "text-ink-secondary hover:bg-surface hover:text-ink"}
                          ${collapsed ? "lg:justify-center lg:px-0" : ""}`}
                      >
                        {/* The Nxeon active indicator: a signal filament, not a filled pill */}
                        <span
                          className={`absolute left-0 top-1/2 h-5 w-0.5 -translate-y-1/2 rounded-pill transition-all duration-[var(--nx-dur-1)] ${
                            on ? "bg-signal-edge opacity-100" : "bg-transparent opacity-0"
                          }`}
                          aria-hidden="true"
                        />
                        <Icon name={it.icon} size="md" className={on ? "text-signal-text" : "text-ink-muted group-hover:text-ink-secondary"} />
                        {!collapsed && <span className="flex-1 truncate">{it.label}</span>}
                        {!collapsed && it.badge !== undefined && (
                          <span className="rounded-sm bg-plate px-1.5 py-0.5 font-mono text-[0.6875rem] tabular-nums text-ink-secondary">
                            {it.badge}
                          </span>
                        )}
                        {collapsed && it.badge !== undefined && (
                          <span className="absolute right-2 top-1.5 h-1.5 w-1.5 rounded-full bg-signal-edge" aria-hidden="true" />
                        )}
                      </button>
                    </li>
                  );
                })}
              </ul>
            </div>
          ))}
        </nav>

        {/* Rail footer */}
        <div className="shrink-0 border-t border-hairline p-2.5">
          <button
            type="button"
            onClick={() => setCollapsed((v) => !v)}
            className={`hidden w-full items-center gap-2.5 rounded-md px-3 py-2 font-display text-caption font-medium text-ink-muted transition-colors duration-[var(--nx-dur-1)] hover:bg-surface hover:text-ink lg:flex ${
              collapsed ? "justify-center px-0" : ""
            }`}
            aria-label={collapsed ? "Expand navigation" : "Collapse navigation"}
          >
            <Icon name="collapse" size="md" className={collapsed ? "rotate-180" : ""} />
            {!collapsed && <span>Collapse</span>}
          </button>
        </div>
      </aside>

      {/* -------------------------------------------------------- COLUMN */}
      <div className="flex min-w-0 flex-1 flex-col">
        <header className="sticky top-0 z-[var(--nx-z-sticky)] flex h-14 shrink-0 items-center gap-3 border-b border-hairline bg-base/85 px-4 backdrop-blur-md sm:px-6">
          <div className="lg:hidden">
            <IconButton
              name="menu" label="Open navigation" size="sm"
              aria-expanded={drawer} aria-controls="nx-rail"
              onClick={() => setDrawer(true)}
            />
          </div>

          <button
            type="button"
            className="group flex h-9 min-w-0 flex-1 items-center gap-2.5 rounded-md border border-hairline bg-surface px-3 text-left transition-colors duration-[var(--nx-dur-1)] hover:border-hairline-strong sm:max-w-md"
          >
            <Icon name="search" size="md" className="text-ink-muted" />
            <span className="flex-1 truncate text-body-sm text-ink-muted">Search or run a command…</span>
            <kbd className="hidden rounded-sm border border-hairline-strong bg-plate px-1.5 py-0.5 font-mono text-[0.6875rem] text-ink-muted sm:block">
              ⌘K
            </kbd>
          </button>

          <div className="ml-auto flex items-center gap-1.5">
            <span className="hidden sm:block"><Badge tone="signal" size="sm">Sandbox</Badge></span>
            <IconButton name="bell" label="Notifications" size="sm" />
            <span className="ml-1 flex h-8 w-8 items-center justify-center rounded-md border border-hairline-strong bg-interactive font-display text-caption font-semibold text-ink">
              N
            </span>
          </div>
        </header>

        <main id="nx-main" className="mx-auto w-full max-w-[90rem] flex-1 px-4 py-7 sm:px-6 lg:px-8">
          {children}
        </main>
      </div>
    </div>
  );
}

/** The mark, drawn rather than raster — the audit found no vector master
    existed and every consumer scaled one 496x85 PNG. */
export function NxeonMark({ size = 22 }: { size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" aria-hidden="true" className="shrink-0">
      <path d="M3 20V4l9 12V4" fill="none" stroke="var(--color-signal-text)" strokeWidth="2.1"
        strokeLinecap="round" strokeLinejoin="round" />
      <path d="M15.5 8.5 21 15.5M21 8.5l-5.5 7" fill="none" stroke="var(--color-ink)" strokeWidth="2.1"
        strokeLinecap="round" />
    </svg>
  );
}

