"use client";

/* Showcase — patterns: the composed Nxeon signatures. These are the pieces
   later phases assemble product pages from. */

import { useEffect, useState } from "react";
import {
  PageHeader, SectionRule, Container, ObjectSurface, DataPlate,
  StatusIndicator, MetaItem, Badge,
} from "@/components/system/primitives";
import { Button, Field, Input, Radio, Toggle } from "@/components/system/controls";
import { Wizard, Stepper } from "@/components/system/navigation";
import { DeploymentLadder, SetupChecklist, type Rung } from "@/components/system/states";
import { ResourceMeter, MetricTile, Sparkline } from "@/components/system/data";
import { Alert } from "@/components/system/overlays";
import { CPU_SERIES } from "@/lib/mock";

/* ------------------------------------------------- THE DEPLOYMENT LADDER */
const LADDER: string[] = [
  "Allocating your server",
  "Configuring the network",
  "Starting your server",
  "Booting the operating system",
  "Waiting for network access",
];

export function Ladder() {
  const [at, setAt] = useState(1);
  const [secs, setSecs] = useState(38);

  useEffect(() => {
    const t = window.setInterval(() => setSecs((s) => s + 1), 1000);
    return () => window.clearInterval(t);
  }, []);

  const rungs: Rung[] = LADDER.map((label, i) => ({
    label,
    state: i < at ? "done" : i === at ? "active" : "pending",
  }));

  const mm = String(Math.floor(secs / 60)).padStart(2, "0");
  const ss = String(secs % 60).padStart(2, "0");

  return (
    <>
      <PageHeader
        eyebrow="Patterns"
        title="Deployment ladder"
        description="The signature post-payment moment, and the pattern with the strictest rule in the system: it may never claim more than the backend knows."
      />

      <Alert tone="signal" title="Why there is no percentage here">
        The provisioning worker writes exactly six coarse step labels and no progress figure, no
        estimate and no status endpoint. So the component takes named stages and has no percentage
        prop to pass. It shows elapsed time and a typical range instead of a countdown it cannot honour.
      </Alert>

      <div className="mt-5 grid gap-4 lg:grid-cols-[minmax(0,1fr)_320px]">
        <DeploymentLadder
          rungs={rungs}
          elapsedLabel={`${mm}:${ss} elapsed`}
          typicalLabel="usually 1–3 min"
          overdue={at >= LADDER.length - 1}
          onCheckStatus={() => {}}
        />
        <Container className="flex flex-col gap-4 self-start px-5 py-5">
          <h3 className="text-h4 text-ink">Demonstration</h3>
          <p className="text-caption text-ink-muted">
            Step through the real backend states. Nothing here is interpolated.
          </p>
          <div className="flex gap-2">
            <Button size="sm" variant="secondary" onClick={() => setAt((n) => Math.max(0, n - 1))}>Back</Button>
            <Button size="sm" variant="primary" onClick={() => setAt((n) => Math.min(LADDER.length, n + 1))}>Advance</Button>
          </div>
          <div className="border-t border-hairline pt-4">
            <p className="text-caption text-ink-secondary">
              Past the expected window the message changes to say so and offers an action, rather than
              spinning silently. Advance to the last rung to see it.
            </p>
          </div>
        </Container>
      </div>

      <SectionRule label="First value arrives as soon as it exists" />
      <p className="mb-4 max-w-[68ch] text-body-sm text-ink-secondary">
        Connection details are shown the moment the address is assigned, marked as not ready until boot
        completes — rather than withheld until the very end.
      </p>
      <div className="grid gap-3 sm:grid-cols-2">
        <DataPlate label="Public address" value="198.51.100.24" />
        <DataPlate label="Shell access" value="ssh root@198.51.100.24" />
      </div>
    </>
  );
}

/* ------------------------------------------------------ TWO-STAGE BUY */
export function Checkout() {
  const [step, setStep] = useState(0);
  const [tier, setTier] = useState("pro");
  const [term, setTerm] = useState("annual");

  const monthly = tier === "starter" ? 8.88 : tier === "standard" ? 12.99 : 20.99;
  const rate = term === "annual" ? monthly * 0.8 : monthly;

  return (
    <>
      <PageHeader
        eyebrow="Patterns"
        title="Two-stage checkout"
        description="Stage one asks only what sets the price. For game servers every remaining field has a live-change API, so the whole configuration step moves after payment — four steps become two."
      />

      <Wizard
        steps={[{ id: "plan", label: "Plan" }, { id: "pay", label: "Pay" }]}
        current={step}
        onBack={() => setStep(0)}
        summary={
          <div className="flex items-baseline gap-2">
            <span className="font-display text-metric-sm tabular-nums text-ink">${rate.toFixed(2)}</span>
            <span className="text-caption text-ink-muted">
              /mo{term === "annual" ? ` · $${(rate * 12).toFixed(2)} billed yearly` : ""}
            </span>
          </div>
        }
        primary={
          step === 0
            ? <Button variant="primary" iconRight="arrowRight" onClick={() => setStep(1)}>Continue</Button>
            : <Button variant="primary" icon="deploy">Pay ${rate.toFixed(2)} and deploy</Button>
        }
      >
        {step === 0 ? (
          <div className="flex flex-col gap-6">
            <div>
              <h3 className="text-h3 text-ink">Choose your plan</h3>
              <p className="mt-1 max-w-[62ch] text-body-sm text-ink-secondary">
                These two choices set the price. Everything else — name, address, server type and
                configuration — you set after payment, and can change at any time.
              </p>
            </div>
            <div className="grid gap-3 sm:grid-cols-3">
              {[
                { id: "starter", name: "Starter", specs: "1 vCPU · 2 GB · 25 GB", best: "Up to 10 players" },
                { id: "pro", name: "Pro", specs: "3 vCPU · 8 GB · 80 GB", best: "Up to 40 players, modded" },
                { id: "max", name: "Max", specs: "4 vCPU · 16 GB · 120 GB", best: "Large modpacks" },
              ].map((p) => (
                <button
                  key={p.id}
                  type="button"
                  onClick={() => setTier(p.id)}
                  className={`nx-object px-4 py-4 text-left transition-colors duration-[var(--nx-dur-1)] ${
                    tier === p.id ? "!border-signal-edge bg-interactive" : "hover:bg-interactive"
                  }`}
                >
                  <div className="flex items-center justify-between gap-2 pl-1">
                    <span className="font-display text-h4 text-ink">{p.name}</span>
                    {p.id === "pro" && <Badge tone="signal" size="sm">Recommended</Badge>}
                  </div>
                  <p className="mt-2 pl-1 font-mono text-caption text-ink-muted">{p.specs}</p>
                  <p className="mt-1.5 pl-1 text-caption text-ink-secondary">{p.best}</p>
                </button>
              ))}
            </div>
            <div className="flex flex-col gap-3 border-t border-hairline pt-5">
              <Radio name="t" checked={term === "monthly"} onChange={() => setTerm("monthly")}
                label="Monthly" description={`$${monthly.toFixed(2)} per month, cancel any time`} />
              <Radio name="t" checked={term === "annual"} onChange={() => setTerm("annual")}
                label="Annual — save 20%"
                description={`$${(monthly * 0.8).toFixed(2)} per month for the first year, then $${monthly.toFixed(2)} per month`} />
            </div>
            <p className="max-w-[62ch] text-caption text-ink-muted">
