                <div className="flex justify-between gap-3"><dt className="text-ink-secondary">Tax</dt><dd className="text-ink">Included</dd></div>
                <div className="mt-1 flex justify-between gap-3 border-t border-hairline pt-2.5">
                  <dt className="font-display font-semibold text-ink">Due today</dt>
                  <dd className="font-display text-metric-sm tabular-nums text-ink">
