=== sandbox vhost ===
# Isolated UI/UX sandbox — separate app, DB, and codebase from prod/staging.
# Fake wallet balance only; payAndDeploy/registerDomain are SANDBOX-gated to
# never reach Stripe/name.com. Proxies to its own nxeon-sandbox-web instance.
server {
    listen 80;
    listen [::]:80;
    server_name flow.k9x4rq7wpz2ah6t.nxeon.cloud;
    location /.well-known/acme-challenge/ { root /var/www/certbot; }
    location / { return 301 https://$host$request_uri; }
}
server {
    listen 443 ssl;
    listen [::]:443 ssl;
    http2 on;
    server_name flow.k9x4rq7wpz2ah6t.nxeon.cloud;
    ssl_certificate /etc/letsencrypt/live/nxeon-sandbox/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/nxeon-sandbox/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;
    client_max_body_size 20m;
    error_page 502 503 504 /maintenance.html;
    location = /maintenance.html {
        root /opt/nxeon-sandbox/public;
        internal;
    }
    location / {
        proxy_pass http://127.0.0.1:3002;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
}
