33	    "bg-transparent text-danger-text border border-danger-text/40 hover:bg-danger/25 hover:border-danger-text/70 active:bg-danger/35",
34	  ai:
35	    "bg-ai text-white border border-ai hover:brightness-110 active:brightness-95",
36	};
37	
38	const SIZE: Record<Size, string> = {
39	  sm: "h-8 px-3 text-[0.8125rem] gap-1.5",
40	  md: "h-10 px-4 text-body-sm gap-2",
41	  lg: "h-12 px-5 text-body gap-2",
42	};
43	
44	export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
45	  variant?: Variant;
46	  size?: Size;
47	  loading?: boolean;
48	  icon?: IconName;
49	  iconRight?: IconName;
50	  block?: boolean;
51	}
52	
53	export function Button({
54	  variant = "secondary", size = "md", loading, icon, iconRight, block,
55	  className = "", children, disabled, ...rest
56	}: ButtonProps) {
57	  return (
58	    <button
59	      className={`inline-flex items-center justify-center rounded-md font-display font-semibold
60	        transition-[background-color,border-color,color] duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
61	        disabled:cursor-not-allowed disabled:opacity-45
62	        ${VARIANT[variant]} ${SIZE[size]} ${block ? "w-full" : ""} ${className}`}
63	      disabled={disabled || loading}
64	      aria-busy={loading || undefined}
65	      {...rest}
66	    >
67	      {loading ? (
68	        <Icon name="spinner" size={size === "lg" ? "lg" : "md"} className="animate-spin" />
69	      ) : icon ? (
70	        <Icon name={icon} size={size === "lg" ? "lg" : "md"} />
71	      ) : null}
72	      {children}
73	      {iconRight && !loading && <Icon name={iconRight} size={size === "lg" ? "lg" : "md"} />}
74	    </button>
75	  );
76	}
77	
78	/** Icon-only control. The label is required, not optional — that is how the
79	    nine unnamed icon buttons in the old portal stop being possible. */
80	export function IconButton({
81	  name, label, variant = "ghost", size = "md", className = "", ...rest
82	}: { name: IconName; label: string; variant?: Variant; size?: Size } & ButtonHTMLAttributes<HTMLButtonElement>) {
83	  const box = size === "sm" ? "h-8 w-8" : size === "lg" ? "h-12 w-12" : "h-10 w-10";
84	  return (
85	    <button
86	      aria-label={label}
87	      title={label}
88	      className={`inline-flex items-center justify-center rounded-md
89	        transition-[background-color,border-color,color] duration-[var(--nx-dur-1)] ease-[var(--nx-ease)]
90	        disabled:cursor-not-allowed disabled:opacity-45 ${VARIANT[variant]} ${box} ${className}`}
91	      {...rest}
92	    >
93	      <Icon name={name} size={size === "sm" ? "sm" : size === "lg" ? "lg" : "md"} />
94	    </button>
95	  );
96	}
97	
98	/* -------------------------------------------------------------- FIELD */
99	interface FieldProps {
100	  label: string;
101	  hint?: string;
102	  error?: string;
103	  success?: string;
104	  required?: boolean;
105	  children: (props: { id: string; describedBy?: string; invalid: boolean }) => ReactNode;
106	}
107	/** One label, hint, error and success structure for every form in the
108	    product. 61% of labels in the old portal had no programmatic association;
109	    here association is produced by the wrapper, not by discipline. */
110	export function Field({ label, hint, error, success, required, children }: FieldProps) {
111	  const id = useId();
112	  const hintId = `${id}-hint`;
113	  const msgId = `${id}-msg`;
114	  const describedBy = [hint ? hintId : null, error || success ? msgId : null]
115	    .filter(Boolean).join(" ") || undefined;
116	
117	  return (
118	    <div className="flex flex-col gap-1.5">
119	      <label htmlFor={id} className="font-display text-label uppercase tracking-[0.11em] text-ink-secondary">
120	        {label}
121	        {required && <span className="ml-1 text-danger-text" aria-hidden="true">*</span>}
122	      </label>
123	      {hint && <p id={hintId} className="text-caption text-ink-muted">{hint}</p>}
124	      {children({ id, describedBy, invalid: Boolean(error) })}
125	      {(error || success) && (
126	        <p
127	          id={msgId}
128	          role={error ? "alert" : "status"}
129	          className={`flex items-start gap-1.5 text-caption ${error ? "text-danger-text" : "text-success-text"}`}
130	        >
131	          <Icon name={error ? "alert" : "check"} size="sm" className="mt-0.5" />
132	          <span>{error || success}</span>
133	        </p>
134	      )}
135	    </div>
136	  );
137	}
138	
139	const CONTROL_BASE =
140	  "w-full rounded-md border bg-plate px-3 text-body text-ink placeholder:text-ink-muted " +
141	  "transition-[border-color,background-color] duration-[var(--nx-dur-1)] " +
142	  "hover:border-hairline-strong disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:border-hairline";
143	
144	/* -------------------------------------------------------------- INPUT */
145	export function Input({
146	  invalid, mono, className = "", ...rest
147	}: { invalid?: boolean; mono?: boolean } & InputHTMLAttributes<HTMLInputElement>) {
148	  return (
149	    <input
150	      aria-invalid={invalid || undefined}
151	      className={`${CONTROL_BASE} h-10 ${invalid ? "border-danger-text/60" : "border-hairline"} ${mono ? "font-mono text-code" : ""} ${className}`}
152	      {...rest}
153	    />
154	  );
155	}
156	
157	/* ------------------------------------------------------------- SELECT */
158	export function Select({
159	  invalid, className = "", children, ...rest
160	}: { invalid?: boolean } & SelectHTMLAttributes<HTMLSelectElement>) {
161	  return (
162	    <div className="relative">
163	      <select
164	        aria-invalid={invalid || undefined}
165	        className={`${CONTROL_BASE} h-10 appearance-none pr-9 ${invalid ? "border-danger-text/60" : "border-hairline"} ${className}`}
166	        {...rest}
167	      >
168	        {children}
169	      </select>
170	      <Icon name="chevronDown" size="md"
171	        className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-ink-muted" />
172	    </div>
173	  );
174	}
175	
176	/* ----------------------------------------------------------- TEXTAREA */
177	export function Textarea({
178	  invalid, className = "", ...rest
179	}: { invalid?: boolean } & InputHTMLAttributes<HTMLTextAreaElement>) {
180	  return (
181	    <textarea
182	      aria-invalid={invalid || undefined}
183	      className={`${CONTROL_BASE} min-h-24 resize-y py-2.5 ${invalid ? "border-danger-text/60" : "border-hairline"} ${className}`}
184	      {...(rest as object)}
185	    />
186	  );
187	}
