"use client";

/* Showcase — patterns: the composed Nxeon signatures. */

import { useEffect, useState } from "react";
import {
  PageHeader, SectionRule, Container, ObjectSurface, DataPlate,
  StatusIndicator, MetaItem, Badge,
} from "@/components/system/primitives";
import { Button, Radio, Toggle } from "@/components/system/controls";
import { Stepper } from "@/components/system/navigation";
import { DeploymentLadder, SetupChecklist, type Rung } from "@/components/system/states";
import { ResourceMeter, MetricTile, Sparkline } from "@/components/system/data";
import { Alert } from "@/components/system/overlays";
import { RegionMap, TopologyDiagram, NodeField, NXEON_REGIONS } from "@/components/system/Topology";
import { Assembling } from "@/components/system/illustrations";
import { CPU_SERIES } from "@/lib/mock";

/* ================================================================ LADDER */
const LADDER: string[] = [
  "Allocating your server",
  "Configuring the network",
  "Starting your server",
  "Booting the operating system",
  "Waiting for network access",
];

export function Ladder() {
  const [at, setAt] = useState(1);
  const [secs, setSecs] = useState(38);
  useEffect(() => {
    const t = window.setInterval(() => setSecs((s) => s + 1), 1000);
    return () => window.clearInterval(t);
  }, []);

  const rungs: Rung[] = LADDER.map((label, i) => ({
    label, state: i < at ? "done" : i === at ? "active" : "pending",
  }));
  const mm = String(Math.floor(secs / 60)).padStart(2, "0");
  const ss = String(secs % 60).padStart(2, "0");

  return (
    <>
      <PageHeader
        eyebrow="Patterns"
        title="Deployment ladder"
        description="The signature post-payment moment, and the pattern with the strictest rule in the system: it may never claim more than the backend knows."
      />

      {/* The brand moment: gradient, grid and node field, used once */}
      <div className="nx-container-surface relative mb-5 overflow-hidden">
        <span className="nx-grad-rule absolute inset-x-0 top-0" aria-hidden="true" />
        <div className="nx-grid-field nx-grid-mask pointer-events-none absolute inset-0" aria-hidden="true" />
        <NodeField />
        <div className="relative flex flex-wrap items-center gap-6 px-6 py-7">
          <Assembling size={150} />
          <div className="min-w-0 flex-1">
            <p className="font-display text-label uppercase tracking-[0.13em] text-ink-muted">Deploying</p>
            <h2 className="mt-1 text-h1"><span className="nx-grad-text">survival-smp</span></h2>
            <p className="mt-1.5 max-w-[52ch] text-body-sm text-ink-secondary">
              Minecraft · Pro · Singapore. You can close this tab — we will email you when it is ready.
            </p>
          </div>
        </div>
      </div>

      <Alert tone="signal" title="Why there is no percentage here">
        The provisioning worker writes exactly six coarse step labels and no progress figure, no
        estimate and no status endpoint. So the component takes named stages and has no percentage
        prop to pass. It shows elapsed time and a typical range instead of a countdown it cannot honour.
      </Alert>

      <div className="mt-4 grid gap-4 lg:grid-cols-[minmax(0,1fr)_300px]">
        <DeploymentLadder
          rungs={rungs}
          elapsedLabel={`${mm}:${ss} elapsed`}
          typicalLabel="usually 1–3 min"
          overdue={at >= LADDER.length - 1}
          onCheckStatus={() => {}}
        />
        <Container className="flex flex-col gap-3 self-start px-5 py-5">
          <h3 className="text-h4 text-ink">Demonstration</h3>
          <p className="text-caption text-ink-muted">Step through the real backend states. Nothing is interpolated.</p>
          <div className="flex gap-2">
            <Button size="sm" variant="secondary" onClick={() => setAt((n) => Math.max(0, n - 1))}>Back</Button>
            <Button size="sm" variant="primary" onClick={() => setAt((n) => Math.min(LADDER.length, n + 1))}>Advance</Button>
          </div>
          <p className="border-t border-hairline pt-3 text-caption text-ink-secondary">
            Past the expected window the message changes and offers an action, rather than spinning
            silently. Advance to the last rung to see it.
          </p>
        </Container>
      </div>

      <SectionRule label="First value arrives as soon as it exists" />
      <div className="grid gap-3 sm:grid-cols-2">
        <DataPlate label="Connect address" value="play.example.nx:25565" />
        <DataPlate label="Console password" value="w8Rq-4Tz9-Lm2P" masked />
      </div>
    </>
  );
}

/* ============================================================== CHECKOUT */
const TIERS = [
  { id: "starter", name: "Starter", price: 8.88,  cpu: "1 vCPU", ram: "2 GB", disk: "25 GB",  players: "Up to 10 players" },
  { id: "pro",     name: "Pro",     price: 20.99, cpu: "3 vCPU", ram: "8 GB", disk: "80 GB",  players: "Up to 40, modded" },
  { id: "max",     name: "Max",     price: 32.99, cpu: "4 vCPU", ram: "16 GB", disk: "120 GB", players: "Large modpacks" },
];

export function Checkout() {
  const [step, setStep] = useState(0);
  const [tier, setTier] = useState("pro");
  const [region, setRegion] = useState("sgp");
  const [term, setTerm] = useState<"monthly" | "annual">("annual");

  const plan = TIERS.find((t) => t.id === tier)!;
  const rate = term === "annual" ? plan.price * 0.8 : plan.price;
  const dueToday = term === "annual" ? rate * 12 : rate;
  const regionLabel = NXEON_REGIONS.find((r) => r.id === region)?.label ?? "";

  return (
    <>
      <PageHeader
        eyebrow="Patterns"
        title="Two-stage checkout"
        description="Stage one asks only what sets the price. For game servers every remaining field has a live-change API, so the whole configuration step moves after payment — four steps become two."
      />

      <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_320px] lg:items-start">
        {/* ---------------------------------------------------- main column */}
        <div className="min-w-0">
          <div className="nx-container-surface relative overflow-hidden">
            <span className="nx-grad-rule absolute inset-x-0 top-0" aria-hidden="true" />
            <div className="border-b border-hairline px-5 py-4">
              <Stepper steps={[{ id: "plan", label: "Plan and region" }, { id: "pay", label: "Payment" }]} current={step} />
            </div>

            {step === 0 ? (
              <div className="flex flex-col gap-7 px-5 py-6">
                <div>
                  <h3 className="text-h2 text-ink">Choose your plan</h3>
                  <p className="mt-1.5 max-w-[58ch] text-body-sm text-ink-secondary">
                    These are the only choices that change the price. Server name, connect address,
                    version and every setting come after payment, and change any time.
                  </p>
                </div>

                {/* Plan cards — objects, so they carry the notch and read as things */}
                <div className="grid gap-3 sm:grid-cols-3">
                  {TIERS.map((t) => {
                    const on = t.id === tier;
                    return (
                      <button
                        key={t.id}
                        type="button"
                        onClick={() => setTier(t.id)}
                        aria-pressed={on}
                        className={`nx-object nx-object-interactive ${on ? "nx-object-selected" : ""} px-4 pb-4 pt-3.5 text-left`}
                      >
                        <div className="flex items-start justify-between gap-2">
                          <span className="font-display text-h3 text-ink">{t.name}</span>
                          {t.id === "pro" && (
                            <span className="nx-grad-brand rounded-sm px-1.5 py-0.5 font-display text-[0.625rem] font-semibold uppercase tracking-[0.09em] text-white">
                              Popular
                            </span>
                          )}
                        </div>

                        <div className="mt-3 flex items-baseline gap-1">
                          <span className="font-display text-metric tabular-nums text-ink">
                            ${(term === "annual" ? t.price * 0.8 : t.price).toFixed(2)}
                          </span>
                          <span className="text-caption text-ink-muted">/mo</span>
                        </div>

                        <dl className="mt-3.5 flex flex-col gap-1 border-t border-hairline pt-3">
                          {[["CPU", t.cpu], ["Memory", t.ram], ["NVMe", t.disk]].map(([k, v]) => (
                            <div key={k} className="flex items-baseline justify-between gap-2">
                              <dt className="font-display text-[0.6875rem] uppercase tracking-[0.1em] text-ink-muted">{k}</dt>
                              <dd className="font-mono text-caption text-ink-secondary">{v}</dd>
                            </div>
                          ))}
                        </dl>
                        <p className="mt-3 text-caption text-ink-muted">{t.players}</p>
                      </button>
                    );
                  })}
                </div>

                {/* Region, as a network rather than a dropdown */}
                <div>
                  <div className="nx-rule mb-3">
                    <span className="nx-rule-label">Region</span>
                  </div>
                  <RegionMap value={region} onChange={setRegion} height={240} />
                  <p className="mt-2 text-caption text-ink-muted">
                    Latency is measured from your location. Los Angeles is at capacity today.
                  </p>
                </div>

                {/* Term */}
                <div>
                  <div className="nx-rule mb-3"><span className="nx-rule-label">Billing term</span></div>
                  <div className="grid gap-2 sm:grid-cols-2">
                    <label className={`nx-object nx-object-interactive ${term === "monthly" ? "nx-object-selected" : ""} cursor-pointer px-4 py-3`}>
                      <Radio name="term" checked={term === "monthly"} onChange={() => setTerm("monthly")}
                        label="Monthly" description={`$${plan.price.toFixed(2)} per month · cancel any time`} />
                    </label>
                    <label className={`nx-object nx-object-interactive ${term === "annual" ? "nx-object-selected" : ""} cursor-pointer px-4 py-3`}>
                      <Radio name="term" checked={term === "annual"} onChange={() => setTerm("annual")}
                        label="Annual · save 20%"
                        description={`$${(plan.price * 0.8).toFixed(2)}/mo for year one, then $${plan.price.toFixed(2)}/mo`} />
                    </label>
                  </div>
                </div>
              </div>
            ) : (
              <div className="flex flex-col gap-6 px-5 py-6">
                <div>
                  <h3 className="text-h2 text-ink">Payment</h3>
                  <p className="mt-1.5 text-body-sm text-ink-secondary">Secure, and the last step before your server is built.</p>
                </div>
                <div className="flex flex-col gap-4">
                  <DataPlate label="Card number" value="4242 4242 4242 4242" copyable={false} />
                  <div className="grid grid-cols-2 gap-4">
                    <DataPlate label="Expiry" value="04 / 28" copyable={false} />
                    <DataPlate label="Security code" value="•••" copyable={false} />
                  </div>
                </div>
                <Alert tone="neutral" title="No add-ons on this step">
                  Complements are offered before or after payment, never here. Trust is most fragile
                  at the moment of paying.
                </Alert>
              </div>
            )}
          </div>
        </div>

        {/* ------------------------------------------------------ order rail */}
        <aside className="lg:sticky lg:top-20">
          <div className="nx-container-surface relative overflow-hidden">
            <div className="nx-grid-field nx-grid-mask pointer-events-none absolute inset-0" aria-hidden="true" />
            <div className="relative px-5 py-4">
              <p className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">Your order</p>
              <p className="mt-2 font-display text-h3 text-ink">Minecraft · {plan.name}</p>
              <p className="mt-0.5 font-mono text-caption text-ink-muted">{plan.cpu} · {plan.ram} · {plan.disk}</p>

              <dl className="mt-4 flex flex-col gap-2 border-t border-hairline pt-3.5 text-body-sm">
                <div className="flex justify-between gap-3"><dt className="text-ink-secondary">Region</dt><dd className="text-ink">{regionLabel}</dd></div>
                <div className="flex justify-between gap-3"><dt className="text-ink-secondary">Term</dt><dd className="text-ink">{term === "annual" ? "Annual" : "Monthly"}</dd></div>
                <div className="flex justify-between gap-3"><dt className="text-ink-secondary">Tax</dt><dd className="text-ink">Included</dd></div>
              </dl>

              <div className="mt-3.5 border-t border-hairline pt-3.5">
                <div className="flex items-baseline justify-between gap-3">
                  <span className="font-display text-h4 text-ink">Due today</span>
                  <span className="font-display text-metric tabular-nums text-ink">${dueToday.toFixed(2)}</span>
                </div>
                <p className="mt-1 text-caption text-ink-muted">
                  Then ${term === "annual" ? plan.price.toFixed(2) : rate.toFixed(2)} per month
                  {term === "annual" ? ", billed yearly from next year" : ""}.
                </p>
              </div>

              <div className="mt-4">
                {step === 0 ? (
                  <Button variant="brand" size="lg" block iconRight="arrowRight" onClick={() => setStep(1)}>
                    Continue to payment
                  </Button>
                ) : (
                  <Button variant="brand" size="lg" block icon="deploy">
                    Pay ${dueToday.toFixed(2)} and deploy
                  </Button>
                )}
                {step === 1 && (
                  <Button variant="ghost" size="sm" block className="mt-1.5" onClick={() => setStep(0)}>
                    Back to plan
                  </Button>
                )}
              </div>

              <ul className="mt-4 flex flex-col gap-1.5 border-t border-hairline pt-3.5 text-caption text-ink-muted">
                <li>Both prices shown before you pay.</li>
                <li>Change plan any time, up or down.</li>
                <li>Everything else is set after payment.</li>
              </ul>
            </div>
          </div>
        </aside>
      </div>
    </>
  );
}

/* ================================================================= SETUP */
export function Setup() {
  const [done, setDone] = useState<string[]>(["Server provisioned", "Game installed"]);
  const toggle = (l: string) => setDone((d) => (d.includes(l) ? d.filter((x) => x !== l) : [...d, l]));

  const tasks = [
    { label: "Server provisioned", detail: "Completed automatically." },
    { label: "Game installed", detail: "Minecraft 1.21, Paper." },
    { label: "Name your server", detail: "Shown to players in the list." },
    { label: "Choose a connect address", detail: "You can change this later.", optional: true },
    { label: "Invite players", detail: "Share the address or add a whitelist.", optional: true },
  ].map((t) => ({
    ...t,
    done: done.includes(t.label),
    action: done.includes(t.label) ? undefined : (
      <Button size="sm" variant="secondary" onClick={() => toggle(t.label)}>Do it</Button>
    ),
  }));

  return (
    <>
      <PageHeader
        eyebrow="Patterns"
        title="Post-payment setup"
        description="Stage two: a server-side record, resumable on any device, skippable with safe defaults. Skipped items do not vanish — they persist as standing tasks on the dashboard."
      />
      <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_320px]">
        <SetupChecklist title="Finish setting up survival-smp" tasks={tasks} />
        <Container className="flex flex-col gap-3 self-start px-5 py-5">
          <h3 className="text-h4 text-ink">Why nothing here blocks</h3>
          <p className="text-body-sm text-ink-secondary">
            Every task maps to an API that changes a live resource, so none of it needed to be asked
            before payment. The customer can close the tab and finish on a phone.
          </p>
          <Button variant="ghost" size="sm">Skip for now</Button>
        </Container>
      </div>
    </>
  );
}

/* ================================================================ DETAIL */
export function Detail() {
  const [auto, setAuto] = useState(true);
  return (
    <>
      <PageHeader
        eyebrow="Patterns"
        title="atlas-web"
        status="running"
        description="Identity, then three primary actions, then health, then everything else behind tabs — with destructive controls in their own section."
        meta={<><MetaItem label="Plan" value="Pro · 3 vCPU · 8 GB" /><MetaItem label="Region" value="Singapore" /><MetaItem label="Node" value="sgp-02" mono /></>}
        actions={<><Button variant="secondary" icon="console">Console</Button><Button variant="secondary" icon="restart">Restart</Button><Button variant="primary" icon="play">Start</Button></>}
      />

      <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_320px]">
        <div className="min-w-0">
          <SectionRule label="Health" />
          <div className="grid grid-cols-2 gap-px overflow-hidden rounded-lg border border-hairline bg-hairline lg:grid-cols-4">
            <div className="bg-surface"><MetricTile label="Processor" value={34} unit="%" chart={<Sparkline points={CPU_SERIES} />} /></div>
            <div className="bg-surface"><MetricTile label="Memory" value="4.1" unit="/ 8 GB" /></div>
            <div className="bg-surface"><MetricTile label="Disk" value={42} unit="/ 100 GB" /></div>
            <div className="bg-surface"><MetricTile label="Uptime" value="1d 18h" /></div>
          </div>
          <Container className="mt-3 grid gap-5 px-5 py-4 sm:grid-cols-3">
            <ResourceMeter label="Memory" used={4.1} total={8} unit="GB" format={(n) => n.toFixed(1)} />
            <ResourceMeter label="Disk" used={42} total={100} unit="GB" />
            <ResourceMeter label="Bandwidth" used={3.8} total={4} unit="TB" format={(n) => n.toFixed(1)} />
          </Container>

          <SectionRule label="Attached" />
          <TopologyDiagram
            center="atlas-web"
            attached={[
              { label: "archive-vol", kind: "250 GB block storage", live: true },
              { label: "example.nx", kind: "domain · A record" },
              { label: "sgp-02", kind: "node · 12 ms" },
            ]}
          />
          <p className="mt-2 text-caption text-ink-muted">
            What a resource is attached to, drawn. A list of tabs cannot show a relationship.
          </p>
        </div>

        <aside className="flex flex-col gap-3">
          <Container className="px-5 py-4">
            <p className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">Access</p>
            <div className="mt-3 flex flex-col gap-3">
              <DataPlate label="Public address" value="198.51.100.24" />
              <DataPlate label="Shell" value="ssh root@198.51.100.24" />
            </div>
          </Container>
          <Container className="flex flex-col gap-3.5 px-5 py-4">
            <p className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">Settings</p>
            <Toggle checked={auto} onChange={setAuto} label="Auto-renew" description="Renews 1 October for $22.99." />
            <Toggle checked label="Daily backups" description="Seven restore points kept." />
          </Container>
          <div className="rounded-lg border border-danger-text/30 bg-surface px-5 py-4">
            <p className="font-display text-h4 text-ink">Destroy this server</p>
            <p className="mt-1 text-caption text-ink-secondary">
              Removes the disk, all snapshots and all backups. The address returns to the pool.
            </p>
            <Button variant="danger" size="sm" icon="trash" className="mt-3">Destroy</Button>
          </div>
        </aside>
      </div>
    </>
  );
}

/* ============================================================= INVENTORY */
const ROWS = [
  { n: "atlas-web",    k: "VPS",     s: "running" as const,      a: "198.51.100.24",         r: "Singapore", p: "Pro · 3 vCPU" },
  { n: "survival-smp", k: "Game",    s: "running" as const,      a: "play.example.nx:25565", r: "Singapore", p: "Minecraft · 8 GB" },
  { n: "kestrel-api",  k: "VPS",     s: "provisioning" as const, a: "assigning address",     r: "Frankfurt", p: "Standard · 2 vCPU" },
  { n: "studio-site",  k: "Hosting", s: "running" as const,      a: "studio.example.nx",     r: "Singapore", p: "Business" },
  { n: "archive-vol",  k: "Volume",  s: "stopped" as const,      a: "vol_8f2a1c",            r: "Singapore", p: "250 GB block" },
  { n: "legacy-mail",  k: "VPS",     s: "suspended" as const,    a: "198.51.100.71",         r: "Singapore", p: "Starter · 1 vCPU" },
];

export function Inventory() {
  return (
    <>
      <PageHeader
        eyebrow="Patterns"
        title="Resource inventory"
        description="One surface for everything the customer owns, filtered by kind. This replaces five sidebar rows over two backends and gives the four orphaned resource types a home."
        actions={<Button variant="brand" icon="deploy">Deploy</Button>}
      />
      <div className="flex flex-col gap-1.5">
        {ROWS.map((r) => (
          <ObjectSurface key={r.n} status={r.s} interactive className="px-4 py-3">
            <div className="flex flex-wrap items-center gap-x-5 gap-y-1.5 pl-2.5">
              <div className="min-w-44 flex-1">
                <div className="flex items-center gap-2.5">
                  <span className="font-display text-h4 text-ink">{r.n}</span>
                  <Badge size="sm">{r.k}</Badge>
                </div>
                <p className="mt-0.5 font-mono text-caption text-ink-muted">{r.a}</p>
              </div>
              <span className="hidden text-caption text-ink-secondary sm:block">{r.p}</span>
              <span className="hidden text-caption text-ink-muted md:block">{r.r}</span>
              <StatusIndicator status={r.s} size="sm" />
              <Button size="sm" variant="secondary">Manage</Button>
            </div>
          </ObjectSurface>
        ))}
      </div>
    </>
  );
}

/* ============================================================== TOPOLOGY */
export function TopologyView() {
  const [region, setRegion] = useState("sgp");
  return (
    <>
      <PageHeader
        eyebrow="Patterns"
        title="Topology"
        description="The Nxeon infrastructure visual language. Regions, networking and relationships are drawn as diagrams — never flags, stock maps or 3D server art."
      />

      <SectionRule label="Region selector" />
      <p className="mb-3 max-w-[68ch] text-body-sm text-ink-secondary">
        A region is a node on a network, not an option in a list. Selecting one lights it and traces
        the paths that reach it, so latency and peering are visible rather than described.
      </p>
      <RegionMap value={region} onChange={setRegion} />

      <SectionRule label="Resource relationships" />
      <TopologyDiagram
        center="atlas-web"
        attached={[
          { label: "archive-vol", kind: "250 GB block storage", live: true },
          { label: "example.nx", kind: "domain · A record" },
          { label: "sgp-02", kind: "node · 12 ms" },
        ]}
      />

      <SectionRule label="The rules" />
      <ul className="flex max-w-[68ch] list-disc flex-col gap-1.5 pl-5 text-body-sm text-ink-secondary">
        <li>Geometry is abstract and deliberate. It is never a literal world map.</li>
        <li>Every stroke is a token colour, so a theme change reaches the diagrams.</li>
        <li>Motion means traffic. A static path is an idle path.</li>
        <li>Nothing is filler — each drawing carries state the customer needs.</li>
      </ul>
    </>
  );
}

toolUseResult.content:
"use client";

/* Showcase — patterns: the composed Nxeon signatures. */

import { useEffect, useState } from "react";
import {
  PageHeader, SectionRule, Container, ObjectSurface, DataPlate,
  StatusIndicator, MetaItem, Badge,
} from "@/components/system/primitives";
import { Button, Radio, Toggle } from "@/components/system/controls";
import { Stepper } from "@/components/system/navigation";
import { DeploymentLadder, SetupChecklist, type Rung } from "@/components/system/states";
import { ResourceMeter, MetricTile, Sparkline } from "@/components/system/data";
import { Alert } from "@/components/system/overlays";
import { RegionMap, TopologyDiagram, NodeField, NXEON_REGIONS } from "@/components/system/Topology";
import { Assembling } from "@/components/system/illustrations";
import { CPU_SERIES } from "@/lib/mock";

/* ================================================================ LADDER */
const LADDER: string[] = [
  "Allocating your server",
  "Configuring the network",
  "Starting your server",
  "Booting the operating system",
  "Waiting for network access",
];

export function Ladder() {
  const [at, setAt] = useState(1);
  const [secs, setSecs] = useState(38);
  useEffect(() => {
    const t = window.setInterval(() => setSecs((s) => s + 1), 1000);
    return () => window.clearInterval(t);
  }, []);

  const rungs: Rung[] = LADDER.map((label, i) => ({
    label, state: i < at ? "done" : i === at ? "active" : "pending",
  }));
  const mm = String(Math.floor(secs / 60)).padStart(2, "0");
  const ss = String(secs % 60).padStart(2, "0");

  return (
    <>
      <PageHeader
        eyebrow="Patterns"
        title="Deployment ladder"
        description="The signature post-payment moment, and the pattern with the strictest rule in the system: it may never claim more than the backend knows."
      />

      {/* The brand moment: gradient, grid and node field, used once */}
      <div className="nx-container-surface relative mb-5 overflow-hidden">
        <span className="nx-grad-rule absolute inset-x-0 top-0" aria-hidden="true" />
        <div className="nx-grid-field nx-grid-mask pointer-events-none absolute inset-0" aria-hidden="true" />
        <NodeField />
        <div className="relative flex flex-wrap items-center gap-6 px-6 py-7">
          <Assembling size={150} />
          <div className="min-w-0 flex-1">
            <p className="font-display text-label uppercase tracking-[0.13em] text-ink-muted">Deploying</p>
            <h2 className="mt-1 text-h1"><span className="nx-grad-text">survival-smp</span></h2>
            <p className="mt-1.5 max-w-[52ch] text-body-sm text-ink-secondary">
              Minecraft · Pro · Singapore. You can close this tab — we will email you when it is ready.
            </p>
          </div>
        </div>
      </div>

      <Alert tone="signal" title="Why there is no percentage here">
        The provisioning worker writes exactly six coarse step labels and no progress figure, no
        estimate and no status endpoint. So the component takes named stages and has no percentage
        prop to pass. It shows elapsed time and a typical range instead of a countdown it cannot honour.
      </Alert>

      <div className="mt-4 grid gap-4 lg:grid-cols-[minmax(0,1fr)_300px]">
        <DeploymentLadder
          rungs={rungs}
          elapsedLabel={`${mm}:${ss} elapsed`}
          typicalLabel="usually 1–3 min"
          overdue={at >= LADDER.length - 1}
          onCheckStatus={() => {}}
        />
        <Container className="flex flex-col gap-3 self-start px-5 py-5">
          <h3 className="text-h4 text-ink">Demonstration</h3>
          <p className="text-caption text-ink-muted">Step through the real backend states. Nothing is interpolated.</p>
          <div className="flex gap-2">
            <Button size="sm" variant="secondary" onClick={() => setAt((n) => Math.max(0, n - 1))}>Back</Button>
            <Button size="sm" variant="primary" onClick={() => setAt((n) => Math.min(LADDER.length, n + 1))}>Advance</Button>
          </div>
          <p className="border-t border-hairline pt-3 text-caption text-ink-secondary">
            Past the expected window the message changes and offers an action, rather than spinning
            silently. Advance to the last rung to see it.
          </p>
        </Container>
      </div>

      <SectionRule label="First value arrives as soon as it exists" />
      <div className="grid gap-3 sm:grid-cols-2">
        <DataPlate label="Connect address" value="play.example.nx:25565" />
        <DataPlate label="Console password" value="w8Rq-4Tz9-Lm2P" masked />
      </div>
    </>
  );
}

/* ============================================================== CHECKOUT */
const TIERS = [
  { id: "starter", name: "Starter", price: 8.88,  cpu: "1 vCPU", ram: "2 GB", disk: "25 GB",  players: "Up to 10 players" },
  { id: "pro",     name: "Pro",     price: 20.99, cpu: "3 vCPU", ram: "8 GB", disk: "80 GB",  players: "Up to 40, modded" },
  { id: "max",     name: "Max",     price: 32.99, cpu: "4 vCPU", ram: "16 GB", disk: "120 GB", players: "Large modpacks" },
];

export function Checkout() {
  const [step, setStep] = useState(0);
  const [tier, setTier] = useState("pro");
  const [region, setRegion] = useState("sgp");
  const [term, setTerm] = useState<"monthly" | "annual">("annual");

  const plan = TIERS.find((t) => t.id === tier)!;
  const rate = term === "annual" ? plan.price * 0.8 : plan.price;
  const dueToday = term === "annual" ? rate * 12 : rate;
  const regionLabel = NXEON_REGIONS.find((r) => r.id === region)?.label ?? "";

  return (
    <>
      <PageHeader
        eyebrow="Patterns"
        title="Two-stage checkout"
        description="Stage one asks only what sets the price. For game servers every remaining field has a live-change API, so the whole configuration step moves after payment — four steps become two."
      />

      <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_320px] lg:items-start">
        {/* ---------------------------------------------------- main column */}
        <div className="min-w-0">
          <div className="nx-container-surface relative overflow-hidden">
            <span className="nx-grad-rule absolute inset-x-0 top-0" aria-hidden="true" />
            <div className="border-b border-hairline px-5 py-4">
              <Stepper steps={[{ id: "plan", label: "Plan and region" }, { id: "pay", label: "Payment" }]} current={step} />
            </div>

            {step === 0 ? (
              <div className="flex flex-col gap-7 px-5 py-6">
                <div>
                  <h3 className="text-h2 text-ink">Choose your plan</h3>
                  <p className="mt-1.5 max-w-[58ch] text-body-sm text-ink-secondary">
                    These are the only choices that change the price. Server name, connect address,
                    version and every setting come after payment, and change any time.
                  </p>
                </div>

                {/* Plan cards — objects, so they carry the notch and read as things */}
                <div className="grid gap-3 sm:grid-cols-3">
                  {TIERS.map((t) => {
                    const on = t.id === tier;
                    return (
                      <button
                        key={t.id}
                        type="button"
                        onClick={() => setTier(t.id)}
                        aria-pressed={on}
                        className={`nx-object nx-object-interactive ${on ? "nx-object-selected" : ""} px-4 pb-4 pt-3.5 text-left`}
                      >
                        <div className="flex items-start justify-between gap-2">
                          <span className="font-display text-h3 text-ink">{t.name}</span>
                          {t.id === "pro" && (
                            <span className="nx-grad-brand rounded-sm px-1.5 py-0.5 font-display text-[0.625rem] font-semibold uppercase tracking-[0.09em] text-white">
                              Popular
                            </span>
                          )}
                        </div>

                        <div className="mt-3 flex items-baseline gap-1">
                          <span className="font-display text-metric tabular-nums text-ink">
                            ${(term === "annual" ? t.price * 0.8 : t.price).toFixed(2)}
                          </span>
                          <span className="text-caption text-ink-muted">/mo</span>
                        </div>

                        <dl className="mt-3.5 flex flex-col gap-1 border-t border-hairline pt-3">
                          {[["CPU", t.cpu], ["Memory", t.ram], ["NVMe", t.disk]].map(([k, v]) => (
                            <div key={k} className="flex items-baseline justify-between gap-2">
                              <dt className="font-display text-[0.6875rem] uppercase tracking-[0.1em] text-ink-muted">{k}</dt>
                              <dd className="font-mono text-caption text-ink-secondary">{v}</dd>
                            </div>
                          ))}
                        </dl>
                        <p className="mt-3 text-caption text-ink-muted">{t.players}</p>
                      </button>
                    );
                  })}
                </div>

                {/* Region, as a network rather than a dropdown */}
                <div>
                  <div className="nx-rule mb-3">
                    <span className="nx-rule-label">Region</span>
                  </div>
                  <RegionMap value={region} onChange={setRegion} height={240} />
                  <p className="mt-2 text-caption text-ink-muted">
                    Latency is measured from your location. Los Angeles is at capacity today.
                  </p>
                </div>

                {/* Term */}
                <div>
                  <div className="nx-rule mb-3"><span className="nx-rule-label">Billing term</span></div>
                  <div className="grid gap-2 sm:grid-cols-2">
                    <label className={`nx-object nx-object-interactive ${term === "monthly" ? "nx-object-selected" : ""} cursor-pointer px-4 py-3`}>
                      <Radio name="term" checked={term === "monthly"} onChange={() => setTerm("monthly")}
                        label="Monthly" description={`$${plan.price.toFixed(2)} per month · cancel any time`} />
                    </label>
                    <label className={`nx-object nx-object-interactive ${term === "annual" ? "nx-object-selected" : ""} cursor-pointer px-4 py-3`}>
                      <Radio name="term" checked={term === "annual"} onChange={() => setTerm("annual")}
                        label="Annual · save 20%"
                        description={`$${(plan.price * 0.8).toFixed(2)}/mo for year one, then $${plan.price.toFixed(2)}/mo`} />
                    </label>
                  </div>
                </div>
              </div>
            ) : (
              <div className="flex flex-col gap-6 px-5 py-6">
                <div>
                  <h3 className="text-h2 text-ink">Payment</h3>
                  <p className="mt-1.5 text-body-sm text-ink-secondary">Secure, and the last step before your server is built.</p>
                </div>
                <div className="flex flex-col gap-4">
                  <DataPlate label="Card number" value="4242 4242 4242 4242" copyable={false} />
                  <div className="grid grid-cols-2 gap-4">
                    <DataPlate label="Expiry" value="04 / 28" copyable={false} />
                    <DataPlate label="Security code" value="•••" copyable={false} />
                  </div>
                </div>
                <Alert tone="neutral" title="No add-ons on this step">
                  Complements are offered before or after payment, never here. Trust is most fragile
                  at the moment of paying.
                </Alert>
              </div>
            )}
          </div>
        </div>

        {/* ------------------------------------------------------ order rail */}
        <aside className="lg:sticky lg:top-20">
          <div className="nx-container-surface relative overflow-hidden">
            <div className="nx-grid-field nx-grid-mask pointer-events-none absolute inset-0" aria-hidden="true" />
            <div className="relative px-5 py-4">
              <p className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">Your order</p>
              <p className="mt-2 font-display text-h3 text-ink">Minecraft · {plan.name}</p>
              <p className="mt-0.5 font-mono text-caption text-ink-muted">{plan.cpu} · {plan.ram} · {plan.disk}</p>

              <dl className="mt-4 flex flex-col gap-2 border-t border-hairline pt-3.5 text-body-sm">
                <div className="flex justify-between gap-3"><dt className="text-ink-secondary">Region</dt><dd className="text-ink">{regionLabel}</dd></div>
                <div className="flex justify-between gap-3"><dt className="text-ink-secondary">Term</dt><dd className="text-ink">{term === "annual" ? "Annual" : "Monthly"}</dd></div>
                <div className="flex justify-between gap-3"><dt className="text-ink-secondary">Tax</dt><dd className="text-ink">Included</dd></div>
              </dl>

              <div className="mt-3.5 border-t border-hairline pt-3.5">
                <div className="flex items-baseline justify-between gap-3">
                  <span className="font-display text-h4 text-ink">Due today</span>
                  <span className="font-display text-metric tabular-nums text-ink">${dueToday.toFixed(2)}</span>
                </div>
                <p className="mt-1 text-caption text-ink-muted">
                  Then ${term === "annual" ? plan.price.toFixed(2) : rate.toFixed(2)} per month
                  {term === "annual" ? ", billed yearly from next year" : ""}.
                </p>
              </div>

              <div className="mt-4">
                {step === 0 ? (
                  <Button variant="brand" size="lg" block iconRight="arrowRight" onClick={() => setStep(1)}>
                    Continue to payment
                  </Button>
                ) : (
                  <Button variant="brand" size="lg" block icon="deploy">
                    Pay ${dueToday.toFixed(2)} and deploy
                  </Button>
                )}
                {step === 1 && (
                  <Button variant="ghost" size="sm" block className="mt-1.5" onClick={() => setStep(0)}>
                    Back to plan
                  </Button>
                )}
              </div>

              <ul className="mt-4 flex flex-col gap-1.5 border-t border-hairline pt-3.5 text-caption text-ink-muted">
                <li>Both prices shown before you pay.</li>
                <li>Change plan any time, up or down.</li>
                <li>Everything else is set after payment.</li>
              </ul>
            </div>
          </div>
        </aside>
      </div>
    </>
  );
}

/* ================================================================= SETUP */
export function Setup() {
  const [done, setDone] = useState<string[]>(["Server provisioned", "Game installed"]);
  const toggle = (l: string) => setDone((d) => (d.includes(l) ? d.filter((x) => x !== l) : [...d, l]));

  const tasks = [
    { label: "Server provisioned", detail: "Completed automatically." },
    { label: "Game installed", detail: "Minecraft 1.21, Paper." },
    { label: "Name your server", detail: "Shown to players in the list." },
    { label: "Choose a connect address", detail: "You can change this later.", optional: true },
    { label: "Invite players", detail: "Share the address or add a whitelist.", optional: true },
  ].map((t) => ({
    ...t,
    done: done.includes(t.label),
    action: done.includes(t.label) ? undefined : (
      <Button size="sm" variant="secondary" onClick={() => toggle(t.label)}>Do it</Button>
    ),
  }));

  return (
    <>
      <PageHeader
        eyebrow="Patterns"
        title="Post-payment setup"
        description="Stage two: a server-side record, resumable on any device, skippable with safe defaults. Skipped items do not vanish — they persist as standing tasks on the dashboard."
      />
      <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_320px]">
        <SetupChecklist title="Finish setting up survival-smp" tasks={tasks} />
        <Container className="flex flex-col gap-3 self-start px-5 py-5">
          <h3 className="text-h4 text-ink">Why nothing here blocks</h3>
          <p className="text-body-sm text-ink-secondary">
            Every task maps to an API that changes a live resource, so none of it needed to be asked
            before payment. The customer can close the tab and finish on a phone.
          </p>
          <Button variant="ghost" size="sm">Skip for now</Button>
        </Container>
      </div>
    </>
  );
}

/* ================================================================ DETAIL */
export function Detail() {
  const [auto, setAuto] = useState(true);
  return (
    <>
      <PageHeader
        eyebrow="Patterns"
        title="atlas-web"
        status="running"
        description="Identity, then three primary actions, then health, then everything else behind tabs — with destructive controls in their own section."
        meta={<><MetaItem label="Plan" value="Pro · 3 vCPU · 8 GB" /><MetaItem label="Region" value="Singapore" /><MetaItem label="Node" value="sgp-02" mono /></>}
        actions={<><Button variant="secondary" icon="console">Console</Button><Button variant="secondary" icon="restart">Restart</Button><Button variant="primary" icon="play">Start</Button></>}
      />

      <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_320px]">
        <div className="min-w-0">
          <SectionRule label="Health" />
          <div className="grid grid-cols-2 gap-px overflow-hidden rounded-lg border border-hairline bg-hairline lg:grid-cols-4">
            <div className="bg-surface"><MetricTile label="Processor" value={34} unit="%" chart={<Sparkline points={CPU_SERIES} />} /></div>
            <div className="bg-surface"><MetricTile label="Memory" value="4.1" unit="/ 8 GB" /></div>
            <div className="bg-surface"><MetricTile label="Disk" value={42} unit="/ 100 GB" /></div>
            <div className="bg-surface"><MetricTile label="Uptime" value="1d 18h" /></div>
          </div>
          <Container className="mt-3 grid gap-5 px-5 py-4 sm:grid-cols-3">
            <ResourceMeter label="Memory" used={4.1} total={8} unit="GB" format={(n) => n.toFixed(1)} />
            <ResourceMeter label="Disk" used={42} total={100} unit="GB" />
            <ResourceMeter label="Bandwidth" used={3.8} total={4} unit="TB" format={(n) => n.toFixed(1)} />
          </Container>

          <SectionRule label="Attached" />
          <TopologyDiagram
            center="atlas-web"
            attached={[
              { label: "archive-vol", kind: "250 GB block storage", live: true },
              { label: "example.nx", kind: "domain · A record" },
              { label: "sgp-02", kind: "node · 12 ms" },
            ]}
          />
          <p className="mt-2 text-caption text-ink-muted">
            What a resource is attached to, drawn. A list of tabs cannot show a relationship.
          </p>
        </div>

        <aside className="flex flex-col gap-3">
          <Container className="px-5 py-4">
            <p className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">Access</p>
            <div className="mt-3 flex flex-col gap-3">
              <DataPlate label="Public address" value="198.51.100.24" />
              <DataPlate label="Shell" value="ssh root@198.51.100.24" />
            </div>
          </Container>
          <Container className="flex flex-col gap-3.5 px-5 py-4">
            <p className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">Settings</p>
            <Toggle checked={auto} onChange={setAuto} label="Auto-renew" description="Renews 1 October for $22.99." />
            <Toggle checked label="Daily backups" description="Seven restore points kept." />
          </Container>
          <div className="rounded-lg border border-danger-text/30 bg-surface px-5 py-4">
            <p className="font-display text-h4 text-ink">Destroy this server</p>
            <p className="mt-1 text-caption text-ink-secondary">
              Removes the disk, all snapshots and all backups. The address returns to the pool.
            </p>
            <Button variant="danger" size="sm" icon="trash" className="mt-3">Destroy</Button>
          </div>
        </aside>
      </div>
    </>
  );
}

/* ============================================================= INVENTORY */
const ROWS = [
  { n: "atlas-web",    k: "VPS",     s: "running" as const,      a: "198.51.100.24",         r: "Singapore", p: "Pro · 3 vCPU" },
  { n: "survival-smp", k: "Game",    s: "running" as const,      a: "play.example.nx:25565", r: "Singapore", p: "Minecraft · 8 GB" },
  { n: "kestrel-api",  k: "VPS",     s: "provisioning" as const, a: "assigning address",     r: "Frankfurt", p: "Standard · 2 vCPU" },
