69	        aria-label="Nxeon regions"
70	      >
71	        <defs>
72	          <linearGradient id={`${uid}-link`} x1="0" y1="0" x2="1" y2="0">
73	            <stop offset="0%" stopColor="var(--color-brand-a)" stopOpacity="0.55" />
74	            <stop offset="55%" stopColor="var(--color-brand-b)" stopOpacity="0.5" />
