/* Build-time only. Reads the public-domain Natural Earth land topology and
   rasterises it to a 1-degree land/sea bitset that the globe samples at
   runtime. Output is a base64 bitset — no runtime dependency, no fetch. */
import fs from "node:fs";

const topo = JSON.parse(fs.readFileSync("/opt/nxeon/public/countries-110m.json", "utf8"));
const { scale: S, translate: T } = topo.transform;

// Decode delta-encoded quantised arcs into lon/lat rings.
const arcs = topo.arcs.map((arc) => {
  let x = 0, y = 0;
  return arc.map(([dx, dy]) => {
    x += dx; y += dy;
    return [x * S[0] + T[0], y * S[1] + T[1]];
  });
});

const ring = (idxs) => {
  const out = [];
  for (const i of idxs) {
    const a = i < 0 ? arcs[~i].slice().reverse() : arcs[i];
    for (const p of (out.length ? a.slice(1) : a)) out.push(p);
  }
  return out;
};

const geom = topo.objects.land ?? topo.objects.countries;
const polys = [];
const collect = (g) => {
  if (g.type === "Polygon") polys.push(g.arcs.map(ring));
  else if (g.type === "MultiPolygon") g.arcs.forEach((p) => polys.push(p.map(ring)));
  else if (g.type === "GeometryCollection") g.geometries.forEach(collect);
};
collect(geom);

// Even-odd ray casting across every ring of a polygon handles holes for free.
const inPoly = (lon, lat, rings) => {
  let inside = false;
  for (const r of rings) {
    for (let i = 0, j = r.length - 1; i < r.length; j = i++) {
      const [xi, yi] = r[i], [xj, yj] = r[j];
      if ((yi > lat) !== (yj > lat) && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside;
    }
  }
  return inside;
};

const LON = 360, LAT = 180;               // one degree
const bits = new Uint8Array(Math.ceil((LON * LAT) / 8));
let land = 0;
for (let iy = 0; iy < LAT; iy++) {
  const lat = 90 - iy - 0.5;
  for (let ix = 0; ix < LON; ix++) {
    const lon = ix - 180 + 0.5;
    let hit = false;
    for (const p of polys) if (inPoly(lon, lat, p)) { hit = true; break; }
    if (hit) { const n = iy * LON + ix; bits[n >> 3] |= 1 << (n & 7); land++; }
  }
}

fs.writeFileSync(
  "lib/land.ts",
  `/* GENERATED by scripts/build-land.mjs — do not edit.\n` +
  `   1-degree land bitset from public-domain Natural Earth data (110m).\n` +
  `   ${land} land cells of ${LON * LAT}. Decoded once at module load. */\n` +
  `export const LAND_W = ${LON};\nexport const LAND_H = ${LAT};\n` +
  `const B64 = "${Buffer.from(bits).toString("base64")}";\n` +
  `const bin = typeof atob === "function" ? atob(B64) : Buffer.from(B64, "base64").toString("binary");\n` +
  `const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));\n` +
  `export function isLand(lonIdx: number, latIdx: number): boolean {\n` +
  `  const n = latIdx * LAND_W + lonIdx;\n` +
  `  return (bytes[n >> 3] & (1 << (n & 7))) !== 0;\n}\n`
);
console.log(`land cells: ${land} / ${LON * LAT}  (${((land / (LON * LAT)) * 100).toFixed(1)}%)`);
EOF
