1	"use client";
2	
3	/* ============================================================================
4	   THE GLOBE — the region selector's hero graphic
5	   A rotating dot-matrix Earth drawn on canvas: ~20,000 land cells from
6	   public-domain Natural Earth data, a lat/lon network grid, great-circle
7	   routes between Nxeon regions with travelling packets, a neon rim and a
8	   reflected plinth.
9	
10	   No 3D library. Land cells are projected once into unit vectors at mount and
11	   only rotated per frame, so the whole thing is a few milliseconds of maths.
12	   Honours prefers-reduced-motion by holding still rather than spinning.
13	   ========================================================================= */
14	
15	import { useEffect, useRef } from "react";
16	import { LAND_W, LAND_H, isLand } from "@/lib/land";
17	
18	export interface GlobeRegion {
19	  id: string;
20	  label: string;
21	  lat: number;
22	  lon: number;
23	  latencyMs: number;
24	  available?: boolean;
25	}
26	
27	export const GLOBE_REGIONS: GlobeRegion[] = [
28	  { id: "sgp", label: "Singapore",   lat: 1.35,  lon: 103.8, latencyMs: 12 },
29	  { id: "jpn", label: "Japan",       lat: 35.7,  lon: 139.7, latencyMs: 32 },
30	  { id: "aus", label: "Australia",   lat: -33.9, lon: 151.2, latencyMs: 42 },
31	  { id: "eur", label: "Europe",      lat: 50.1,  lon: 8.7,   latencyMs: 68 },
32	  { id: "usw", label: "US West",     lat: 37.4,  lon: -122.1, latencyMs: 48 },
33	  { id: "use", label: "US East",     lat: 40.7,  lon: -74.0, latencyMs: 52 },
34	  { id: "sam", label: "South America", lat: -23.5, lon: -46.6, latencyMs: 85 },
35	  { id: "mea", label: "Middle East", lat: 25.2,  lon: 55.3,  latencyMs: 78, available: false },
36	];
37	
38	const ROUTES: [string, string][] = [
39	  ["sgp", "jpn"], ["sgp", "aus"], ["sgp", "eur"], ["eur", "use"],
40	  ["use", "usw"], ["use", "sam"], ["eur", "mea"], ["sgp", "usw"],
41	];
42	
43	const toVec = (latDeg: number, lonDeg: number): [number, number, number] => {
44	  const la = (latDeg * Math.PI) / 180, lo = (lonDeg * Math.PI) / 180;
45	  return [Math.cos(la) * Math.sin(lo), Math.sin(la), Math.cos(la) * Math.cos(lo)];
46	};
47	
48	/** Reads a CSS custom property so the globe stays on the token system. */
49	function tokenRgb(el: HTMLElement, name: string): [number, number, number] {
50	  const v = getComputedStyle(el).getPropertyValue(name).trim();
51	  const m = v.match(/^#([0-9a-f]{6})$/i);
52	  if (m) {
53	    const n = parseInt(m[1], 16);
54	    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
55	  }
56	  return [110, 140, 255];
57	}
58	
59	export function Globe({
60	  regions = GLOBE_REGIONS,
61	  selected,
62	  onSelect,
63	  height = 460,
64	}: {
65	  regions?: GlobeRegion[];
66	  selected: string;
67	  onSelect?: (id: string) => void;
68	  height?: number;
69	}) {
70	  const canvasRef = useRef<HTMLCanvasElement>(null);
71	  const wrapRef = useRef<HTMLDivElement>(null);
72	  const selRef = useRef(selected);
73	  selRef.current = selected;
74	  /* Lets the selection repaint a paused globe (reduced motion, off-screen). */
75	  const drawRef = useRef<(() => void) | null>(null);
76	
77	  useEffect(() => {
78	    const canvas = canvasRef.current, wrap = wrapRef.current;
79	    if (!canvas || !wrap) return;
80	    const ctx = canvas.getContext("2d");
81	    if (!ctx) return;
82	
83	    /* ---- land cells -> unit vectors, once ---- */
84	    const pts: number[] = [];
85	    for (let iy = 0; iy < LAND_H; iy++) {
86	      // Thin the sampling toward the poles, where 1 degree of longitude is tiny.
87	      const lat = 90 - iy - 0.5;
88	      const step = Math.abs(lat) > 72 ? 3 : Math.abs(lat) > 55 ? 2 : 1;
89	      for (let ix = 0; ix < LAND_W; ix += step) {
90	        if (!isLand(ix, iy)) continue;
91	        const [x, y, z] = toVec(lat, ix - 180 + 0.5);
92	        pts.push(x, y, z);
93	      }
94	    }
95	    const land = new Float32Array(pts);
96	    const N = land.length / 3;
97	
98	    const A = tokenRgb(wrap, "--color-brand-a");
99	    const B = tokenRgb(wrap, "--color-brand-b");
100	    const C = tokenRgb(wrap, "--color-brand-c");
101	    const NEON = tokenRgb(wrap, "--color-neon-cyan");
102	    const RAISED = tokenRgb(wrap, "--color-raised");
103	    const PLATE = tokenRgb(wrap, "--color-plate");
104	    const MUTED = tokenRgb(wrap, "--color-ink-muted");
105	
106	    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
107	
108	    let raf = 0, t = 0, dpr = 1, W = 0, H = 0, R = 0, cx = 0, cy = 0;
109	
110	    const resize = () => {
111	      dpr = Math.min(window.devicePixelRatio || 1, 2);
112	      W = wrap.clientWidth; H = height;
113	      canvas.width = W * dpr; canvas.height = H * dpr;
114	      canvas.style.width = `${W}px`; canvas.style.height = `${H}px`;
115	      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
116	      R = Math.min(W, H) * 0.36;
117	      cx = W / 2; cy = H * 0.46;
118	      drawRef.current?.(); // a paused globe must not stay blank after resize
119	    };
120	
121	    /* Blend the brand ramp left-to-right across the sphere. */
122	    const ramp = (u: number): [number, number, number] => {
123	      if (u < 0.5) {
124	        const k = u * 2;
125	        return [A[0] + (B[0] - A[0]) * k, A[1] + (B[1] - A[1]) * k, A[2] + (B[2] - A[2]) * k];
126	      }
127	      const k = (u - 0.5) * 2;
128	      return [B[0] + (C[0] - B[0]) * k, B[1] + (C[1] - B[1]) * k, B[2] + (C[2] - B[2]) * k];
129	    };
130	
131	    const draw = () => {
132	      ctx.clearRect(0, 0, W, H);
133	      const rot = reduce ? 0.6 : t * 0.00022;
134	      const cos = Math.cos(rot), sin = Math.sin(rot);
135	
136	      /* ---- atmosphere ---- */
137	      const atmo = ctx.createRadialGradient(cx, cy, R * 0.72, cx, cy, R * 1.5);
138	      atmo.addColorStop(0, `rgba(${B[0]},${B[1]},${B[2]},0.22)`);
139	      atmo.addColorStop(0.55, `rgba(${C[0]},${C[1]},${C[2]},0.10)`);
140	      atmo.addColorStop(1, "rgba(0,0,0,0)");
141	      ctx.fillStyle = atmo;
142	      ctx.beginPath(); ctx.arc(cx, cy, R * 1.5, 0, Math.PI * 2); ctx.fill();
143	
144	      /* ---- sphere body: the raised and plate surface tokens ---- */
145	      const body = ctx.createRadialGradient(cx - R * 0.3, cy - R * 0.35, R * 0.1, cx, cy, R);
146	      body.addColorStop(0, `rgba(${RAISED.join(",")},0.95)`);
147	      body.addColorStop(1, `rgba(${PLATE.join(",")},0.98)`);
148	      ctx.fillStyle = body;
149	      ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.fill();
150	
151	      /* ---- network grid: parallels and meridians ---- */
152	      ctx.lineWidth = 0.6;
153	      for (let latD = -60; latD <= 60; latD += 30) {
154	        ctx.beginPath();
155	        let started = false;
156	        for (let lonD = -180; lonD <= 180; lonD += 3) {
157	          const [x, y, z] = toVec(latD, lonD);
158	          const rx = x * cos + z * sin, rz = -x * sin + z * cos;
159	          if (rz <= 0) { started = false; continue; }
160	          const sx = cx + rx * R, sy = cy - y * R;
161	          if (!started) { ctx.moveTo(sx, sy); started = true; } else ctx.lineTo(sx, sy);
162	        }
163	        ctx.strokeStyle = `rgba(${B[0]},${B[1]},${B[2]},0.16)`;
164	        ctx.stroke();
165	      }
166	      for (let lonD = -180; lonD < 180; lonD += 30) {
167	        ctx.beginPath();
168	        let started = false;
169	        for (let latD = -90; latD <= 90; latD += 3) {
170	          const [x, y, z] = toVec(latD, lonD);
171	          const rx = x * cos + z * sin, rz = -x * sin + z * cos;
172	          if (rz <= 0) { started = false; continue; }
173	          const sx = cx + rx * R, sy = cy - y * R;
174	          if (!started) { ctx.moveTo(sx, sy); started = true; } else ctx.lineTo(sx, sy);
175	        }
176	        ctx.strokeStyle = `rgba(${B[0]},${B[1]},${B[2]},0.13)`;
177	        ctx.stroke();
178	      }
179	
180	      /* ---- land dots ---- */
181	      for (let i = 0; i < N; i++) {
182	        const x = land[i * 3], y = land[i * 3 + 1], z = land[i * 3 + 2];
183	        const rx = x * cos + z * sin, rz = -x * sin + z * cos;
184	        if (rz <= 0.02) continue;
