/* ============================================================================
   NXEON INFORMATION ARCHITECTURE — Phase 3
   The single definition of the portal's navigation. Every route in the
   product resolves through this file: the sidebar renders from it, the
   breadcrumb derives from it, the command palette indexes it, and the
   legacy-route map below proves nothing was stranded by the restructure.

   The model is the approved Phase 1 IA: navigate by OBJECT, not by product
   name. The old sidebar was organised by product while the app was organised
   by database table, which is why a game server's page lived under "Servers"
   and the nav highlight jumped on every click.
   ========================================================================= */

import type { IconName } from "@/components/system/Icon";

export type ResourceKind = "vps" | "game" | "hosting" | "site" | "volume" | "nxcloud" | "freemc";

export interface NavLeaf {
  id: string;
  label: string;
  href: string;
  icon: IconName;
  /** Live count or unread marker. */
  badge?: number;
  /** Indented under its parent — used for owned resource kinds. */
  child?: boolean;
  /** Present in the tree but only shown when the customer owns one. */
  ownedOnly?: boolean;
}

export interface NavSection {
  /** Section heading. Absent for the single Home row. */
  label?: string;
  items: NavLeaf[];
}

/* ---------------------------------------------------------------------------
   The three tiers the brief asks for: what you make, what you own, and the
   account and operations behind them. A customer should never have to work
   out which column an item belongs to.
   ------------------------------------------------------------------------ */
export const NAV: NavSection[] = [
  {
    items: [{ id: "home", label: "Home", href: "/home", icon: "home" }],
  },
  {
    label: "Create",
    items: [
      { id: "deploy", label: "Deploy", href: "/deploy", icon: "deploy" },
      { id: "build", label: "Build with AI", href: "/build", icon: "ai" },
    ],
  },
  {
    label: "Your resources",
    items: [
      { id: "resources", label: "All resources", href: "/resources", icon: "resources" },
      { id: "r-vps",     label: "VPS",            href: "/resources/vps",     icon: "vps",     child: true, ownedOnly: true },
      { id: "r-game",    label: "Game servers",   href: "/resources/game",    icon: "game",    child: true, ownedOnly: true },
      { id: "r-hosting", label: "Shared hosting", href: "/resources/hosting", icon: "hosting", child: true, ownedOnly: true },
      { id: "r-site",    label: "Websites",       href: "/resources/site",    icon: "files",   child: true, ownedOnly: true },
      { id: "r-volume",  label: "Storage",        href: "/resources/volume",  icon: "storage", child: true, ownedOnly: true },
      { id: "r-nxcloud", label: "NxCloud",        href: "/resources/nxcloud", icon: "datacenter", child: true, ownedOnly: true },
      { id: "r-freemc",  label: "Free Minecraft", href: "/resources/freemc",  icon: "game",    child: true, ownedOnly: true },
    ],
  },
  {
    label: "Network & mail",
    items: [
      { id: "domains",    label: "Domains",          href: "/network/domains",    icon: "domains" },
      { id: "ssl",        label: "SSL certificates", href: "/network/ssl",        icon: "ssl" },
      { id: "inbox",      label: "Inbox",            href: "/network/inbox",      icon: "mail" },
      { id: "mailboxes",  label: "Mailboxes",        href: "/network/mailboxes",  icon: "mailbox" },
    ],
  },
  {
    label: "Account & operations",
    items: [
      { id: "billing",   label: "Billing",   href: "/account/billing",   icon: "billing" },
      { id: "team",      label: "Team",      href: "/account/team",      icon: "account" },
      { id: "migration", label: "Migration", href: "/account/migration", icon: "migration" },
      { id: "activity",  label: "Activity",  href: "/account/activity",  icon: "activity" },
      { id: "support",   label: "Support",   href: "/account/support",   icon: "support" },
      { id: "settings",  label: "Settings",  href: "/account/settings",  icon: "settings" },
    ],
  },
];

/** Utility destinations. Deliberately NOT permanent sidebar rows: the 16 tools
    are duplicated verbatim on the marketing site and do not earn nav weight.
    They live in the rail footer and are fully indexed in the command palette. */
export const NAV_FOOTER: NavLeaf[] = [
  { id: "tools",     label: "Free tools", href: "/tools",     icon: "settings" },
  { id: "whatsnew",  label: "What's new", href: "/whats-new", icon: "info" },
];

/* ---------------------------------------------------------------------------
   RESOURCE KINDS
   One detail-page contract per kind, and the URL states the kind, so the nav
   highlight can never disagree with the page you are on.
   ------------------------------------------------------------------------ */
export const KINDS: Record<ResourceKind, { label: string; singular: string; icon: IconName }> = {
  vps:     { label: "VPS",            singular: "VPS",            icon: "vps" },
  game:    { label: "Game servers",   singular: "Game server",    icon: "game" },
  hosting: { label: "Shared hosting", singular: "Hosting plan",   icon: "hosting" },
  site:    { label: "Websites",       singular: "Website",        icon: "files" },
  volume:  { label: "Storage",        singular: "Volume",         icon: "storage" },
  nxcloud: { label: "NxCloud",        singular: "NxCloud",        icon: "datacenter" },
  freemc:  { label: "Free Minecraft", singular: "Free server",    icon: "game" },
};

/* ---------------------------------------------------------------------------
   LEGACY ROUTE MAP
   Every destination in the production portal, and where it now lives. This is
   the guarantee that restructuring the IA stranded nothing: the audit found
   seven orphan routes with no nav entry at all, and all seven get a home here.
   `redirect` entries are wired in next.config.ts so old links keep working.
   ------------------------------------------------------------------------ */
export interface RouteMapping {
  legacy: string;
  now: string;
  note?: string;
}

export const ROUTE_MAP: RouteMapping[] = [
  { legacy: "/dashboard",                    now: "/home" },
  { legacy: "/dashboard/deploy",             now: "/deploy" },
  { legacy: "/dashboard/order",              now: "/deploy",  note: "Dead redirect stub in production; folded into the hub." },
  { legacy: "/dashboard/servers",            now: "/resources/vps" },
  { legacy: "/dashboard/servers/[id]",       now: "/resources/vps/[id]", note: "Game servers now resolve to /resources/game/[id] instead of sharing this route." },
  { legacy: "/dashboard/games",              now: "/resources/game" },
  { legacy: "/dashboard/free-minecraft",     now: "/resources/freemc", note: "Was a duplicate of a tab; now a kind. Old URL redirects for marketing deep links." },
  { legacy: "/dashboard/hosting",            now: "/resources/hosting" },
  { legacy: "/dashboard/hosting/[id]",       now: "/resources/hosting/[id]" },
  { legacy: "/dashboard/sites",              now: "/resources/site" },
  { legacy: "/dashboard/sites/[id]",         now: "/resources/site/[id]" },
  { legacy: "/dashboard/volumes",            now: "/resources/volume" },
  { legacy: "/dashboard/nxcloud",            now: "/resources/nxcloud", note: "ORPHAN in production — no nav entry at all. Now a first-class kind." },
  { legacy: "/dashboard/projects",           now: "/resources?group=project", note: "ORPHAN. Becomes a grouping filter on the inventory, not a hidden page." },
  { legacy: "/dashboard/domains",            now: "/network/domains" },
  { legacy: "/dashboard/domains/[id]",       now: "/network/domains/[id]" },
  { legacy: "/dashboard/domains/register",   now: "/deploy?product=domain" },
  { legacy: "/dashboard/domains/transfer",   now: "/network/domains?action=transfer" },
  { legacy: "/dashboard/domains/ideas",      now: "/network/domains?action=ideas" },
  { legacy: "/dashboard/ssl",                now: "/network/ssl", note: "Moved under Network: a certificate is an attribute of a domain, not a product." },
  { legacy: "/dashboard/mail",               now: "/network/inbox" },
  { legacy: "/dashboard/email",              now: "/network/mailboxes", note: "Renamed: the production name collided with Inbox six different ways." },
  { legacy: "/dashboard/build",              now: "/build" },
  { legacy: "/dashboard/claude-code",        now: "/build?tab=guides", note: "Merged. In production the two AI entries had labels swapped against their URLs." },
  { legacy: "/dashboard/billing",            now: "/account/billing" },
  { legacy: "/dashboard/invoices",           now: "/account/billing?tab=invoices", note: "ORPHAN. Now a real Billing tab, which the production nav already claimed but never did." },
  { legacy: "/dashboard/invoices/[id]",      now: "/account/billing/invoice/[id]" },
  { legacy: "/dashboard/team",               now: "/account/team" },
  { legacy: "/dashboard/team/accept",        now: "/account/team?invite=accept" },
  { legacy: "/dashboard/support",            now: "/account/support" },
  { legacy: "/dashboard/support/[id]",       now: "/account/support/[id]" },
  { legacy: "/dashboard/feedback",           now: "/account/support?tab=feedback", note: "ORPHAN. Folded into Support." },
  { legacy: "/dashboard/activity",           now: "/account/activity" },
  { legacy: "/dashboard/settings",           now: "/account/settings" },
  { legacy: "/dashboard/refer",              now: "/account/settings?tab=referrals" },
  { legacy: "/dashboard/affiliate",          now: "/account/settings?tab=referrals", note: "ORPHAN. Same code and same reward as Refer — merged rather than shown twice." },
  { legacy: "/dashboard/partner",            now: "/account/settings?tab=partner" },
  { legacy: "/dashboard/migrate",            now: "/account/migration" },
  { legacy: "/dashboard/migrate/consolidate", now: "/account/migration?mode=consolidate" },
  { legacy: "/dashboard/tools",              now: "/tools", note: "Demoted from the sidebar; still reachable and fully indexed in the command palette." },
  { legacy: "/dashboard/whats-new",          now: "/whats-new" },
  { legacy: "/dashboard/calendar",           now: "/network/inbox?view=calendar", note: "Flag-gated off in production; kept reachable rather than deleted." },
];

/* Flatten for lookup. */
export const ALL_NAV: NavLeaf[] = [...NAV.flatMap((s) => s.items), ...NAV_FOOTER];

/** Which sidebar item should light for a given path. Longest prefix wins, so
    /resources/vps/atlas-web highlights VPS rather than All resources. */
export function activeNavId(pathname: string): string | undefined {
  let best: NavLeaf | undefined;
  for (const item of ALL_NAV) {
    if (pathname === item.href || pathname.startsWith(item.href + "/")) {
      if (!best || item.href.length > best.href.length) best = item;
    }
  }
  return best?.id;
}
