export type ResourceStatus = "running" | "provisioning" | "stopped" | "suspended" | "error" | "active";

export interface Resource {
  id: string;
  slug: string;
  name: string;
  kind: ResourceKind;
  status: ResourceStatus;
  plan: string;
  region: string;
  address: string;
  project?: string;
  /** Something the customer needs to act on. Drives the Home attention band. */
  attention?: { level: "warning" | "danger"; text: string };
