"use client";

/* ============================================================================
   COMMAND PALETTE
   The production palette indexed eight entity types, offered no actions at
   all, and three of its result types resolved to a list page rather than the
   item — it was a search box wearing a command palette's name.

   This one answers "where is the thing I need?" rather than "search this
   page": every resource kind, every domain, mailboxes, invoices, settings,
   support, the sixteen tools, and real verbs that DO something.
   ========================================================================= */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { Icon, type IconName } from "@/components/system/Icon";
import {
  RESOURCES, DOMAINS, COMMAND_ACTIONS, TOOLS, RECENT_IDS,
  type CommandEntry, type CommandType,
} from "@/lib/estate";
import { ALL_NAV, KINDS } from "@/lib/nav";

const TYPE_LABEL: Record<CommandType, string> = {
  action: "Actions",
  resource: "Resources",
  domain: "Domains",
  mailbox: "Mailboxes",
  invoice: "Billing",
  page: "Go to",
  tool: "Tools",
};
/* Actions lead: a palette that can only navigate is a worse search box. */
const TYPE_ORDER: CommandType[] = ["action", "resource", "domain", "mailbox", "invoice", "page", "tool"];

function buildIndex(): CommandEntry[] {
  const out: CommandEntry[] = [...COMMAND_ACTIONS];

  for (const r of RESOURCES) {
    out.push({
      id: `res-${r.id}`, type: "resource", label: r.name,
      hint: `${KINDS[r.kind].singular} · ${r.region}`,
      href: `/resources/${r.kind}/${r.slug}`,
      icon: KINDS[r.kind].icon, keywords: `${r.address} ${r.plan} ${r.project ?? ""}`,
    });
  }
  for (const d of DOMAINS) {
    out.push({
      id: `dom-${d.id}`, type: "domain", label: d.name, hint: `Expires ${d.expires}`,
      href: `/network/domains/${d.name}`, icon: "domains", keywords: "dns nameserver renew",
    });
  }
  out.push(
    { id: "mb-1", type: "mailbox", label: "hello@example.nx",  hint: "Mailbox · 2.1 GB used", href: "/network/mailboxes", icon: "mailbox", keywords: "email inbox" },
    { id: "mb-2", type: "mailbox", label: "billing@example.nx", hint: "Mailbox · 0.4 GB used", href: "/network/mailboxes", icon: "mailbox", keywords: "email inbox" },
    { id: "inv-1", type: "invoice", label: "Invoice NX-10428", hint: "$65.44 · paid", href: "/account/billing?tab=invoices", icon: "billing", keywords: "receipt payment" },
    { id: "inv-2", type: "invoice", label: "Invoice NX-10391", hint: "$22.99 · paid", href: "/account/billing?tab=invoices", icon: "billing", keywords: "receipt payment" },
  );
  for (const n of ALL_NAV) {
    out.push({ id: `nav-${n.id}`, type: "page", label: n.label, href: n.href, icon: n.icon });
  }
  for (const t of TOOLS) {
    out.push({ id: `tool-${t.slug}`, type: "tool", label: t.label, href: `/tools#${t.slug}`, icon: "settings" });
  }
  return out;
}

export function CommandPalette({ open, onClose }: { open: boolean; onClose: () => void }) {
  const router = useRouter();
  const [q, setQ] = useState("");
  const [active, setActive] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);
  const index = useMemo(buildIndex, []);

  useEffect(() => { if (open) { setQ(""); setActive(0); inputRef.current?.focus(); } }, [open]);

  const recents = useMemo(
    () => RECENT_IDS.map((id) => index.find((e) => e.id === `res-${id}` || e.id === `dom-${id}`)).filter(Boolean) as CommandEntry[],
    [index]
  );

  const results = useMemo(() => {
    const term = q.trim().toLowerCase();
    if (!term) return COMMAND_ACTIONS.slice(0, 5);
    return index
      .filter((e) => `${e.label} ${e.hint ?? ""} ${e.keywords ?? ""}`.toLowerCase().includes(term))
      .slice(0, 24);
  }, [q, index]);

  /* Grouped for display, but flat for keyboard: arrow keys move through every
     result in visual order regardless of which category it sits in. */
  const grouped = useMemo(() => {
    const by = new Map<CommandType, CommandEntry[]>();
    for (const r of results) {
      if (!by.has(r.type)) by.set(r.type, []);
      by.get(r.type)!.push(r);
    }
    return TYPE_ORDER.filter((t) => by.has(t)).map((t) => ({ type: t, items: by.get(t)! }));
  }, [results]);

  const flat = useMemo(() => grouped.flatMap((g) => g.items), [grouped]);

  const go = useCallback((e: CommandEntry) => { onClose(); router.push(e.href); }, [onClose, router]);

  useEffect(() => {
    if (!open) return;
    const onKey = (ev: KeyboardEvent) => {
      if (ev.key === "Escape") { ev.preventDefault(); onClose(); }
      else if (ev.key === "ArrowDown") { ev.preventDefault(); setActive((i) => Math.min(i + 1, flat.length - 1)); }
      else if (ev.key === "ArrowUp") { ev.preventDefault(); setActive((i) => Math.max(i - 1, 0)); }
      else if (ev.key === "Home") { ev.preventDefault(); setActive(0); }
      else if (ev.key === "End") { ev.preventDefault(); setActive(flat.length - 1); }
      else if (ev.key === "Enter" && flat[active]) { ev.preventDefault(); go(flat[active]); }
    };
    document.addEventListener("keydown", onKey, true);
    return () => document.removeEventListener("keydown", onKey, true);
  }, [open, flat, active, go, onClose]);

  useEffect(() => {
    listRef.current?.querySelector<HTMLElement>(`[data-idx="${active}"]`)
      ?.scrollIntoView({ block: "nearest" });
  }, [active]);

  if (!open) return null;
  let idx = -1;

  return (
    <div className="fixed inset-0 z-[var(--nx-z-overlay)] flex items-start justify-center px-4 pt-[10vh]">
      <div className="absolute inset-0 bg-scrim/80 animate-nx-fade" onClick={onClose} aria-hidden="true" />
      <div
        role="dialog" aria-modal="true" aria-label="Search and commands"
        className="animate-nx-rise relative flex max-h-[70vh] w-full max-w-xl flex-col overflow-hidden rounded-lg border border-hairline-strong bg-surface shadow-overlay"
      >
        <div className="flex items-center gap-3 border-b border-hairline px-4">
          <Icon name="search" size="lg" className="shrink-0 text-ink-muted" />
          <input
            ref={inputRef}
            value={q}
            onChange={(e) => { setQ(e.target.value); setActive(0); }}
            placeholder="Search resources, domains, billing — or type a command"
            aria-label="Search resources, domains, billing, or type a command"
            aria-controls="nx-cmd-list"
            aria-activedescendant={flat[active] ? `nx-cmd-${flat[active].id}` : undefined}
            role="combobox" aria-expanded
            className="h-14 min-w-0 flex-1 bg-transparent text-body text-ink outline-none placeholder:text-ink-muted"
          />
          <kbd className="hidden shrink-0 rounded-sm border border-hairline-strong bg-plate px-1.5 py-0.5 font-mono text-[0.6875rem] text-ink-muted sm:block">esc</kbd>
        </div>

        <div ref={listRef} id="nx-cmd-list" role="listbox" className="min-h-0 flex-1 overflow-y-auto py-2">
          {!q && recents.length > 0 && (
            <Group label="Recent">
              {recents.map((e) => { idx += 1; const i = idx; return (
                <Row key={e.id} e={e} i={i} active={active === i} onHover={setActive} onPick={go} />
              ); })}
            </Group>
          )}

          {flat.length === 0 ? (
            <div className="px-4 py-10 text-center">
              <Icon name="search" size="lg" className="mx-auto mb-3 text-ink-muted" />
              <p className="text-body-sm text-ink">No matches for “{q}”</p>
              <p className="mx-auto mt-1.5 max-w-[42ch] text-caption text-ink-muted">
                Try a resource name, a domain, an invoice number, or a verb such as “deploy” or “add funds”.
              </p>
            </div>
          ) : (
            grouped.map((g) => (
              <Group key={g.type} label={TYPE_LABEL[g.type]}>
                {g.items.map((e) => { idx += 1; const i = idx; return (
                  <Row key={e.id} e={e} i={i} active={active === i} onHover={setActive} onPick={go} />
                ); })}
              </Group>
            ))
          )}
        </div>

        <div className="flex shrink-0 items-center gap-4 border-t border-hairline px-4 py-2 text-caption text-ink-muted">
          <Legend k="↑↓" t="Navigate" /><Legend k="↵" t="Open" /><Legend k="esc" t="Close" />
          <span className="ml-auto hidden sm:inline">{flat.length} result{flat.length === 1 ? "" : "s"}</span>
        </div>
      </div>
    </div>
  );
}

function Group({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div role="group" aria-label={label} className="mb-1">
      <p className="px-4 py-1.5 font-display text-label uppercase tracking-[0.11em] text-ink-muted">{label}</p>
      {children}
    </div>
  );
}

function Row({
  e, i, active, onHover, onPick,
}: { e: CommandEntry; i: number; active: boolean; onHover: (i: number) => void; onPick: (e: CommandEntry) => void }) {
  return (
    <button
      type="button" role="option" id={`nx-cmd-${e.id}`} data-idx={i} aria-selected={active}
      onMouseEnter={() => onHover(i)} onClick={() => onPick(e)}
      className={`flex w-full items-center gap-3 px-4 py-2.5 text-left transition-colors duration-[var(--nx-dur-1)] ${
        active ? "bg-interactive" : ""
      }`}
    >
      <Icon name={e.icon as IconName} size="md" className={active ? "text-signal-text" : "text-ink-muted"} />
      <span className="min-w-0 flex-1 truncate text-body-sm text-ink">{e.label}</span>
      {e.hint && <span className="hidden shrink-0 font-mono text-caption text-ink-muted sm:block">{e.hint}</span>}
      {e.type === "action" && (
        <span className="shrink-0 rounded-sm border border-signal-edge/40 px-1.5 py-0.5 font-display text-[0.625rem] uppercase tracking-[0.09em] text-signal-text">
          Run
        </span>
      )}
    </button>
  );
}

function Legend({ k, t }: { k: string; t: string }) {
  return (
    <span className="inline-flex items-center gap-1.5">
      <kbd className="rounded-sm border border-hairline-strong bg-plate px-1.5 py-0.5 font-mono text-[0.6875rem]">{k}</kbd>
      <span className="hidden sm:inline">{t}</span>
    </span>
  );
}
