"use client";

/* ============================================================================
   SIDEBAR
   Rebuilt on the Phase 1 IA rather than restyled. Three differences from the
   production rail that matter:

   1. It is grouped by what the customer is doing — create, own, administer —
      not by product name, so nobody has to work out which items are products
      and which are account functions.
   2. It adapts to the estate. Resource kinds the customer owns are pinned as
      children; kinds they do not own are absent and live under Deploy. A
      one-VPS customer does not carry the same 21 rows as an estate customer.
   3. The active state is carried by four signals at once — a gradient edge
      marker, an elevated surface, a signal-coloured icon and heavier weight —
      so it never depends on a subtle background alone, or on colour alone.
   ========================================================================= */

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useEffect, useState } from "react";
import { Icon } from "@/components/system/Icon";
import { IconButton } from "@/components/system/controls";
import { NAV, NAV_FOOTER, activeNavId, type NavLeaf } from "@/lib/nav";
import { OWNED_KINDS, RESOURCES, NOTIFICATIONS } from "@/lib/estate";

/* Counts shown against nav rows. Derived, never hand-maintained. */
function badgeFor(id: string): number | undefined {
  const byKind = (k: string) => RESOURCES.filter((r) => r.kind === k).length || undefined;
  switch (id) {
    case "resources": return RESOURCES.length;
    case "r-vps": return byKind("vps");
    case "r-game": return byKind("game");
    case "r-hosting": return byKind("hosting");
    case "r-site": return byKind("site");
    case "r-volume": return byKind("volume");
    case "r-nxcloud": return byKind("nxcloud");
    case "r-freemc": return byKind("freemc");
    case "inbox": return 3;
    case "support": return NOTIFICATIONS.filter((n) => !n.read && n.kind === "billing").length || undefined;
    default: return undefined;
  }
}

/** Owned-only rows disappear entirely when the customer owns none of that kind. */
function visible(item: NavLeaf): boolean {
  if (!item.ownedOnly) return true;
  const kind = item.id.replace(/^r-/, "");
  return (OWNED_KINDS as string[]).includes(kind);
}

export function Sidebar({
  collapsed, onToggleCollapse, onCloseMobile, mobileOpen,
}: {
  collapsed: boolean;
  onToggleCollapse: () => void;
  onCloseMobile: () => void;
  mobileOpen: boolean;
}) {
  const pathname = usePathname();
  const activeId = activeNavId(pathname);
  const [folded, setFolded] = useState<Record<string, boolean>>({});

  /* Close the drawer on route change — a drawer that survives navigation
     leaves the customer looking at the menu they just used. */
  useEffect(() => { onCloseMobile(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [pathname]);

  return (
    <aside
      id="nx-rail"
      aria-label="Primary"
      className={`fixed inset-y-0 left-0 z-[var(--nx-z-rail)] flex w-64 flex-col border-r border-hairline bg-surface
        transition-transform duration-[var(--nx-dur-3)] ease-[var(--nx-ease)]
        ${mobileOpen ? "translate-x-0" : "-translate-x-full"}
        lg:sticky lg:top-0 lg:h-dvh lg:translate-x-0 ${collapsed ? "lg:w-[4.75rem]" : "lg:w-64"}`}
    >
      {/* Brand */}
      <div className="flex h-14 shrink-0 items-center gap-2.5 border-b border-hairline px-4">
        <Link href="/home" className="flex min-w-0 items-center gap-2.5 rounded-md" aria-label="Nxeon, go to home">
          <NxeonMark />
          {!collapsed && <span className="truncate font-display text-h4 font-bold tracking-[-0.01em] text-ink">Nxeon</span>}
        </Link>
        <div className="ml-auto lg:hidden">
          <IconButton name="close" label="Close navigation" size="sm" onClick={onCloseMobile} />
        </div>
      </div>

      <nav aria-label="Sections" className="min-h-0 flex-1 overflow-y-auto px-2.5 py-3">
        {NAV.map((section, si) => {
          const items = section.items.filter(visible);
          if (items.length === 0) return null;
          const key = section.label ?? `s${si}`;
          const isFolded = Boolean(folded[key]);

          return (
            <div key={key} className="mb-4 last:mb-0">
              {section.label && !collapsed && (
                <button
                  type="button"
                  onClick={() => setFolded((f) => ({ ...f, [key]: !f[key] }))}
                  aria-expanded={!isFolded}
                  className="group mb-1 flex w-full items-center gap-1.5 rounded-md px-2 py-1 text-left font-display text-label uppercase tracking-[0.13em] text-ink-muted transition-colors duration-[var(--nx-dur-1)] hover:text-ink-secondary"
                >
                  <Icon
                    name="chevronDown" size="sm"
                    className={`transition-transform duration-[var(--nx-dur-1)] ${isFolded ? "-rotate-90" : ""}`}
                  />
                  <span>{section.label}</span>
                </button>
              )}
              {section.label && collapsed && <div className="mx-2 mb-2 h-px bg-hairline" />}

              {!isFolded && (
                <ul className="flex flex-col gap-0.5">
                  {items.map((item) => (
                    <li key={item.id}>
                      <Row item={item} active={item.id === activeId} collapsed={collapsed} badge={badgeFor(item.id)} />
                    </li>
                  ))}
                </ul>
              )}
            </div>
          );
        })}
      </nav>

      {/* Footer: utilities that do not earn a permanent product row */}
      <div className="shrink-0 border-t border-hairline p-2.5">
        <ul className="mb-1 flex flex-col gap-0.5">
          {NAV_FOOTER.map((item) => (
            <li key={item.id}>
              <Row item={item} active={item.id === activeId} collapsed={collapsed} muted />
            </li>
          ))}
        </ul>
        <button
          type="button"
          onClick={onToggleCollapse}
          aria-label={collapsed ? "Expand navigation" : "Collapse navigation"}
          className={`hidden w-full items-center gap-2.5 rounded-md px-3 py-2 font-display text-caption font-medium text-ink-muted transition-colors duration-[var(--nx-dur-1)] hover:bg-interactive hover:text-ink lg:flex ${
            collapsed ? "justify-center px-0" : ""
          }`}
        >
          <Icon name="collapse" size="md" className={collapsed ? "rotate-180" : ""} />
          {!collapsed && <span>Collapse</span>}
        </button>
      </div>
    </aside>
  );
}

