import { Sidebar } from "./Sidebar";
import { TopBar } from "./TopBar";
import { CommandPalette } from "./CommandPalette";
import { WORKSPACES, type Workspace } from "@/lib/estate";
import { activeNavId } from "@/lib/nav";

const BOTTOM = [
  { id: "home",      label: "Home",      href: "/home",      icon: "home" as const },
  { id: "resources", label: "Resources", href: "/resources", icon: "resources" as const },
  { id: "deploy",    label: "Deploy",    href: "/deploy",    icon: "deploy" as const },
  { id: "billing",   label: "Billing",   href: "/account/billing", icon: "billing" as const },
];

export function PortalShell({ children }: { children: ReactNode }) {
  const pathname = usePathname();
  const activeId = activeNavId(pathname);
  const [collapsed, setCollapsed] = useState(false);
  const [mobileNav, setMobileNav] = useState(false);
  const [palette, setPalette] = useState(false);
  const [workspace, setWorkspace] = useState<Workspace>(WORKSPACES[0]);

  /* Remember the rail state across navigations and reloads. */
  useEffect(() => {
    try { setCollapsed(localStorage.getItem("nx.rail.collapsed") === "1"); } catch { /* private mode */ }
  }, []);
  const toggleCollapse = useCallback(() => {
    setCollapsed((c) => {
      try { localStorage.setItem("nx.rail.collapsed", c ? "0" : "1"); } catch { /* ignore */ }
      return !c;
