"use client";

/* ============================================================================
   PAGE SHELL — the one page contract
   In production 34 routes used one header component, 4 used another, 2 used
   none, 1 a bare heading and 1 an aria-hidden void painted over by a floating
   panel, with six different h1 recipes between them. Every page in the
   redesign takes this and only this.

   It carries breadcrumb, title, description, status, primary action,
   secondary actions and an overflow menu, and it supplies the layout
   primitives beneath so a table page, a form page and a dashboard do not each
   invent their own geometry.
   ========================================================================= */

import Link from "next/link";
import { useEffect, useRef, useState, type ReactNode } from "react";
import { Icon } from "@/components/system/Icon";
import { StatusIndicator, STATUS_TONE } from "@/components/system/primitives";

export interface Crumb { label: string; href?: string }

export interface OverflowItem { label: string; onSelect?: () => void; tone?: "default" | "danger" }

export function PageShell({
  crumbs, title, description, status, meta, primary, secondary, overflow, tabs, children,
}: {
  crumbs?: Crumb[];
  title: string;
  description?: string;
  status?: keyof typeof STATUS_TONE;
  meta?: ReactNode;
  /** The single most important thing on the page. One only. */
  primary?: ReactNode;
  secondary?: ReactNode;
  overflow?: OverflowItem[];
  tabs?: ReactNode;
  children: ReactNode;
}) {
  return (
    <>
      <header className="mb-5">
        {crumbs && crumbs.length > 0 && <Breadcrumbs items={crumbs} />}

        <div className="mt-2 flex flex-wrap items-start justify-between gap-x-6 gap-y-3">
          <div className="min-w-0 max-w-[68ch]">
            <div className="flex flex-wrap items-center gap-x-3 gap-y-1.5">
              <h1 className="text-h1 text-ink">{title}</h1>
              {status && <StatusIndicator status={status} />}
            </div>
            {description && <p className="mt-2 text-body text-ink-secondary">{description}</p>}
            {meta && <div className="mt-3 flex flex-wrap items-center gap-x-5 gap-y-2">{meta}</div>}
          </div>

          {(primary || secondary || overflow) && (
            <div className="flex shrink-0 flex-wrap items-center gap-2">
              {secondary}
              {primary}
              {overflow && overflow.length > 0 && <OverflowMenu items={overflow} />}
            </div>
          )}
        </div>

        {tabs ? <div className="mt-4">{tabs}</div> : <div className="mt-4 h-px bg-hairline" />}
      </header>

      {children}
    </>
  );
}

/* ------------------------------------------------------------- BREADCRUMBS */
/** Establishes where you are. The production portal had no breadcrumb at all,
    which is why a game server opening under "Servers" was so disorienting. */
export function Breadcrumbs({ items }: { items: Crumb[] }) {
  return (
    <nav aria-label="Breadcrumb">
      <ol className="flex flex-wrap items-center gap-1 font-display text-caption">
        {items.map((c, i) => {
          const last = i === items.length - 1;
          return (
            <li key={`${c.label}-${i}`} className="flex items-center gap-1">
              {i > 0 && <Icon name="chevronRight" size="sm" className="text-ink-disabled" aria-hidden="true" />}
              {c.href && !last ? (
                <Link href={c.href} className="rounded-sm text-ink-muted transition-colors duration-[var(--nx-dur-1)] hover:text-ink">
                  {c.label}
                </Link>
              ) : (
                <span className={last ? "font-semibold text-ink-secondary" : "text-ink-muted"} aria-current={last ? "page" : undefined}>
                  {c.label}
                </span>
              )}
            </li>
          );
        })}
      </ol>
    </nav>
  );
}

/* ---------------------------------------------------------- OVERFLOW MENU */
function OverflowMenu({ items }: { items: OverflowItem[] }) {
  const [open, setOpen] = useState(false);
  const wrap = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => { if (wrap.current && !wrap.current.contains(e.target as Node)) setOpen(false); };
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setOpen(false); };
    document.addEventListener("mousedown", onDoc); document.addEventListener("keydown", onKey);
    return () => { document.removeEventListener("mousedown", onDoc); document.removeEventListener("keydown", onKey); };
  }, [open]);

  return (
    <div ref={wrap} className="relative">
      <button
        type="button" onClick={() => setOpen((v) => !v)} aria-expanded={open} aria-haspopup="menu"
        aria-label="More actions"
        className="flex h-10 w-10 items-center justify-center rounded-md border border-hairline-strong bg-interactive text-ink transition-colors duration-[var(--nx-dur-1)] hover:border-signal-edge/50"
      >
        <Icon name="settings" size="md" />
      </button>
      {open && (
        <div role="menu" className="absolute right-0 top-[calc(100%+4px)] z-[var(--nx-z-overlay)] min-w-52 animate-nx-rise rounded-md border border-hairline-strong bg-surface py-1 shadow-overlay">
          {items.map((it) => (
            <button
              key={it.label} role="menuitem" type="button"
              onClick={() => { it.onSelect?.(); setOpen(false); }}
              className={`flex w-full items-center px-3 py-2 text-left text-body-sm transition-colors duration-[var(--nx-dur-1)] hover:bg-interactive ${
                it.tone === "danger" ? "text-danger-text" : "text-ink-secondary hover:text-ink"
              }`}
            >
              {it.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------ LAYOUT PRIMITIVES */
/** A labelled section. The primary grouping device — most sections need no
    border, which is what stops every page becoming a stack of cards. */
export function Section({
  label, action, children, className = "",
}: { label?: string; action?: ReactNode; children: ReactNode; className?: string }) {
  return (
    <section className={`mb-7 last:mb-0 ${className}`}>
      {label && (
        <div className="nx-rule mb-3">
          <span className="nx-rule-label">{label}</span>
          {action && <div className="order-last shrink-0 pl-3">{action}</div>}
        </div>
      )}
      {children}
    </section>
  );
}

/** Main column plus a sidebar of supporting detail. The recurring two-column
    shape for resource pages, checkout and settings. */
export function Split({ children, aside }: { children: ReactNode; aside: ReactNode }) {
  return (
    <div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_320px] lg:items-start">
      <div className="min-w-0">{children}</div>
      <aside className="flex flex-col gap-3 lg:sticky lg:top-20">{aside}</aside>
    </div>
  );
}

/** A reading-width column for prose, forms and settings. */
export function Prose({ children }: { children: ReactNode }) {
  return <div className="max-w-[68ch]">{children}</div>;
}
