"use client";

/* ============================================================================
   SHELL-LEVEL STATES
   Established now so every product page in later phases consumes them instead
   of inventing its own. In production 58 routes shared one loading file and
   one error file, "Something went wrong" appeared eleven times, and there was
   no not-found inside the shell at all — so all eight not-found paths ejected
   the customer to the marketing 404, outside the portal entirely.
   ========================================================================= */

import Link from "next/link";
import { useEffect, useState, type ReactNode } from "react";
import { Icon, type IconName } from "@/components/system/Icon";
import { Button } from "@/components/system/controls";
import { EmptySlot, BrokenPath } from "@/components/system/illustrations";
import { Skeleton } from "@/components/system/states";

/* ------------------------------------------------------------------ FRAME */
function StateFrame({
  art, title, body, actions,
}: { art: ReactNode; title: string; body: string; actions?: ReactNode }) {
  return (
    <div className="nx-container-surface relative flex flex-col items-center overflow-hidden px-6 py-14 text-center">
      <div className="nx-grid-field nx-grid-mask pointer-events-none absolute inset-0" aria-hidden="true" />
      <div className="relative mb-4">{art}</div>
      <h2 className="relative text-h2 text-ink">{title}</h2>
      <p className="relative mt-2 max-w-[52ch] text-body-sm text-ink-secondary">{body}</p>
      {actions && <div className="relative mt-5 flex flex-wrap items-center justify-center gap-2">{actions}</div>}
    </div>
  );
}

/* -------------------------------------------------------------- NOT FOUND */
export function NotFoundState({ what = "page" }: { what?: string }) {
  return (
    <StateFrame
      art={<EmptySlot size={148} />}
      title={`That ${what} does not exist`}
      body={`We could not find the ${what} you asked for. It may have been deleted, or the link may be wrong. Everything else in your account is unaffected.`}
      actions={
        <>
          <Link href="/home"><Button variant="primary" icon="home">Go to Home</Button></Link>
          <Link href="/resources"><Button variant="secondary" icon="resources">View resources</Button></Link>
        </>
      }
    />
  );
}

/* ------------------------------------------------------------------ ERROR */
export function ErrorPageState({
  reason, technical, onRetry,
}: { reason?: string; technical?: string; onRetry?: () => void }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="nx-container-surface px-6 py-12" role="alert">
      <div className="mx-auto flex max-w-[52ch] flex-col items-center text-center">
        <BrokenPath size={148} />
        <h2 className="mt-4 text-h2 text-ink">This page could not load</h2>
        <p className="mt-2 text-body-sm text-ink-secondary">
          {reason ?? "The request did not complete. Nothing was changed, and your resources are still running."}
        </p>
        <p className="mt-2 text-body-sm text-ink-secondary">
          Try again in a moment. If it keeps failing, open a ticket and include the reference below.
        </p>
        <div className="mt-5 flex flex-wrap items-center justify-center gap-2">
          {onRetry && <Button variant="primary" icon="restart" onClick={onRetry}>Try again</Button>}
          <Link href="/account/support"><Button variant="secondary" icon="support">Contact support</Button></Link>
        </div>
        {technical && (
          <div className="mt-5 w-full">
            <button
              type="button" onClick={() => setOpen((v) => !v)} aria-expanded={open}
              className="inline-flex items-center gap-1.5 font-display text-caption font-semibold text-ink-muted transition-colors duration-[var(--nx-dur-1)] hover:text-ink-secondary"
            >
              <Icon name="chevronRight" size="sm" className={`transition-transform ${open ? "rotate-90" : ""}`} />
              View technical details
            </button>
            {open && <pre className="nx-plate mt-2 overflow-x-auto px-3 py-2 text-left text-code text-ink-secondary">{technical}</pre>}
          </div>
        )}
      </div>
    </div>
