}

/* ------------------------------------------------------ PERMISSION DENIED */
export function PermissionDeniedState({ area = "this area" }: { area?: string }) {
  return (
    <StateFrame
      art={<span className="flex h-16 w-16 items-center justify-center rounded-lg border border-hairline-strong bg-plate text-warning-text"><Icon name="firewall" size="lg" /></span>}
      title={`You do not have access to ${area}`}
      body="Your role in this workspace does not include this area. A workspace owner or admin can grant it, or you can switch to a workspace where you have access."
      actions={
        <>
          <Link href="/account/team"><Button variant="primary" icon="account">Ask an admin</Button></Link>
          <Link href="/home"><Button variant="secondary">Back to Home</Button></Link>
        </>
      }
    />
  );
}

/* ---------------------------------------------------------------- OFFLINE */
/** Shell-level, because a dropped connection is not a page's problem to
    solve. It watches the real browser events rather than guessing. */
export function OfflineBanner() {
  const [offline, setOffline] = useState(false);
  useEffect(() => {
    const on = () => setOffline(false), off = () => setOffline(true);
    setOffline(typeof navigator !== "undefined" && !navigator.onLine);
    window.addEventListener("online", on);
    window.addEventListener("offline", off);
    return () => { window.removeEventListener("online", on); window.removeEventListener("offline", off); };
  }, []);
  if (!offline) return null;
  return (
    <div role="status" className="mb-4 flex items-center gap-3 rounded-md border border-y-hairline border-l-2 border-l-warning-text border-r-hairline bg-surface px-4 py-3">
      <Icon name="warning" size="md" className="shrink-0 text-warning-text" />
      <p className="text-body-sm text-ink-secondary">
        <span className="font-semibold text-warning-text">You are offline.</span>{" "}
        Your resources keep running. This page will refresh when the connection returns.
      </p>
    </div>
  );
}

