      {shape === "list" && (
        <div className="flex flex-col gap-2">
          {Array.from({ length: 5 }).map((_, i) => (
            <div key={i} className="nx-object flex items-center gap-4 px-4 py-3.5">
              <Skeleton className="h-8 w-8 rounded-md" />
              <div className="flex flex-1 flex-col gap-2"><Skeleton className="h-3.5 w-40" /><Skeleton className="h-3 w-64" /></div>
              <Skeleton className="h-7 w-20 rounded-md" />
            </div>
          ))}
        </div>
      )}
      {shape === "detail" && (
        <div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_320px]">
          <div className="flex flex-col gap-3"><Skeleton className="h-28" /><Skeleton className="h-56" /></div>
