import { RESOURCES, DOMAINS } from "./estate";
export { RESOURCES, DOMAINS };

/** Everything across the estate that needs the customer to act, in one list. */
export function KIND_ATTENTION() {
  const out: { id: string; level: "warning" | "danger"; title: string; text: string; href: string }[] = [];
  for (const r of RESOURCES) {
    if (r.attention) out.push({ id: r.id, level: r.attention.level, title: r.name, text: r.attention.text, href: `/resources/${r.kind}/${r.slug}` });
  }
  for (const d of DOMAINS) {
    if (d.attention) out.push({ id: d.id, level: "warning", title: d.name, text: d.attention, href: `/network/domains/${d.name}` });
  }
  return out.sort((a, b) => (a.level === "danger" ? -1 : 1) - (b.level === "danger" ? -1 : 1));
}
