                  <Icon name="chevronRight" size="md" className="hidden shrink-0 text-ink-muted sm:block" />
                </div>
              </ObjectSurface>
            </Link>
          ))}
        </div>
      )}

      {!kind && (
        <Section label="Not using these yet">
          <div className="flex flex-wrap gap-2">
            {ORDER.filter((k) => !owned.has(k)).map((k) => (
              <Link key={k} href={`/deploy?product=${k}`}
                className="inline-flex items-center gap-2 rounded-md border border-hairline bg-surface px-3 py-2 text-body-sm text-ink-secondary transition-colors duration-[var(--nx-dur-1)] hover:border-hairline-strong hover:text-ink">
                <Icon name={KINDS[k].icon} size="md" className="text-ink-muted" />
                {KINDS[k].label}
                <Icon name="plus" size="sm" className="text-signal-text" />
              </Link>
            ))}
          </div>
          <p className="mt-2 text-caption text-ink-muted">
            Kinds you do not own stay out of the sidebar. They are one click away here and in Deploy.
          </p>
        </Section>
      )}
    </PageShell>
  );
}

/* --------------------------------------------------- OBJECT DETAIL SHELL */
/** Phase 3 builds the CONTEXT a resource page sits in — breadcrumb, identity,
    tab spine — and nothing else. The panels themselves are Phases 7 to 11. */
export function ResourceContext({ kind, id }: { kind: ResourceKind; id: string }) {
  const r = RESOURCES.find((x) => x.slug === id && x.kind === kind);
  if (!r) {
    return (
      <PageShell crumbs={[{ label: "Nxeon", href: "/home" }, { label: "Resources", href: "/resources" }, { label: KINDS[kind].label, href: `/resources/${kind}` }, { label: id }]}
        title={id} description="This resource does not exist in this workspace.">
        <PhasePlaceholder area="Resource detail" icon={KINDS[kind].icon}
          capabilities={["not found", "check the address", "return to the inventory"]} />
      </PageShell>
    );
  }

  const CAPS: Record<ResourceKind, string[]> = {
    vps: ["Overview", "Console", "Files", "Networking", "Storage", "Backups", "Snapshots", "Security", "Metrics", "Activity", "Settings", "Danger"],
    game: ["Overview", "Console", "Players", "Worlds", "Mods", "Backups", "Schedules", "Files", "Settings", "Activity", "Danger"],
    hosting: ["Overview", "Websites", "Files", "Databases", "Domains", "Email", "Apps", "Cron", "Backups", "Settings"],
    site: ["Editor", "Pages", "Assets", "Versions", "Domain", "Publish"],
    volume: ["Overview", "Attach", "Resize", "Snapshots", "Danger"],
    nxcloud: ["Overview", "Storage", "Users", "Apps", "Settings"],
    freemc: ["Overview", "Console", "Players", "Roles", "Settings", "Upgrade"],
  };

  return (
    <PageShell
      crumbs={[
        { label: "Nxeon", href: "/home" },
        { label: "Resources", href: "/resources" },
        { label: KINDS[kind].label, href: `/resources/${kind}` },
        { label: r.name },
      ]}
      title={r.name}
      status={r.status}
      description={`${KINDS[kind].singular} in ${r.region}.`}
      meta={
        <>
          <Meta label="Plan" value={r.plan} />
          <Meta label="Region" value={r.region} />
          <Meta label="Address" value={r.address} mono />
        </>
      }
      secondary={<Button variant="secondary" icon="console">Console</Button>}
      primary={<Button variant="primary" icon="restart">Restart</Button>}
      overflow={[{ label: "Rename" }, { label: "Move to project" }, { label: "Destroy", tone: "danger" }]}
    >
      <PhasePlaceholder area={`${KINDS[kind].singular} management`} icon={KINDS[kind].icon} capabilities={CAPS[kind]} />
    </PageShell>
  );
}

function Meta({ label, value, mono }: { label: string; value: string; mono?: boolean }) {
  return (
    <span className="flex items-baseline gap-2">
      <span className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">{label}</span>
      <span className={`text-body-sm text-ink-secondary ${mono ? "font-mono" : ""}`}>{value}</span>
    </span>
  );
}
