export default function DeployPage() {
  const [openId, setOpenId] = useState<string | null>(null);
  const [planId, setPlanId] = useState<string | null>(null);
  const [term, setTerm] = useState<Term>("annual");

  const product = PRODUCTS.find((p) => p.id === openId) ?? null;
  const plan = product?.plans?.find((p) => p.id === planId) ?? product?.plans?.find((p) => p.popular) ?? product?.plans?.[0] ?? null;
  const t = TERMS.find((x) => x.id === term)!;

  const money = useMemo(() => {
    if (!plan) return null;
    const rate = plan.price * (1 - t.off);
    return {
      rate,
      dueToday: rate * t.months,
      renewal: plan.price,
      savedPerYear: (plan.price - rate) * 12,
    };
  }, [plan, t]);

  return (
    <PageShell
      crumbs={[{ label: "Nxeon", href: "/home" }, { label: "Deploy" }]}
