          <dl className="grid shrink-0 grid-cols-2 gap-x-8 gap-y-3">
            {[["9", "products"], ["8", "regions"], ["30-day", "money back"], ["24/7", "support"]].map(([v, l]) => (
              <div key={l}>
                <dt className="font-display text-metric tabular-nums text-ink">{v}</dt>
                <dd className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">{l}</dd>
