      </div>

      {/* -------------------------------------------------------- PRODUCTS */}
      <div className="nx-rule mb-3"><span className="nx-rule-label">Choose a product</span></div>
      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
