                    <ul className="mt-3 flex flex-col gap-1 border-t border-hairline pt-3">
                      {pl.specs.map((sp) => (
                        <li key={sp} className="font-mono text-caption text-ink-secondary">{sp}</li>
                      ))}
                    </ul>
                  </button>
                );
              })}
            </div>

            {/* Term ladder — both numbers, always */}
            <div className="nx-rule mb-3 mt-6"><span className="nx-rule-label">Billing term</span></div>
            <div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-4">
