                          : "border border-signal-edge/45 text-signal-text"
                      }`}>
                        {tt.tag}
                      </span>
                    )}
                    <p className="pl-1 font-display text-h4 text-ink">{tt.label}</p>
                    <div className="mt-1.5 flex items-baseline gap-1.5 pl-1">
                      <span className="font-display text-metric-sm tabular-nums text-ink">${rate.toFixed(2)}</span>
                      <span className="text-caption text-ink-muted">/mo</span>
                      {tt.off > 0 && (
                        <span className="ml-1 rounded-sm bg-success/25 px-1.5 py-0.5 font-mono text-[0.6875rem] text-success-text">
                          −{Math.round(tt.off * 100)}%
                        </span>
                      )}
                    </div>
                    <p className="mt-1 pl-1 text-caption text-ink-muted">
                      {tt.off > 0
                        ? <>Save ${save.toFixed(2)} over {tt.months / 12} yr</>
                        : <>Flexible — cancel any time</>}
                    </p>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Running total. It never leaves the screen while you choose. */}
          <div className="sticky bottom-0 flex flex-wrap items-center justify-between gap-3 border-t border-hairline bg-surface/95 px-5 py-3.5 backdrop-blur">
            <div className="min-w-0">
              <p className="flex items-baseline gap-2">
                <span className="font-display text-metric tabular-nums text-ink">${money.dueToday.toFixed(2)}</span>
                <span className="text-caption text-ink-muted">due today</span>
              </p>
              <p className="mt-0.5 text-caption text-ink-muted">
                {product.label} · {plan.name} · {t.label.toLowerCase()} · then ${money.renewal.toFixed(2)}/mo
                {t.off > 0 && <span className="text-success-text"> · saving ${money.savedPerYear.toFixed(2)} a year</span>}
              </p>
            </div>
            <Link href={`/deploy?product=${product.id}&plan=${plan.id}&term=${term}`}>
              <Button variant="deploy" size="lg" iconRight="arrowRight">Configure and pay</Button>
            </Link>
