  { id: "site",    label: "Website builder", icon: "files",      token: "--color-p-site",    from: "Included", note: "No server needed" },
  { id: "nxcloud", label: "NxCloud",         icon: "datacenter", token: "--color-p-cloud",   from: "$5.00/mo", note: "Managed Nextcloud" },
  { id: "freemc",  label: "Free Minecraft",  icon: "game",       token: "--color-p-free",    from: "Free",     note: "Sleeps when idle" },
];

export default function DeployPage() {
  const [openId, setOpenId] = useState<string | null>("vps");
  const [planId, setPlanId] = useState<string | null>(null);
  const [term, setTerm] = useState<Term>("annual");
  const [domain, setDomain] = useState("");

  const product = PRODUCTS.find((p) => p.id === openId) ?? null;
  const plan = product?.plans?.find((p) => p.id === planId)
    ?? product?.plans?.find((p) => p.popular)
    ?? product?.plans?.[0] ?? null;
  const t = TERMS.find((x) => x.id === term)!;

  const money = useMemo(() => {
    if (!plan) return null;
    const rate = plan.price * (1 - t.off);
    return { rate, dueToday: rate * t.months, renewal: plan.price, savedPerYear: (plan.price - rate) * 12 };
  }, [plan, t]);

  return (
    <PageShell
      crumbs={[{ label: "Nxeon", href: "/home" }, { label: "Deploy" }]}
      title="Deploy"
      description="Four guided flows for the things most people buy, and everything else one click away. Each wizard asks only what sets the price — the rest you set afterwards and can change any time."
    >
      {/* ------------------------------------------------------------ HERO */}
      <div className="nx-hero nx-container-surface nx-glow-hero relative mb-6 overflow-hidden">
        <span className="nx-grad-rule absolute inset-x-0 top-0 z-10" aria-hidden="true" />
        <div className="nx-grid-field nx-grid-mask pointer-events-none absolute inset-0" aria-hidden="true" />
        <NodeField />
        <div className="relative flex flex-wrap items-center gap-6 px-6 py-8">
          <div className="min-w-64 flex-1">
            <p className="font-display text-label uppercase tracking-[0.16em] text-ink-muted">Nxeon · Deploy</p>
            <h2 className="mt-2 text-display">Live in <span className="nx-grad-text">47 seconds</span></h2>
            <p className="mt-2 max-w-[54ch] text-body text-ink-secondary">
              Pick a product and a plan. We size it, provision it and hand you the connection details.
              Everything else has a sensible default you can change at any time.
            </p>
          </div>
          <dl className="grid shrink-0 grid-cols-2 gap-x-8 gap-y-3">
            {[["4", "guided flows"], ["8", "regions"], ["30-day", "money back"], ["24/7", "support"]].map(([v, l]) => (
              <div key={l}>
                <dt className="font-display text-metric tabular-nums text-ink">{v}</dt>
                <dd className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">{l}</dd>
              </div>
            ))}
          </dl>
        </div>
      </div>

      {/* -------------------------------------------------- THE FOUR FLOWS */}
      <div className="nx-rule mb-3"><span className="nx-rule-label">Choose a product</span></div>
      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
        {PRODUCTS.map((p) => {
          const on = p.id === openId;
          return (
            <button
              key={p.id} type="button" aria-expanded={on}
              onClick={() => { setOpenId(on ? null : p.id); setPlanId(null); }}
              style={{ ["--p" as string]: `var(${p.token})` }}
              className={`nx-object nx-p-card nx-p-edge overflow-hidden px-4 py-4 text-left ${
                on ? "!border-[color-mix(in_srgb,var(--p)_55%,transparent)]" : ""
              }`}
            >
              <div className="flex items-start justify-between gap-2 pl-1.5">
                <span className="nx-p-tile flex h-10 w-10 shrink-0 items-center justify-center rounded-md">
                  <Icon name={p.icon} size="lg" />
                </span>
                {p.tag && <Badge size="sm" tone={p.tagTone ?? "signal"}>{p.tag}</Badge>}
              </div>
              <p className="mt-3 pl-1.5 font-display text-h3 text-ink">{p.label}</p>
              <p className="mt-1 pl-1.5 text-caption text-ink-secondary">{p.blurb}</p>
              <div className="mt-4 flex items-baseline gap-2 border-t border-hairline pl-1.5 pt-3">
                <span className="font-display text-label uppercase tracking-[0.11em] text-ink-muted">from</span>
                <span className="font-display text-metric-sm tabular-nums" style={{ color: "var(--p)" }}>{p.from}</span>
                <span className="ml-auto inline-flex items-center gap-1 font-display text-caption font-semibold" style={{ color: "var(--p)" }}>
                  {on ? "Hide" : p.search ? "Search" : "See plans"}
                  <Icon name="chevronDown" size="sm" className={on ? "rotate-180 transition-transform" : "transition-transform"} />
                </span>
              </div>
            </button>
          );
        })}
      </div>

      {/* --------------------------------------------- PLANS (compute-like) */}
      {product?.plans && plan && money && (
        <div style={{ ["--p" as string]: `var(${product.token})` }}
          className="nx-container-surface nx-p-edge relative mt-4 animate-nx-rise overflow-hidden">
          <div className="px-5 py-5">
            <div className="flex flex-wrap items-center gap-3">
              <span className="nx-p-tile flex h-8 w-8 items-center justify-center rounded-md"><Icon name={product.icon} size="md" /></span>
              <h3 className="text-h3 text-ink">{product.label} plans</h3>
              <span className="ml-auto text-caption text-ink-muted">Change plan any time, up or down.</span>
            </div>

            <div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
              {product.plans.map((pl) => {
                const on = pl.id === plan.id;
                const rate = pl.price * (1 - t.off);
                return (
                  <button key={pl.id} type="button" onClick={() => setPlanId(pl.id)} aria-pressed={on}
                    className={`nx-object nx-object-interactive ${on ? "nx-object-selected" : ""} px-4 pb-4 pt-3.5 text-left`}>
                    <div className="flex items-center justify-between gap-2">
                      <span className="font-display text-h4 text-ink">{pl.name}</span>
                      {pl.popular && (
                        <span className="nx-grad-brand rounded-sm px-1.5 py-0.5 font-display text-[0.625rem] font-semibold uppercase tracking-[0.09em] text-white">Popular</span>
                      )}
                    </div>
                    <div className="mt-2.5 flex items-baseline gap-1">
                      <span className="font-display text-metric tabular-nums text-ink">${rate.toFixed(2)}</span>
                      <span className="text-caption text-ink-muted">/mo</span>
                    </div>
                    {t.off > 0 && (
                      <p className="mt-0.5 text-caption text-ink-muted">
                        <span className="line-through">${pl.price.toFixed(2)}</span> then ${pl.price.toFixed(2)}/mo
                      </p>
                    )}
                    <ul className="mt-3 flex flex-col gap-1 border-t border-hairline pt-3">
                      {pl.specs.map((sp) => <li key={sp} className="font-mono text-caption text-ink-secondary">{sp}</li>)}
                    </ul>
                  </button>
                );
              })}
            </div>

            <div className="nx-rule mb-3 mt-6"><span className="nx-rule-label">Billing term</span></div>
            <div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-4">
              {TERMS.map((tt) => {
                const on = tt.id === term;
                const rate = plan.price * (1 - tt.off);
                const save = (plan.price - rate) * tt.months;
                return (
                  <button key={tt.id} type="button" onClick={() => setTerm(tt.id)} aria-pressed={on}
                    className={`nx-object nx-object-interactive ${on ? "nx-object-selected" : ""} relative px-4 pb-3.5 pt-3 text-left`}>
                    {tt.tag && (
                      <span className={`absolute right-3 top-3 rounded-sm px-1.5 py-0.5 font-display text-[0.625rem] font-semibold uppercase tracking-[0.09em] ${
                        tt.tag === "Best value" ? "border border-success-text/45 text-success-text" : "border border-signal-edge/45 text-signal-text"
                      }`}>{tt.tag}</span>
                    )}
                    <p className="pl-1 font-display text-h4 text-ink">{tt.label}</p>
                    <div className="mt-1.5 flex items-baseline gap-1.5 pl-1">
                      <span className="font-display text-metric-sm tabular-nums text-ink">${rate.toFixed(2)}</span>
                      <span className="text-caption text-ink-muted">/mo</span>
                      {tt.off > 0 && (
                        <span className="ml-1 rounded-sm bg-success/25 px-1.5 py-0.5 font-mono text-[0.6875rem] text-success-text">−{Math.round(tt.off * 100)}%</span>
                      )}
                    </div>
                    <p className="mt-1 pl-1 text-caption text-ink-muted">
                      {tt.off > 0 ? <>Save ${save.toFixed(2)} over {tt.months / 12} yr</> : <>Flexible — cancel any time</>}
                    </p>
                  </button>
                );
              })}
            </div>
          </div>

          <div className="sticky bottom-0 flex flex-wrap items-center justify-between gap-3 border-t border-hairline bg-surface/95 px-5 py-3.5 backdrop-blur">
            <div className="min-w-0">
              <p className="flex items-baseline gap-2">
                <span className="font-display text-metric tabular-nums text-ink">${money.dueToday.toFixed(2)}</span>
                <span className="text-caption text-ink-muted">due today</span>
              </p>
              <p className="mt-0.5 text-caption text-ink-muted">
                {product.label} · {plan.name} · {t.label.toLowerCase()} · then ${money.renewal.toFixed(2)}/mo
                {t.off > 0 && <span className="text-success-text"> · saving ${money.savedPerYear.toFixed(2)} a year</span>}
              </p>
            </div>
            <Link href={`/deploy?product=${product.id}&plan=${plan.id}&term=${term}`}>
              <Button variant="deploy" size="lg" iconRight="arrowRight">Configure and pay</Button>
            </Link>
          </div>
        </div>
      )}

      {/* ------------------------------------------------- DOMAIN: A SEARCH */}
      {product?.search && (
        <div style={{ ["--p" as string]: `var(${product.token})` }}
          className="nx-container-surface nx-p-edge relative mt-4 animate-nx-rise overflow-hidden">
          <div className="nx-grid-field nx-grid-mask pointer-events-none absolute inset-0" aria-hidden="true" />
          <div className="relative px-5 py-6">
            <div className="mx-auto max-w-2xl text-center">
              <h3 className="text-h2 text-ink">Find your domain</h3>
              <p className="mx-auto mt-1.5 max-w-[48ch] text-body-sm text-ink-secondary">
