              <div className="mt-4 flex gap-2">
                <Input value={domain} onChange={(e) => setDomain(e.target.value)}
                  placeholder="yourbrand" aria-label="Search for a domain name" className="h-12 text-body" />
                <Button variant="deploy" size="lg" icon="search">Search</Button>
              </div>
            </div>

            <div className="nx-rule mb-3 mt-7"><span className="nx-rule-label">Pricing</span></div>
            <p className="mb-3 max-w-[68ch] text-caption text-ink-muted">
              Registration, renewal and transfer side by side. Renewal shock is the biggest trust
              failure in this category, so the second-year price is never hidden.
            </p>
            <div className="overflow-x-auto rounded-lg border border-hairline">
              <table className="w-full border-collapse text-body-sm">
                <thead>
                  <tr className="border-b border-hairline bg-surface">
                    {["Extension", "Register", "Renew", "Transfer"].map((h, i) => (
                      <th key={h} scope="col" className={`px-4 py-2.5 font-display text-label uppercase tracking-[0.11em] text-ink-muted ${i ? "text-right" : "text-left"}`}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {TLDS.map((r) => (
                    <tr key={r.tld} className="border-b border-hairline last:border-0">
                      <td className="px-4 py-2.5">
                        <span className="inline-flex items-center gap-2">
                          <span className="font-mono text-code" style={{ color: "var(--p)" }}>{r.tld}</span>
                          {r.popular && <Badge size="sm" tone="success">Popular</Badge>}
                        </span>
                      </td>
                      <td className="px-4 py-2.5 text-right font-mono tabular-nums text-ink">${r.register.toFixed(2)}</td>
                      <td className="px-4 py-2.5 text-right font-mono tabular-nums text-ink-secondary">${r.renew.toFixed(2)}</td>
                      <td className="px-4 py-2.5 text-right font-mono tabular-nums text-ink-secondary">${r.transfer.toFixed(2)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <p className="mt-3 text-caption text-ink-muted">
              All prices per year. WHOIS privacy, DNS hosting and auto-renew are included at no charge.
            </p>
          </div>
        </div>
      )}

      {/* ------------------------------------------------ ALSO AVAILABLE */}
      <div className="nx-rule mb-3 mt-7"><span className="nx-rule-label">Also available</span></div>
      <div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-5">
        {ALSO.map((a) => (
          <Link key={a.id} href={`/deploy?product=${a.id}`}
            style={{ ["--p" as string]: `var(${a.token})` }}
            className="nx-object nx-p-card flex items-center gap-3 px-3.5 py-3">
            <span className="nx-p-tile flex h-8 w-8 shrink-0 items-center justify-center rounded-md">
              <Icon name={a.icon} size="md" />
            </span>
            <span className="min-w-0 flex-1">
              <span className="block truncate font-display text-body-sm font-semibold text-ink">{a.label}</span>
              <span className="block truncate text-caption text-ink-muted">{a.note}</span>
            </span>
            <span className="shrink-0 font-mono text-caption" style={{ color: "var(--p)" }}>{a.from}</span>
          </Link>
        ))}
      </div>

      {/* ----------------------------------------------------------- TRUST */}
      <div className="mt-6 grid gap-px overflow-hidden rounded-lg border border-hairline bg-hairline sm:grid-cols-2 xl:grid-cols-4">
        {[
          { icon: "firewall" as const, t: "30-day money back", s: "Try any plan risk-free." },
          { icon: "activity" as const, t: "99.9% uptime",       s: "Backed by a written guarantee." },
          { icon: "support" as const,  t: "24/7 expert support", s: "Real engineers, not a script." },
          { icon: "deploy" as const,   t: "Instant setup",      s: "Most servers are live in minutes." },
        ].map((f) => (
          <div key={f.t} className="flex items-start gap-3 bg-surface px-4 py-3.5">
            <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md border border-hairline-strong bg-plate text-signal-text">
              <Icon name={f.icon} size="md" />
            </span>
            <span className="min-w-0">
              <span className="block font-display text-body-sm font-semibold text-ink">{f.t}</span>
              <span className="mt-0.5 block text-caption text-ink-muted">{f.s}</span>
            </span>
          </div>
        ))}
      </div>
    </PageShell>
  );
}
